const _reproParams = (typeof window !== "undefined") ? reproParams.parseReproParams() : { seed: null, cam: null, preset: null };
if (typeof window !== "undefined") {
    try { if (_reproParams.seed != null) localStorage.setItem("voxelengine.worldSeed_v1", String(_reproParams.seed | 0)); } catch {}
    reproParams.applySeedEarly(_reproParams);
    window.repro = {
        params: () => _reproParams,
        link: () => reproParams.buildReproLink(window.camera),
        presets: () => reproParams.listPresets(),
        copy: () => { const u = reproParams.buildReproLink(window.camera); try { navigator.clipboard.writeText(u); } catch {} console.log("[repro] " + u); return u; },
    };
}
if (typeof window !== "undefined") {
    window.ENGINE_VERSION = ENGINE_VERSION;
    try { document.title = "SweK Engine " + ENGINE_VERSION; } catch {}   // never stale — tracks the build
    window.engineVersion = () => ENGINE_VERSION;
    // v1507 — follow the server across updates. If the bridge comes back on a HIGHER version (an
    // update applied while this page was open — including a silent poller/fleet apply), reload onto
    // it. Only-on-higher avoids a false reload during the brief restart-down window. Combined with
    // the launcher skipping a duplicate tab on update, an open page becomes the one current page.
    try {
        const _loadedV = parseInt(((ENGINE_VERSION.match(/v?(\d+)/) || [])[1]) || "0", 10);
        if (_loadedV) setInterval(() => {
            fetch("/package/info", { cache: "no-store" }).then(r => r.json()).then(info => {
                const m = String((info && info.version) || "").match(/v?(\d+)/);
                const v = m ? parseInt(m[1], 10) : 0;
                if (v && v > _loadedV) { try { console.log("[swek] server is now v" + v + " (was v" + _loadedV + ") — reloading onto the new build"); } catch {} location.reload(); }
            }).catch(() => {});
        }, 20000);
    } catch {}
    // v969 — benign-noise classifier. These are "an OPTIONAL service isn't
    // running" or "benign skip" messages — expected, not failures. Debug views,
    // the console mirror, and the perf monitor use this to avoid raising an
    // alarm (red) for them. Extend window._benignPatterns to add more.
    window._benignPatterns = [
        /OllamaDiffuser|ollamadiffuser|:9000\/api\/(tags|health)/i,   // diffuser not running (optional)
        /\/ha\/states|502 \(Bad Gateway\)|Bad Gateway/i,              // Home Assistant not reachable (optional)
        /:8765\/assets|assets\/events|AssetLibraryPanel.*(event stream|SSE)/i, // asset server down (optional)
        /ERR_CONNECTION_REFUSED|net::ERR_/i,                          // optional local service offline
        /no default export, skipped/i,                               // benign demo-loader skip
        /intro\.mp4.*404|404 \(Not Found\).*(intro|ogre_boat_carrier)/i, // missing optional media
        /AudioContext was not allowed to start/i,                    // benign until a user gesture
        /message channel closed before a response/i,                 // benign extension noise
        // v1611 — more known-benign noise so the avatar stays calm for "an optional thing isn't here" cases:
        /showcase\.json|404 \(Not Found\).*showcase/i,               // no showcase allowlist in this tree (dev)
        /Permissions policy violation|unload is not allowed/i,       // benign jQuery unload-handler warning
        /willReadFrequently/i,                                       // Canvas2D perf HINT, not an error
        /KPop LISTENER\] loaded undefined clips/i,                   // cosmetic listener log
        /comfyui\/system_stats|ComfyUI.*not reachable/i,             // ComfyUI not running (optional)
        /:1984\/api\/frame\.jpeg|go2rtc/i,                           // camera proxy off (optional)
    ];
    window._benignError = (text) => { try { return window._benignPatterns.some(re => re.test(String(text || ""))); } catch { return false; } };
    // v856 — detect version bump on load and fire engine:roundShipped
    // once. The v849 Twitch broadcast hook + v855 audio cue (feed
    // fanfare) listen for this. Suppresses repeat fires by storing
    // the last-seen version in localStorage. First load on a fresh
    // browser doesn't fire (no baseline to compare against).
    try {
        const KEY = "voxelEngine.lastShippedVersion";
        const last = localStorage.getItem(KEY);
        if (last && last !== ENGINE_VERSION) {
            // Defer dispatch until after the page is fully loaded so
            // listeners (window.twitch.announce, audio cues) are wired.
            setTimeout(() => {
                try {
                    window.dispatchEvent(new CustomEvent("engine:roundShipped", {
                        detail: { round: ENGINE_VERSION, prev: last },
                    }));
                } catch {}
            }, 2500);
        }
        localStorage.setItem(KEY, ENGINE_VERSION);
    } catch {}
}

