// v401 — GPU-side particle system. Transform feedback drives the
// integrator; 100k+ particles live entirely on the GPU. Kaiju AI,
// civilization destruction, megastructure completion cinematics, and
// debris-from-impact effects all spawn through here. Falls back to
// disabled (no-op) on WebGL1 contexts; the existing CPU debris path
// remains the universal fallback.
const gpuParticles = new GPUParticles(gl, {
    maxParticles:      100000,
    maxSpawnsPerFlush: 4096,
    gravity:            9.8,
    drag:               0.4,
    color:              [1.0, 0.7, 0.3],
});
window.gpuParticles = gpuParticles;
if (gpuParticles.isSupported()) {
    console.log("[v401] GPUParticles ready — capacity " + gpuParticles.capacity);
}

// Forward-declared so resize() (which runs before TV wall is built) can
// safely no-op against them. Assigned lower down.
let tvWall = null;
let tvOverlay = null;
let bloomPass = null;
let phosphorPass = null;   // v1074 — GL CRT/phosphor post pass (opt-in)

// Round 30 wow-pass — transient bloom flash for kaiju attack impacts. Bumps
// bloomPass.intensity above its current baseline and eases it back over ~380ms.
// Strongest overlapping pulse wins; the baseline is re-captured on each fresh
// pulse so a user's bloom-slider change isn't clobbered.
let _bloomPulseTimer = null, _bloomPulseEnd = 0, _bloomBase = 0, _bloomPulseAmt = 0;
function _wowBloomPulse(amount) {
    if (!bloomPass) return;
    const fresh = !_bloomPulseTimer;
    if (fresh) _bloomBase = bloomPass.intensity;
    _bloomPulseAmt = fresh ? amount : Math.max(_bloomPulseAmt, amount);
    _bloomPulseEnd = performance.now() + 380;
    bloomPass.intensity = _bloomBase + _bloomPulseAmt;
    if (!fresh) return;
    _bloomPulseTimer = setInterval(() => {
        const left = _bloomPulseEnd - performance.now();
        if (left <= 0) { bloomPass.intensity = _bloomBase; _bloomPulseAmt = 0; clearInterval(_bloomPulseTimer); _bloomPulseTimer = null; return; }
        bloomPass.intensity = _bloomBase + _bloomPulseAmt * (left / 380);
    }, 16);
}

function resize() {
    // High-DPI rendering: framebuffer is sized at device pixel ratio so
    // crisp on retina/4K. Capped at 2x because the cost is quadratic and
    // 4x retina screens (3840 × 2160 logical → 7680 × 4320 framebuffer)
    // can drop FPS hard on low-end GPUs. CSS sizing is unchanged so the
    // canvas still fills the same screen area.
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const cssW = canvas.clientWidth;
    const cssH = canvas.clientHeight;
    canvas.width  = Math.floor(cssW * dpr);
    canvas.height = Math.floor(cssH * dpr);

    if (tvWall) tvWall.onResize();
    if (tvOverlay) tvOverlay.resize(canvas.width, canvas.height, dpr);
    // Round 24 — bloom FBOs follow canvas size. resize() fires before
    // bloomPass exists on first call, so guard against the null forward
    // declaration.
    if (bloomPass) bloomPass.resize(canvas.width, canvas.height);
    if (phosphorPass) phosphorPass.resize(canvas.width, canvas.height);
}
resize();
window.addEventListener("resize", resize);

