window.world = world;

// v2838 -- BOOT FINGERPRINT. Runs at IDLE, never in the boot path: computeFingerprint costs ~1.3s cold and the
// engine must start exactly as fast as it did. The value of doing it at every boot is not the number itself --
// verify.html can already produce that on demand -- it is the COMPARISON. A record is kept per build, and the
// three cases are deliberately different: a new build records a baseline, an unchanged one is quiet, and the
// SAME BUILD producing a DIFFERENT fingerprint is an alarm. That last case means either the source was edited
// without bumping the version or this machine no longer agrees with itself, and neither shows up anywhere else.
//
// It also leaves a cached attestation on disk, so a peer asking "do we agree?" costs one string comparison
// instead of making another box spend 1.3 seconds.
(async () => {
    try {
        const [{ runAtBoot, attestation, agreesWith }, { computeFingerprint }] = await Promise.all([
            import("./tools/fingerprint/bootFingerprint.mjs"),
            import("./tools/fingerprint/fingerprint.mjs"),
        ]);
        window.rigCheck = {
            attestation: () => attestation(),
            agreesWith: (peer) => agreesWith(peer),
            last: null,
        };
        runAtBoot({
            build: ENGINE_VERSION,
            computeFingerprint,
            onResult: (o) => {
                window.rigCheck.last = o;
                if (o.status === "DRIFT") console.error("[RIG CHECK] " + o.message);
                else if (o.status === "error") console.warn("[RIG CHECK] " + o.message);
                else console.log("[RIG CHECK] " + o.status + " - " + o.message + (o.ms ? " (" + o.ms + "ms, " + o.subsystems + " subsystems)" : ""));
            },
        });
    } catch (e) { console.warn("[RIG CHECK] unavailable:", e && e.message); }
})();

window.dumpChunkGrid = (refX, refZ) => world.dumpChunkGrid(
    refX ?? camera?.position?.x ?? 0,
    refZ ?? camera?.position?.z ?? 0
);
// v332 — camera-following chunk streaming. Opt-in. When enabled,
// chunks generate as the camera enters new area and (optionally)
// unload as the camera leaves. Default behavior (fixed grid at
// origin) stays untouched until you flip the switch.
const chunkStreamer = new ChunkStreamer({ world, camera });
// v364 — ChunkStreamer is on by default now (was opt-in since v332).
// Camera-following chunk streaming is mature enough to lead. Users who
// want the old origin-anchored grid can set localStorage flag
// "voxelengine.streamer.disabled" = "1" before reload.
try {
    const disabled = (typeof localStorage !== "undefined") &&
                     localStorage.getItem("voxelengine.streamer.disabled") === "1";
    if (!disabled) {
        chunkStreamer.setEnabled(true);
        console.log("[ChunkStreamer] default-on (v364). Disable: localStorage.setItem('voxelengine.streamer.disabled', '1') + reload");
    } else {
        console.log("[ChunkStreamer] disabled via localStorage opt-out");
    }
} catch (e) {
    // localStorage blocked — fall back to on
    chunkStreamer.setEnabled(true);
}
window.streamer = {
    setEnabled:        (on) => chunkStreamer.setEnabled(on),
    enabled:           () => chunkStreamer.isEnabled(),
    stats:             () => chunkStreamer.stats(),
    setBudget:         (n) => chunkStreamer.setFrameChunkBudget(n),
    setUnloadEnabled:  (on) => chunkStreamer.setUnloadEnabled(on),
    setUnloadMargin:   (n) => chunkStreamer.setUnloadMargin(n),
};
console.log("[STREAMER] camera-following chunk loader · default ON (v364) · 'streamer.setEnabled(false)' to disable");

