// v337 — Demo isolation. Tracks which background systems are allowed to
// run while a demo is active. Most demos benefit from a quiet world
// (no kaiju AI wandering, no civ sim ticking, no auto-spawns). Some
// demos welcome background activity (voice lab — fun to see the world
// behind the recognition panel). Benchmarks need exclusive CPU.
//
// Profile values:
//   "active"    — everything runs normally (kaiju demo, anything that
//                 IS the background activity)
//   "quiet"     — pauses kaiju AI ticks, civ sim, kaiju spawn checks,
//                 throw cinematic. Renderer + input + voxel world stay
//                 fully alive. Default for most demos.
//   "exclusive" — quiet, plus also pauses mesh PP, chunk streamer, and
//                 worker-pool jobs so benchmarks see clean CPU.
//
// The active profile is read by the main loop's individual tick calls
// (aiManager, civLoop, kaijuManager spawn, etc.). Demos set the
// profile via their `isolation` field — see DEMO_MODES below.
window._demoIsolation = "active";
window.getDemoIsolation = () => window._demoIsolation;
const _isIsolationQuiet     = () => window._demoIsolation !== "active";
const _isIsolationExclusive = () => window._demoIsolation === "exclusive";

// v442 — CLEAN STAGE for exclusive demos. When a demo declares
// isolation:"exclusive" it pauses the kaiju/civ sim AND now also renders a
// clean stage: the voxel world, water, grass, debris, and ambient civ/kaiju
// markers are hidden. Only entities the demo registers in
// window._isolationShowIds are drawn (null/empty = nothing), so e.g. the rig
// showcase shows its creatures against an empty sky with no kaiju behind them.
window._isolationShowIds = null;   // Set<entityId> | null
// v452 — "clean" hides the terrain like "exclusive" but shows ALL entities
// (no show-set filter), so a demo that just spawns its own objects runs in an
// empty room without each demo having to register a show-set. "exclusive"
// stays show-set-filtered for demos that curate exactly what's visible.
const _stageHidesBackground = () => window._demoIsolation === "exclusive" || window._demoIsolation === "clean";
const _filterStageEntities = (ents) => {
    const mode = window._demoIsolation;
    if (mode === "exclusive") {
        const show = window._isolationShowIds;
        return show ? ents.filter((e) => show.has(e.id)) : [];
    }
    // v509 — the blank-stage floor plate (a giant wad_plate) must NEVER render
    // outside its own exclusive stage. It was lingering into kaiju as the big
    // flat plane. Filter it out in every non-exclusive mode regardless of how/
    // when it was spawned — robust against boot-default blank_sandbox spawning
    // it before the first kaiju draw.
    ents = ents.filter((e) => e.kind !== "stage_floor");
    if (mode === "clean") {
        // v458 — a clean stage shows the demo's OWN spawns but not the kaiju /
        // civ simulation. Their mesh entities persist (so KAIJU can resume on
        // close) but we hide them here so the room stays empty.
        const exclude = new Set();
        try { for (const k of kaijuManager.kaiju.values()) if (k._meshEntityId != null) exclude.add(k._meshEntityId); } catch {}
        try { for (const c of civManager.getAll()) if (c._meshEntityId != null) exclude.add(c._meshEntityId); } catch {}
        return exclude.size ? ents.filter((e) => !exclude.has(e.id)) : ents;
    }
    return ents;   // active / quiet — show everything (minus the stage floor)
};

// v509 — scene diagnostics. Run these in the console and paste the output so
// stray entities (the "air cubes", the flat plane) can be pinned exactly.
//   window.diag.counts()  — every entity grouped by kind/asset
//   window.diag.air(35)   — entities at/above a Y (the cubes up high)
//   window.diag.big(20)   — large-scale entities (a giant flat plane = one of these)
window.diag = {
    _all() { try { return renderBridge.getVisibleEntities() || []; } catch (e) { console.warn("[diag] no entities:", e?.message); return []; } },
    counts() {
        const all = this._all(), m = {};
        for (const e of all) { const k = `${e.kind}/${e.assetId ?? "—"}`; m[k] = (m[k] || 0) + 1; }
        const rows = Object.entries(m).sort((a, b) => b[1] - a[1]);
        for (const [k, n] of rows) console.log(`[diag] ${String(n).padStart(5)}  ${k}`);
        console.log(`[diag] ${all.length} entities total`);
        return rows;
    },
    air(minY = 35) {
        const hits = this._all().filter((e) => e.y >= minY), m = {};
        for (const e of hits) { const k = `${e.kind}/${e.assetId ?? "—"}`; (m[k] = m[k] || []).push(e); }
        for (const [k, arr] of Object.entries(m)) {
            const s = arr[0];
            console.log(`[diag.air] ${k}: ${arr.length}  e.g. id=${s.id} y=${(s.y ?? 0).toFixed(1)} scale=${s.scale ?? s.scaleX} pos=(${(s.x ?? 0).toFixed(0)},${(s.y ?? 0).toFixed(0)},${(s.z ?? 0).toFixed(0)})`);
        }
        console.log(`[diag.air] ${hits.length} entities at/above y=${minY}`);
        return hits.length;
    },
    big(minScale = 20) {
        const hits = this._all().filter((e) => Math.max(e.scale || 0, e.scaleX || 0, e.scaleY || 0, e.scaleZ || 0) >= minScale);
        for (const e of hits) console.log(`[diag.big] ${e.kind}/${e.assetId ?? "—"} id=${e.id} scale=${e.scale ?? `${e.scaleX}x${e.scaleY}x${e.scaleZ}`} pos=(${(e.x ?? 0).toFixed(0)},${(e.y ?? 0).toFixed(0)},${(e.z ?? 0).toFixed(0)})`);
        console.log(`[diag.big] ${hits.length} large entities (scale ≥ ${minScale})`);
        return hits.length;
    },
};
console.log("[diag] ready — run window.diag.counts(), window.diag.air(), window.diag.big() and paste the output");

// v444 — CLEAN BOOT. The kaiju city simulation (auto-spawn, civ loop, AI,
// hellgate, birth/combat narrative sequences) no longer runs by default.
