// selecting the KAIJU + TERRAIN demo, which sets demo.kaijuSim=true).
window._kaijuSimEnabled = false;
const _kaijuSimOn = () => window._kaijuSimEnabled && !_isIsolationQuiet();
window.kaijuSim = {
    start() { window._kaijuSimEnabled = true; console.log("[kaijuSim] STARTED — kaiju spawn, civ sim, and narrative are now live"); return true; },
    stop()  { window._kaijuSimEnabled = false; console.log("[kaijuSim] STOPPED — world is quiet (no spawning). kaijuSim.start() to resume."); return true; },
    status(){ const on = window._kaijuSimEnabled; console.log(`[kaijuSim] ${on ? "RUNNING" : "stopped (clean)"}`); return on; },
};
console.log("[KAIJU-SIM] quiet by default (v444). 'kaijuSim.start()' to bring the kaiju world to life · 'kaijuSim.stop()' to silence it");

// v335 — feature status + one-shot enable. Surfaces which opt-in
// systems are currently on, and provides a single call to flip them
// all. Useful when testing v331+ changes that ship disabled by
// default — the user can paste `enableAllFeatures()` in the console
// (or run it as part of a multi-line script) to bring everything online.
window.engineStatus = () => {
    const status = {
        version:      ENGINE_VERSION,
        streamer:     chunkStreamer.isEnabled(),
        meshPP:       meshPP.isEnabled?.() ?? false,
        gridGrow:     dynamicGridRadius?.isEnabled?.() ?? false,
        worldChunks:  world.chunks.size,
        gridRadius:   world.gridRadius,
    };
    console.table(status);
    return status;
};
window.enableAllFeatures = () => {
    chunkStreamer.setEnabled(true);
    meshPP.setEnabled(true);
    try { dynamicGridRadius?.setEnabled?.(true); } catch {}
    console.log("[main] enabled: streamer + meshPP + gridGrow (if available)");
    return window.engineStatus();
};
console.log(`[ENGINE ${ENGINE_VERSION}] 'engineStatus()' to inspect · 'enableAllFeatures()' to flip on streamer/meshPP/gridGrow`);

// v336 — storage diagnostics. Lists every voxelengine.* localStorage
// key with byte size + a short preview so you can see what's actually
// persisted across reloads. Use after `resetWorld()` to confirm what
// was/wasn't cleared, or before a session to know your starting state.
window.inspectStorage = () => {
    const rows = [];
    let totalBytes = 0;
    try {
        for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (!k || !k.startsWith("voxelengine.")) continue;
            const v = localStorage.getItem(k) ?? "";
            const bytes = v.length;
            totalBytes += bytes;
            rows.push({
                key:     k.replace("voxelengine.", ""),
                bytes,
                preview: v.length > 60 ? v.slice(0, 57) + "..." : v,
            });
        }
    } catch (e) {
        console.warn("[inspectStorage]", e?.message ?? e);
        return null;
    }
    rows.sort((a, b) => b.bytes - a.bytes);
    console.table(rows);
    console.log(`[inspectStorage] ${rows.length} keys, ${totalBytes} bytes total`);
    return { count: rows.length, totalBytes, rows };
};

// v336 — knock down over-tall mountains. Convenience wrapper around
