window.knockDownMountains = (maxY = 30) => world.knockDownMountains(maxY);

// v336 — universal audio mute. Single switch for every audio source:
// AudioManager (sfx + ambient + speech), kpop TTS, procedural music,
// room ambience, and the master gain. Persists across reloads.
// The 🔊/🔇 button in the KPop LISTENER panel now calls this.
window._muteState = { muted: false, savedVolume: 1.0 };
window.muteAllAudio = () => {
    const s = window._muteState;
    if (s.muted) return;   // already muted
    s.muted = true;
    // Save current master volume so unmute can restore it
    try {
        s.savedVolume = window.audioManager?.audio?._masterVolume ?? 1.0;
    } catch {}
    try { window.audioManager?.setMasterVolume?.(0); } catch {}
    try { window.audioManager?.stopAll?.(); } catch {}
    try { window.audioManager?.muteSpeech?.(); } catch {}
    try { if (window.kpop) window.kpop._ttsMuted = true; } catch {}
    try { window.procMusic?.stop?.(); } catch {}
    try { window.roomAmbience?.stop?.(); } catch {}
    try { localStorage.setItem("voxelengine.muteAll", "1"); } catch {}
    console.log("[mute] all audio sources silenced");
};
window.unmuteAllAudio = () => {
    const s = window._muteState;
    if (!s.muted) return;
    s.muted = false;
    try { window.audioManager?.setMasterVolume?.(s.savedVolume ?? 1.0); } catch {}
    try { window.audioManager?.unmuteSpeech?.(); } catch {}
    try { if (window.kpop) window.kpop._ttsMuted = false; } catch {}
    try { window.procMusic?.resume?.(); } catch {}
    try { window.roomAmbience?.resume?.(); } catch {}
    try { localStorage.removeItem("voxelengine.muteAll"); } catch {}
    console.log(`[mute] all audio restored (master = ${s.savedVolume?.toFixed?.(2)})`);
};
window.toggleMuteAll = () => {
    if (window._muteState.muted) window.unmuteAllAudio();
    else                          window.muteAllAudio();
    return window._muteState.muted;
};
// Restore mute state on next-tick so AudioManager has time to construct
setTimeout(() => {
    try {
        if (localStorage.getItem("voxelengine.muteAll") === "1") {
            window.muteAllAudio();
        }
    } catch {}
}, 100);
console.log("[MUTE] 'muteAllAudio()' / 'unmuteAllAudio()' / 'toggleMuteAll()' — universal silence");

// Round 291 — adaptive view distance. Watches FPS and grows / shrinks
