chunkStreamer.onChunkUnloaded = (key) => { try { renderer.removeChunkMesh(key); } catch {} };
// v945 — LOD: tie distance fog to the LIVE draw distance so far terrain always
// fades into the horizon right at the load edge (hides the pop-in wall) and the
// fade follows the grid as it grows on idle (gridGrow). Recomputes only when the
// radius changes; the other renderers already mirror renderer.fogFar/fogNear.
window.autoFog = {
    isOn: () => { try { return localStorage.getItem("voxelengine.autoFog") !== "0"; } catch { return true; } },
    set:  (on) => { try { localStorage.setItem("voxelengine.autoFog", on ? "1" : "0"); } catch {} _lastFogRadius = -1; },
};
window.drawDistance = {
    get: () => world.gridRadius,
    set: (chunks) => { const r = Math.max(3, Math.min(48, Math.round(chunks))); try { world.growGrid?.(r); } catch {} world.gridRadius = r; _lastFogRadius = -1; return r; },
};
let _lastFogRadius = -1;
setInterval(() => {
    try {
        if (!window.autoFog.isOn()) return;
        const r = world.gridRadius, cs = world.chunkSize || 16;
        if (r === _lastFogRadius) return;
        _lastFogRadius = r;
        const edge = r * cs;
        renderer.fogFar  = edge * 0.95;
        renderer.fogNear = edge * 0.45;
    } catch {}
}, 750);
// v877 — expose so external overlay modules (cape-shield, magic carpet)
