    off:     () => { vegetation.enabled = false; console.log("[vegetation] off"); },
    density: (n = 9000) => { vegetation.setDensity(n); console.log("[vegetation] density", n); },
    wind:    (w = 1.0) => { vegetation.setWind(w); console.log("[vegetation] wind", w); },
    windDir: (deg) => { vegetation.windDir(deg); console.log(deg == null ? "[vegetation] wind auto-drift" : `[vegetation] wind locked to ${deg}°`); },
    windAuto:() => { vegetation.windAuto(); console.log("[vegetation] wind auto-drift"); },
    rebuild: () => { vegetation._buildCenter = null; console.log("[vegetation] will rebuild around camera"); },
