// v419 — WAD Doom sprite billboard renderer. Draws window._wadBillboards
// (a BillboardManager, set when a WAD is voxelized in Doom mode) as
// alpha-tested camera-facing quads. No-op until a WAD with sprites is
// loaded, or wadSprites.test() seeds a demo so it can be verified
// without a WAD on hand.
const wadBillboardRenderer = new WadBillboardRenderer(gl, { enabled: true });
// v421 — aquarium glass + caustics. Inactive until the aquarium demo
// calls window.aquariumTank.setActive(true, bounds). Rendered each frame
// (no-op when inactive).
const aquariumTank = new AquariumTankRenderer(gl);
window.aquariumTank = aquariumTank;
window.wadSprites = {
    on:    () => { wadBillboardRenderer.enabled = true;  console.log("[wadSprites] on"); },
    off:   () => { wadBillboardRenderer.enabled = false; console.log("[wadSprites] off"); },
    state: () => wadBillboardRenderer.getState(),
    clearTextures: () => wadBillboardRenderer.clearTextureCache(),
    // Seed a few demo billboards around the camera using a generated
    // sprite (a little humanoid cutout), so the draw path can be verified
    // before any real WAD is loaded.
    test: async (n = 8) => {
        const { BillboardManager } = await import("./tools/wadBillboards.js");
        const bm = new BillboardManager({ halfSize: 2.2 });
        // Build a 24×40 RGBA humanoid: transparent bg, colored figure.
        const W = 24, H = 40, rgba = new Uint8Array(W * H * 4);
        const put = (x, y, r, g, b) => { const i = (y * W + x) * 4; rgba[i] = r; rgba[i+1] = g; rgba[i+2] = b; rgba[i+3] = 255; };
        for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
            const cx = x - 12;
            if (y < 10 && cx*cx + (y-6)*(y-6) < 24) put(x, y, 210, 170, 130);          // head
            else if (y >= 10 && y < 28 && x > 6 && x < 18) put(x, y, 120, 40, 40);     // torso
            else if (y >= 28 && (x > 7 && x < 11 || x > 13 && x < 17)) put(x, y, 60, 50, 90); // legs
        }
        bm.registerFrame("TEST", "A", 1, { width: W, height: H, rgba });
        const c = (typeof camera !== "undefined" && camera.position) ? camera.position : { x: 0, y: 0, z: 0 };
        for (let i = 0; i < n; i++) {
            const a = (i / n) * Math.PI * 2;
            bm.spawn({ x: c.x + Math.cos(a) * 10, y: c.y, z: c.z + Math.sin(a) * 10, name: "TEST", frame: "A", rot: 1, scale: 1.4 });
        }
        window._wadBillboards = bm;
        console.log(`[wadSprites] test: spawned ${n} demo billboards around the camera`);
        return bm.count();
    },
};

// v414 — opt-in per-voxel detail texture console API. Default OFF, so the
// renderer is unchanged until you turn it on. Test on your GPU:
//   voxelDetail.on()            — enable at default strength (0.6)
//   voxelDetail.set(0.4)        — set blend amount 0..1
//   voxelDetail.scale(0.18)     — tiling frequency (lower = bigger features)
//   voxelDetail.off()           — disable (back to flat-color voxels)
//   voxelDetail.state()         — read current { mix, scale }
window.voxelDetail = {
    on:    (mix = 0.6) => { renderer.setDetailMix(mix); console.log("[voxelDetail] on, mix", mix); },
    off:   () => { renderer.setDetailMix(0); console.log("[voxelDetail] off"); },
    set:   (v) => { renderer.setDetailMix(v); console.log("[voxelDetail] mix", v); },
    scale: (v) => { renderer.setDetailScale(v); console.log("[voxelDetail] scale", v); },
    state: () => renderer.getDetailState(),
    // Swap in custom RGBA pixels (e.g. a WAD wall texture). POT dims tile best.
    texture: (rgba, w, h) => { renderer.setDetailTexture(rgba, w, h); console.log("[voxelDetail] generic layer set", w + "x" + h); },
    // v426 (Tier B) — set one material's array layer to a real texture.
    // layer: 0 stone, 1 dirt, 2 grass, 3 sand, 4 snow, 5 lava, 6 generic.
    layer: (n, rgba, w, h) => { renderer.setDetailLayer(n, rgba, w, h); console.log("[voxelDetail] layer", n, "set", w + "x" + h); },
};
console.log("[voxelDetail] opt-in per-voxel detail texture ready (OFF). 'voxelDetail.on()' to test.");
window._voxelRenderer = renderer;   // round 43p - so GFX panel can toggle frustum cull

// Round 22 — atmospheric upgrade. SkyRenderer draws procedural sky
// gradient with sun disc each frame BEFORE terrain. Its horizon
// color and sun direction are shared with the terrain renderer's
// fog uniform so distant terrain fades into the sky horizon
// continuously (rather than ending at a hard band).
const skyRenderer = new SkyRenderer(gl);
renderer.sunDir   = skyRenderer.getSunDir();

// v438 — wind-driven cloud layer (opt-in). Drifts with the same wind the
// grass uses. window.clouds.cumulus()/cumulonimbus()/stratus()/cirrus()/
// stratocumulus()/nimbostratus()/off(), or pick a type in Settings → World.
const cloudLayer = new CloudLayer(gl);
// v453 — underwater caustics overlay (reviewed-water-dump math, grafted as a
// self-contained DOM overlay; complements the existing submerged tint).
const underwaterFx = new UnderwaterCaustics({});
window.underwater = {
    on:  () => { underwaterFx.setEnabled(true);  console.log("[underwater] caustics ON"); },
    off: () => { underwaterFx.setEnabled(false); console.log("[underwater] caustics OFF"); },
    intensity: (v) => { underwaterFx.intensity = Math.max(0, +v || 1); return underwaterFx.intensity; },
    status: () => ({ enabled: underwaterFx.enabled, amount: +underwaterFx.amount.toFixed(2) }),
};
// v526 — arm caustics so they auto-show when SwimMode reports the eye submerged.
// `auto` gates the automatic drive (loop calls underwaterFx.update with the
// submerged flag); window.underwater.off() still force-hides.
underwaterFx.setEnabled(true);
window.underwater.auto = true;
// v526 — open-world waterline check. SwimMode only covers FPS + Ollama-level
// rooms; this detects the camera eye inside an ocean/lake/river WATER voxel so
// caustics + depth tint trigger in free-fly too.
let _uwActive = false, _uwBaseSpeed = 0;
function _eyeUnderwater() {
    if (!world?.voxelAt || !camera?.position) return false;
    const v = world.voxelAt(Math.floor(camera.position.x), Math.floor(camera.position.y), Math.floor(camera.position.z));
    return v === 10 || v === 11;   // WATER or FLOWING_WATER
}
window.clouds = {
    set:  (type) => { if (type === "automatic" || type === "auto") return window.clouds.auto(true); window.clouds._auto = false; const ok = cloudLayer.setType(type, camera.position.x, camera.position.z); try { localStorage.setItem("voxelengine.clouds", ok ? type : "off"); } catch {} console.log(ok ? `[clouds] ${type} overhead, drifting with the wind` : `[clouds] unknown type "${type}"`); return ok; },
    off:  () => { window.clouds._auto = false; cloudLayer.off(); try { localStorage.setItem("voxelengine.clouds", "off"); } catch {} console.log("[clouds] cleared"); },
    speed: (s) => { cloudLayer.speedScale = +s || 1.6; console.log(`[clouds] drift speed ×${cloudLayer.speedScale}`); },
    current: () => window.clouds._auto ? "automatic" : (cloudLayer.enabled ? cloudLayer.type : "off"),
    cumulus: () => window.clouds.set("cumulus"),
    cumulonimbus: () => window.clouds.set("cumulonimbus"),
    stratus: () => window.clouds.set("stratus"),
    stratocumulus: () => window.clouds.set("stratocumulus"),
    cirrus: () => window.clouds.set("cirrus"),
    nimbostratus: () => window.clouds.set("nimbostratus"),
};
// v1094 — Automatic clouds: pick a sensible cloud type from the current emulated
// weather, and conjure a tornado when it turns stormy. Re-evaluates on each
// weather change while auto is on. window.clouds.auto(true) / set("automatic").
window.clouds._auto = false;
window.clouds._autoPrevStorm = false;
window.clouds.isAuto = () => !!window.clouds._auto;
const _STATE_TO_CLOUD = { clear: "off", cloudy: "stratocumulus", rain: "nimbostratus", snow: "stratus", blizzard: "stratus", storm: "cumulonimbus", fog: "stratus", mist: "stratus" };
window.clouds._applyAuto = () => {
    try {
        const st = (window.weatherSystem && window.weatherSystem.state) || "clear";
        const want = _STATE_TO_CLOUD[st] || "off";
        if (want === "off") cloudLayer.off(); else cloudLayer.setType(want, camera.position.x, camera.position.z);
        const isStorm = (st === "storm");
        // Conjure a tornado on the transition INTO a storm (once), not every re-eval.
        const firedTornado = isStorm && !window.clouds._autoPrevStorm;
        if (firedTornado) { try { window.vortex?.tornado?.(); } catch {} }
        window.clouds._autoPrevStorm = isStorm;
        console.log(`[clouds] automatic → ${want} (weather: ${st})${firedTornado ? " + tornado" : ""}`);
    } catch (e) { console.warn("[clouds] auto apply failed:", e?.message || e); }
};
window.clouds.auto = (on = true) => {
    window.clouds._auto = !!on;
    try { localStorage.setItem("voxelengine.clouds", on ? "automatic" : (cloudLayer.enabled ? cloudLayer.type : "off")); } catch {}
    if (on) window.clouds._applyAuto();
    return on;
};
window.addEventListener("engine:weatherChanged", () => { if (window.clouds._auto) window.clouds._applyAuto(); });
console.log("[CLOUDS] 'clouds.cumulus()' / '.cumulonimbus()' / '.stratus()' / '.cirrus()' / '.stratocumulus()' / '.nimbostratus()' · '.off()'");
// v452 — clouds ON by default (drifting cumulus). Respects a saved choice:
// clouds.off() / Settings → World remembers "off" or a specific type.
try {
    const _cloudPref = localStorage.getItem("voxelengine.clouds");
    if (_cloudPref === "automatic") {
        window.clouds._auto = true;
        setTimeout(() => { try { if (window.clouds._auto) window.clouds._applyAuto(); } catch {} }, 1500);
        console.log("[clouds] automatic mode on (remembered) — picks cloud type from weather");
    } else if (_cloudPref !== "off") {
        const t = (_cloudPref && cloudLayer.setType(_cloudPref, camera.position.x, camera.position.z)) ? _cloudPref
                : (cloudLayer.setType("cumulus", camera.position.x, camera.position.z), "cumulus");
        console.log(`[clouds] ${t} on by default — clouds.off() to clear (remembered).`);
    }
} catch {}

// Round 48 — sun lens flare overlay. Reads sun direction + camera
// orientation each frame; renders HTML disc + ghosts when sun is in view.
const sunFlare = new SunFlare({ skyRenderer, camera });
renderer.fogColor = skyRenderer.getHorizonColor();

// Round 24 — sprite atlas for particles + bloom post-process.
// Atlas has 8 procedurally-drawn sprites in a 4x2 grid; particles
// pick one via SPRITE.* index. BloomPass renders scene to FBO,
// extracts bright pixels, blurs, composites additively.
const spriteAtlas = new SpriteAtlas(gl);
bloomPass   = new BloomPass(gl, canvas.width, canvas.height);
phosphorPass = new PhosphorPass(gl, canvas.width, canvas.height);   // v1074
// v1074 — true GL CRT/phosphor pass. Bloom composites into the phosphor FBO,
// then a fullscreen shader applies barrel/scanlines/phosphor-tint/glow/vignette.
// Opt-in; tint follows the live --game-color (the Pip-Boy EffectColor from v1073).
window.phosphor = {
    set(on) { if (!phosphorPass || !phosphorPass.ok) return { ok: false, error: "phosphor unavailable (shader failed)" }; phosphorPass.enabled = !!on; document.documentElement.classList.toggle("gl-phosphor", !!on); return { ok: true, enabled: phosphorPass.enabled }; },
    config(c = {}) { if (!phosphorPass) return { ok: false }; for (const k of ["tintAmt", "scan", "barrel", "aberration", "vignette", "bloom", "flicker"]) if (typeof c[k] === "number") phosphorPass[k] = c[k]; if (Array.isArray(c.tint)) phosphorPass.setTint(c.tint); return window.phosphor.status(); },
    status() { return phosphorPass ? { ok: phosphorPass.ok, enabled: phosphorPass.enabled, tint: phosphorPass.tint, scan: phosphorPass.scan, barrel: phosphorPass.barrel, aberration: phosphorPass.aberration, vignette: phosphorPass.vignette, bloom: phosphorPass.bloom } : { ok: false }; },
};
console.log("[phosphor] " + (phosphorPass && phosphorPass.ok ? "ready — window.phosphor.set(true) for the CRT pass (tint follows the in-game color)" : "unavailable (shader compile failed)"));
    try { const _ps = JSON.parse(localStorage.getItem("voxelengine.phosphor") || "{}"); if (_ps && Object.keys(_ps).length && window.phosphor) window.phosphor.config(_ps); } catch {}
// Round 317 — shadow resolution dropped from 2048² → 1024². Round
// 318 — dropped further to 512². At 4 FPS the shadow GPU work is
// non-trivial, and at typical view distance 512² depth is
// indistinguishable from 1024² for voxel-world shadows. Configurable
// via window.engineConfig.shadowMapSize for users who want crisper
// shadow edges at perf cost.
const shadowMapSize = (typeof window !== "undefined" && window.engineConfig?.shadowMapSize) || 512;
const shadowPass = new ShadowPass(gl, shadowMapSize);   // round 43k - directional sun shadow

// Round 301 — Cascaded Shadow Maps. Renders alongside the single-pass
// ShadowPass above. The voxel/entity renderers still sample the single
// shadowPass (the canonical near-camera shadow); CSM cascades populate
// independently and are exposed via window.csm for the (forthcoming)
// shader rewrite that will sample per-cascade. Wired-but-passive — the
// machinery runs and its outputs are available, but visual change
// requires the renderer's FS update tracked in
// docs/csm-integration-r301.md.
const { CascadedShadowPass } = await import("./render/CascadedShadowPass.js");
const csm = new CascadedShadowPass(gl, {
    numCascades: 3,
    size: 1024,
    nearPlane: 0.1,
    farPlane: 250,
    lambda: 0.5,
});
window.csm = csm;
// Round 301 — CSM cascade render is OFF by default (3× the voxel depth
// pass cost; only worth it once the FS samples per-cascade). Toggle
// via window.csm._renderOn = true to start populating the cascade
// textures for the shader-integration round.
csm._renderOn = false;
// Round 301 — SSAO tuning passthrough. The existing SSAO in BloomPass
// (round 52) already renders on by default at strength 0.85. Expose
// runtime controls so it can be A/B-tested against the unlit baseline.
//   window.ssao.setStrength(0..1)
//   window.ssao.setRadius(0..3)      world-unit AO falloff
//   window.ssao.setBias(0..0.1)      depth-delta threshold
//   window.ssao.off() / on() / status()
window.ssao = {
    setStrength: (v) => { bloomPass.ssaoStrength = Math.max(0, Math.min(1, v)); },
    setRadius:   (v) => { bloomPass.ssaoRadius   = Math.max(0.01, v); },
    setBias:     (v) => { bloomPass.ssaoBias     = Math.max(0, v); },
    off:         () => { bloomPass.ssaoStrength = 0.0; },
    on:          () => { bloomPass.ssaoStrength = 0.85; },
    status:      () => ({
        strength: bloomPass.ssaoStrength,
        radius:   bloomPass.ssaoRadius,
        bias:     bloomPass.ssaoBias,
    }),
};
const turretRenderer = new TurretRenderer(gl);  // round 43r - half-dome + tube turret visuals
const gfxSettings = new GraphicsSettings();    // round 43l - runtime feature toggles
window._gfxSettings = gfxSettings.state;
// round 43p - perf snapshot consumed by graphics settings panel
window._perfStats = { fps: 0, frameMs: 0, build: 0, entCount: 0 };

// v413 — F1 performance overlay. Dynamically imported + try/caught so a
// stale or missing PerfHUD.js (e.g. browser cached a 404 from before the
// file existed) degrades to "no overlay" instead of crashing engine boot.
// v415 — was a static import; a failed static import is fatal, so a
// non-essential overlay must never be one.
let perfHUD = null;
(async () => {
    try {
        const { PerfHUD } = await import("./ui/PerfHUD.js");
        perfHUD = new PerfHUD({
            extraSources: {
                gpuParticles: () => window.gpuParticles,
                chunkCount:   () => { try { return world.chunks.size; } catch { return null; } },
                kaijuCount:   () => { try { return kaijuManager.size(); } catch { return null; } },
                civCount:     () => { try { return civManager.size(); } catch { return null; } },
            },
        });
        window.perfHUD = perfHUD;
        console.log("[PERF-HUD] press ` (backtick) or F1 for the performance overlay · window.perfHUD.toggle()");
    } catch (e) {
        console.warn("[PERF-HUD] overlay unavailable (PerfHUD.js failed to load — try a hard refresh):", e?.message ?? e);
    }
})();
window.addEventListener("keydown", (e) => {
    // v419 — backtick is the primary toggle (F1 is often swallowed by the
    // browser's Help shortcut). Both work; ignore when typing in a field.
    const tag = (e.target && e.target.tagName) || "";
    if (tag === "INPUT" || tag === "TEXTAREA" || e.target?.isContentEditable) return;
    if (e.code === "Backquote" || e.key === "`" || e.code === "F1" || e.key === "F1") {
        e.preventDefault();
        if (perfHUD) perfHUD.toggle();
        // Fallback: if PerfHUD failed to load (e.g. a stale cached module),
        // open the worker-pool perf dashboard so the key still does something.
        else if (window.perf?.toggle) { window.perf.toggle(); }
        else console.warn("[PERF] overlay unavailable — hard-refresh (Ctrl+Shift+R) to reload PerfHUD.js");
    }
});

// Round 23 — particle system. Single shared pool of 2000 particles
// fed by multiple emitters. ParticleSystem renders billboards;
// emitters drive spawn() based on world state and events.
const particles = new ParticleSystem(gl, {
    maxParticles: 2000,
    atlas: spriteAtlas,
    fogColor: skyRenderer.getHorizonColor(),
    fogNear: 60.0,
    fogFar:  220.0,
});
// v877 — expose for hit-VFX spawning from external overlay modules
// (cape-shield impact sparks etc).
window.particles = particles;
const lavaEmbers = new LavaEmberEmitter({
    particles, world, camera,
    scanRadius: 60, scanInterval: 0.4, embersPerScan: 8,
});
const memoryShimmer = new MemoryShimmerEmitter({
    particles, world, camera,
});
const highlight = new VoxelHighlight(gl);
// v613 — second highlight for "selected" voxel (persistent until next click).
// Hover stays yellow via `highlight`; selection is cyan via this one. Both are
// exposed as window globals so the sandbox demo / editor can call setTarget()
// on them without us threading references through every demo.
const selectionHighlight = new VoxelHighlight(gl, { r: 0, g: 0.85, b: 1, a: 1 });
window._hoverHighlight     = highlight;
window._selectionHighlight = selectionHighlight;
const hud       = new HUD();
try { window._hud = hud; } catch {}   // v1561 — Settings -> Weather triggers hud._fetchLiveWx()

// Round 47 — toast notifications + tamagotchi window. Both subscribe
// to bridge messages once the bridge is constructed (later in main).
// We hold off on instantiating until after wsBridge exists — see below.

// Water renderer — wave-animated translucent surface for water voxels.
// Flipping skipWater excludes water IDs (10, 11) from the greedy mesh
// so they don't render twice. Clear the existing mesh cache so any
// pre-built meshes get regenerated without water on the next frame.
const waterRenderer = new WaterRenderer(gl, world);

// WaterField — event-driven ripple/splash/tidal layer that rides on top of
// WaterRenderer's ambient waves. baseLevel MUST be set to your actual water-
// surface Y to be useful (voxel water level + 1). Finite 256x256 patch centered
// near origin; recenter with waterField.setOrigin(x,z) when roaming.
//   waterField.setBaseLevel(Y) · waterField.splash(x,z,force) ·
//   waterField.tidalWave({ edge:'west', speed:24, amplitude:6, thickness:5 })
const waterField = new WaterField({
    gl, width: 256, depth: 256, cellSize: 1,
    originX: -128, originZ: -128, baseLevel: 9,  // WATER_LEVEL(8) + 1 — surface sits atop the level-8 voxels
});
waterRenderer.setWaterField(waterField);
try { waterRenderer.setMeshedChunks(renderer.meshes); } catch {}   // v511 — water waits for land to be drawn
let _wfLast = performance.now();
window.waterField = waterField;
console.log("[waterField] active — set waterField.setBaseLevel(Y) to your water surface, then waterField.splash(x,z,15)");
// v465 — THE flip the comment above describes, which was never actually
// applied: exclude water (10/11) from the greedy chunk mesh so (a) water
// isn't drawn twice (mesh cubes + WaterRenderer surface) and (b) solid faces
// that border water — the LAKEBED — are emitted instead of culled. Without
// this you swim into a blue void with no ground under the water. Clear the
// mesh cache so existing chunks rebuild without the baked-in water.
renderer.skipWater = true;
try { renderer.meshes.clear(); } catch {}
// Round 423 — water tuning console API. Screen-space refraction defaults
// OFF (bit-identical to prior water); turn it on to validate + tune on GPU.
window.water = {
    refraction: (on = true) => {
        waterRenderer.setRefraction(on === false ? 0 : (typeof on === "number" ? on : 1.0));
        console.log(`[water] refraction ${waterRenderer._refractStrength > 0 ? "ON @ " + waterRenderer._refractStrength : "off"} (distortion). depthFade ${waterRenderer._depthFade}`);
    },
    strength:  (v) => { waterRenderer.setRefraction(v); console.log("[water] refraction distortion", waterRenderer._refractStrength); },
    depthFade: (v) => { waterRenderer.setDepthFade(v); console.log("[water] depthFade", waterRenderer._depthFade, "(higher = goes opaque-blue sooner)"); },
    ssr:       (v) => { waterRenderer._ssrStrength = Math.max(0, +v || 0); console.log("[water] SSR strength", waterRenderer._ssrStrength); },
    sparkle:   (v) => { waterRenderer.setCaustics(v === false ? 0 : v); console.log("[water] surface caustic sparkle", waterRenderer._causticStrength); return waterRenderer._causticStrength; },
    state:     () => ({ refraction: waterRenderer._refractStrength, depthFade: waterRenderer._depthFade, ssr: waterRenderer._ssrStrength, sparkle: waterRenderer._causticStrength }),
};

// v456 — Minecraft schematic loader. Drop a .schem/.schematic onto the window
// (or run schematic.pick()) to voxelize a Minecraft build into the world and
// teleport onto it to walk around — same parse → setVoxel → spawn pipeline as
// the WAD voxelizer. Multiplayer: every client loads the same file locally
// (setVoxel is local; per-voxel network sync would be far too chatty).
window.schematic = {
    async load(arrayBuffer, opts = {}) {
        try {
            // v457 — auto-detect format: LDraw LEGO (.ldr/.mpd, plain text)
            // vs Minecraft schematic (gzip/NBT binary). Both yield the same
            // normalized { width,height,length,voxelAt } structure.
            const u8 = new Uint8Array(arrayBuffer);
            const isGzip = u8[0] === 0x1f && u8[1] === 0x8b;
            const isNBT  = u8[0] === 0x0a;                       // NBT root compound
            const head   = new TextDecoder().decode(u8.slice(0, 96)).replace(/^\uFEFF/, "");
            const looksLDraw = !isGzip && !isNBT && (/\.(ldr|mpd)$/i.test(opts.name || "") || /^\s*[01]\s/.test(head) || /\.dat/i.test(head));
            const parsed = looksLDraw
                ? parseLego(new TextDecoder().decode(arrayBuffer))
                : await parseSchematic(arrayBuffer);
            // Centre on a chosen point (default: the camera's XZ). floorY lets
            // the BUILD VIEWER drop it on its flat floor instead of terrain.
            const cx = Math.floor(opts.center ? opts.center.x : camera.position.x);
            const cz = Math.floor(opts.center ? opts.center.z : camera.position.z);
            let gy = opts.floorY;
            if (gy == null) { gy = 4; try { if (world._heightAt) gy = Math.max(1, world._heightAt(cx, cz) | 0); } catch {} }
            const origin = opts.origin || {
                x: cx - Math.floor(parsed.width / 2), y: gy, z: cz - Math.floor(parsed.length / 2),
            };
            const r = loadSchematicIntoWorld(world, parsed, { origin, maxVoxels: opts.maxVoxels });
            console.log(`[schematic] ${parsed.format} ${parsed.width}×${parsed.height}×${parsed.length} → ${r.voxels} voxels${r.clipped ? " (clipped at cap — raise maxVoxels)" : ""}. Walk in.`);
            if (!opts.noTeleport) {
                try {
                    if (window._safeMoveCamera) window._safeMoveCamera(camera, r.spawn.x, r.spawn.y, r.spawn.z, { warnOnAdjust: false, maxLift: parsed.height + 4 });
                    else { camera.position.x = r.spawn.x; camera.position.y = r.spawn.y; camera.position.z = r.spawn.z; }
                } catch {}
            }
            return r;
        } catch (e) { console.warn("[schematic] load failed:", e.message); return { ok: false, error: e.message }; }
    },
    pick() {
        const inp = document.createElement("input");
        inp.type = "file";
        inp.accept = ".schem,.schematic,.litematic,.ldr,.mpd";
        inp.addEventListener("change", async () => {
            const f = inp.files && inp.files[0];
            if (!f) return;
            console.log(`[schematic] loading ${f.name} (${(f.size / 1024).toFixed(0)} KB)…`);
            await window.schematic.load(await f.arrayBuffer(), { name: f.name });
        });
        inp.click();
    },
};
window.addEventListener("dragover", (e) => { if (e.dataTransfer && e.dataTransfer.types && e.dataTransfer.types.includes("Files")) e.preventDefault(); });
window.addEventListener("drop", async (e) => {
    const f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
    if (!f || !/\.(schem|schematic|litematic|ldr|mpd)$/i.test(f.name)) return;   // ignore non-schematic drops
    e.preventDefault();
    console.log(`[schematic] dropped ${f.name} (${(f.size / 1024).toFixed(0)} KB)…`);
    await window.schematic.load(await f.arrayBuffer(), { name: f.name });
});
console.log("[SCHEMATIC] drop a Minecraft .schem/.schematic/.litematic or LEGO .ldr/.mpd onto the window (or schematic.pick()) to load a build and walk it.");
renderer.meshes.clear();

// Seed a small lake near origin so the water shader is visible
// immediately, before rain has had time to generate persistent water.
function seedStarterLake() {
    const VOXEL_WATER = 10;
    for (let dx = 0; dx < 5; dx++) {
        for (let dz = 0; dz < 5; dz++) {
            // y=19 sits just above the typical noise terrain at this XZ
            world.setVoxel(6 + dx, 19, 6 + dz, VOXEL_WATER);
        }
    }
}
seedStarterLake();
// Clear the _modified flags now — the starter lake voxels are re-seeded
// on every page load, so persisting them is wasteful (and makes "Reset
// World" feel non-empty since the lake is back). User-initiated voxel:set
// commands happen *after* this point, so their _modified flags survive
// and are still persisted by the autosave path.
for (const c of world.chunks.values()) {
    c._modified = false;
}

// ----------------------------------------------------------------------
// PERSISTENCE — restore any prior world state, then schedule autosave
// ----------------------------------------------------------------------
// We seed the lake BEFORE loading so the lake is part of the "fresh
// world" baseline; loadWorld() then overwrites any chunk that was
// modified in the previous session, including the lake area if the
// user changed it. The seed is idempotent — running it again writes
// the same lake voxels.
const persistence = new WorldPersistence(world);
// Round 168 (v663) — persistence.load() is now async (IndexedDB-backed).
// Top-level await in an ES module is supported and pauses everything below
// this line until the world payload is restored — which is exactly what
// we want (no render before the restore completes).
const loadResult = await persistence.load();
if (loadResult.ok) {
    console.log(`[main] world restored: ${loadResult.restored} chunks (age ${(loadResult.ageMs / 1000).toFixed(1)}s · backend: ${loadResult.backend || "idb"})`);
    // Force renderer to rebuild meshes for restored chunks
    renderer.meshes.clear();
    // Round 43f - ensure boundary walls exist even on restored worlds
    if (world._paintBoundaryWalls) world._paintBoundaryWalls();
} else if (loadResult.error !== "no save") {
    console.warn(`[main] world load skipped: ${loadResult.error}`);
}
// v440 — start somewhere random on EVERY load by default (people kept
// restarting at the identical spot staring at the same 3 obelisks). The
// world still persists; only the camera pose is re-randomized. Opt back
// into resuming your last view with: resumeCamera(true).
const _RESUME_CAM = (() => { try { return localStorage.getItem("voxelengine.resumeCamera") === "1"; } catch { return false; } })();
const camResult = _RESUME_CAM ? persistence.loadCamera(camera) : { ok: false };
window.resumeCamera = (on = true) => {
    try { on ? localStorage.setItem("voxelengine.resumeCamera", "1") : localStorage.removeItem("voxelengine.resumeCamera"); } catch {}
    console.log(`[main] camera ${on ? "will resume your last view" : "starts random"} on next load`);
};
// v675 — quick teleport-to-origin for "I got lost / out of bounds" recovery.
// Drops the camera at (0, 30, 0) facing +Z with a slight downward pitch so the
// world is in view. Forces a world.regenerate() so chunks around the new
// position are guaranteed loaded — long teleports otherwise land you in a
// pocket of un-meshed chunks (invisible void).
window.gohome = (y = 30) => {
    camera.position.x = 0;
    camera.position.y = y;
    camera.position.z = 0;
    camera.yaw = 0;
    camera.pitch = -0.25;
    try {
        world.regenerate();
        console.log(`[gohome] teleported to (0, ${y}, 0) facing +Z, regenerated chunks around new position. If you still see nothing, run rig.fish() — a 5×5 golden pad should appear in front of you.`);
    } catch (e) {
        console.warn("[gohome] world.regenerate failed:", e?.message);
        console.log(`[gohome] teleported to (0, ${y}, 0) facing +Z. World regen failed — try regenHere() manually.`);
    }
};
// v675 — manual chunk-rebuild hammer for "I see nothing but sky" debugging.
// Calls world.regenerate() at the current camera position. Use when chunks
// are stale (e.g. after a large teleport, or if the streamer fell behind).
window.regenHere = () => {
    try {
        world.regenerate();
        console.log(`[regenHere] regenerated chunks around camera (${camera.position.x.toFixed(0)}, ${camera.position.y.toFixed(0)}, ${camera.position.z.toFixed(0)})`);
    } catch (e) {
        console.warn("[regenHere] failed:", e?.message ?? e);
    }
};
// v676 — recovery command for "render locked up after going to background".
// The Page Visibility API can leave the engine in a stuck state on some
// browser/GPU combinations (Chrome on Pascal-era cards seems prone to it).
// This command:
//   1. Disables bloom (the bloom pass is the most common render-stall culprit)
//   2. Forces visibility back to "visible" so frame-skip stops
//   3. Forces world.regenerate() to re-mesh chunks
//   4. Logs the engine state for diagnosis
// If unstick() doesn't fix it, a hard reload (Ctrl+Shift+R) is the fallback.
window.unstick = () => {
    const report = {};
    try {
        // 1. Disable bloom — common cause of black-screen after resume on some GPUs
        if (typeof bloomPass !== "undefined" && bloomPass) {
            report.bloomWas = bloomPass._enabled !== false;
            bloomPass._enabled = false;
        }
        // 2. Force visibility to "visible"
        if (window.visibility?._state === "hidden") {
            window.visibility._state = "visible";
            window.visibility._frameSinceLastRender = 0;
            report.visibilityWas = "hidden";
        }
        // 3. Regenerate chunks at current position
        world.regenerate();
        report.chunks = world.chunks?.size ?? "?";
        report.gridRadius = world.gridRadius;
        report.cameraPos = `(${camera.position.x.toFixed(1)}, ${camera.position.y.toFixed(1)}, ${camera.position.z.toFixed(1)})`;
        report.demoIsolation = window._demoIsolation;
        report.currentDemo = window.demoManager?.current?.id;
        console.log("[unstick] recovery attempted:", report);
        console.log("[unstick] if render is still frozen, try Ctrl+Shift+R to fully reload. Pass back this report for further diagnosis.");
    } catch (e) {
        console.warn("[unstick] failed mid-recovery:", e?.message, "partial report:", report);
    }
};
if (!camResult || !camResult.ok) {
    const rx = (Math.random() * 2 - 1) * 110;
    const rz = (Math.random() * 2 - 1) * 110;
    let gy = 40;
    try { gy = (world._heightAt ? (world._heightAt(rx, rz) | 0) : 30) + 18; } catch {}
    camera.position.x = rx;
    camera.position.y = gy;
    camera.position.z = rz;
    camera.yaw = 0;   // v1735 - face a fixed front (was random) so the world does not spawn mid-spin (#2)
    camera.pitch = -0.32;
    console.log(`[main] fresh start — camera at random spot (${rx.toFixed(0)}, ${gy}, ${rz.toFixed(0)}). resumeCamera(true) to keep your view across reloads.`);
}
// v1986 — deterministic repro: if ?cam / ?preset provided a camera, pin it now (overrides the random/resume
// spawn above) so a shared link reproduces the exact view. Seed was already applied at the top, pre-worldgen.
try { if (_reproParams && _reproParams.cam) reproParams.applyCamera(camera, _reproParams); } catch (e) { console.warn("[repro] camera apply skipped:", e && e.message); }

// v1735 - lock camera rotation until the floor has drawn, so the world can't be spun (mouse/drag/gamepad) during load (#2).
// Released as soon as terrain chunks stream in around the spawn, or after a safety timeout no matter what.
try {
    if (camera.lockRotation) {
        camera.lockRotation(7000);
        const _floorT0 = performance.now();
        const _floorPoll = setInterval(() => {
            let n = 0; try { n = world.chunks.size; } catch {}
            if (n >= 4 || performance.now() - _floorT0 > 7000) { try { camera.unlockRotation(); } catch {} clearInterval(_floorPoll); }
        }, 150);
    }
} catch {}

// Round 29 — biome system. BiomeMap is a deterministic procedural
// classifier (5 biomes via 2-octave value noise); BiomePainter walks
// a 200x200 region around origin and modifies surface voxels per
// biome (snow caps, ash, lava, sand patches). Painter is one-shot
// per-world (localStorage flag) — first load paints, subsequent
// loads skip since persistence saved the modifications.
// v339 — terrain seed is read from localStorage so freshWorld() can
// randomize it. Default 1337 preserves identical worlds across reloads
// (deterministic procedural gen). Random seed = new mountains, new
// biome layout, new kaiju spawn spots.
function _getWorldSeed() {
    try {
        const v = localStorage.getItem("voxelengine.worldSeed");
        if (v != null && /^\d+$/.test(v)) return parseInt(v, 10);
    } catch {}
    return 1337;
}
const _WORLD_SEED = _getWorldSeed();
const biomeMap = new BiomeMap({ seed: _WORLD_SEED });
const biomePainter = new BiomePainter({
    world,
    biomeMap,
    region: 200,
    center: { x: 0, z: 0 },
});
biomePainter.paint();

// Round 33 — caves + ruins. Both are one-shot terrain decoration
// gated by their own localStorage flags. Caves carve underground
// tunnels via 3D noise; ruins stamp weathered megastructures on
// surface in plains/jungle biomes.
// v359 — derive a single world seed from worldSeed.js so caves, decor,
// and any future generators share determinism across reloads.
const WORLD_SEED = ensureSeeded();
const caveCarver = new CaveCarver({ world, region: 200, center: { x: 0, z: 0 }, seed: WORLD_SEED });
caveCarver.carve();
const ruinPlacer = new RuinPlacer({ world, biomeMap, region: 180, count: 8 });
ruinPlacer.place();

// v429 — biome/cave/ruin painting calls setVoxel, which marks every
// touched chunk _modified. That content regenerates deterministically
// on load (the painters re-run via their localStorage flags), so saving
// it is pointless AND blew localStorage quota (a fresh world carves ~98k
// + paints ~43k voxels → multi-MB diff → "autosave failed: quota" every
// 30s, plus the wasted serialization stutter). Clear _modified now so the
// procedural baseline isn't persisted; only genuine post-boot edits save.
{
    let _cleared = 0;
    for (const c of world.chunks.values()) { if (c._modified) { c._modified = false; _cleared++; } }
    if (_cleared) console.log(`[main] marked ${_cleared} procedurally-generated chunks as baseline (kept out of save diff)`);
}

// Round 214 — re-decorate after every world.regenerate(). The painter
// + carver + ruin placer were one-shot per browser via localStorage;
// every demo that called world.regenerate() (lunar lander, OGRE, etc.)
// silently wiped the biome decoration and we never re-applied. The
// onRegenerate hook fixes that: each regen re-runs the same painters
// in force mode so the rich landscape persists across demos.
let _regenDecorPool = null;     // forward-declared, filled below
world.onRegenerate(() => {
    // v550 — abstract demos (no `terrain` flag) get NO biome paint, ruins,
    // or decor props, and we drop any decor entities a prior terrain demo
    // left behind. Only terrain demos re-decorate.
    const wantTerrain = (typeof window === "undefined" || window._demoWantsTerrain !== false);
    if (!wantTerrain) {
        if (_regenDecorPool) { try { _regenDecorPool.clear?.(); } catch {} }
        return;
    }
    try {
        biomePainter.paint({ force: true });
        caveCarver.carve({ force: true });
        ruinPlacer.place({ force: true });
        // v429 — same baseline treatment as the boot path: keep the
        // regenerated procedural voxels out of the save diff.
        for (const c of world.chunks.values()) c._modified = false;
    } catch (e) {
        console.warn("[regen-decor] re-paint failed:", e?.message ?? e);
    }
    // Re-fan-out the worker decoration pool too. v550 — clear the OLD props
    // first; previously plan() ran without clearing, so biome decor also
    // accumulated across demo switches.
    if (_regenDecorPool) {
        try { _regenDecorPool.clear?.(); } catch {}
        _regenDecorPool.plan({ region: 200, density: 1.0 }).catch(() => {});
    }
});

// Round 32 — weather + day/night cycle. Drives sun rotation +
// weather state (clear/cloudy/rain/snow/storm) + particle effects.
// Updates skyRenderer colors + sun direction each frame; voxel
// renderer's fogColor uniform tracks horizonColor. events ref
// patched in after civEvents is constructed (sequencing).
const weatherSystem = new WeatherSystem({
    particles,
    biomeMap,
});
window.weatherSystem = weatherSystem;   // v519 — used by remote control panel

// v823 — Day/night cycle + weather control API.
// The WeatherSystem already advances timeOfDay and chooses weather
// states autonomously. These helpers let the player/dev override:
//   * jump to specific times (noon, dusk, etc.)
//   * pause + speed time
//   * pin a weather state (override the auto state machine)
//   * read current state + label
// All changes go through the same WeatherSystem fields the renderer
// already reads, so they propagate next frame without further wiring.
window.dayNight = {
    // Read
    get t()      { return weatherSystem.timeOfDay; },
    get label()  { return weatherSystem.timeOfDayLabel(); },
    get cycleSec(){ return weatherSystem.cycleSeconds; },
    get paused() { return !!weatherSystem._paused; },
    // Set absolute time (0=midnight, 0.25=sunrise, 0.5=noon, 0.75=sunset)
    setTime(t) {
        const v = Math.max(0, Math.min(0.999, Number(t) || 0));
        weatherSystem.timeOfDay = v;
        return weatherSystem.timeOfDayLabel();
    },
    // Presets — match WeatherSystem.timeOfDayLabel() boundaries
    midnight() { return window.dayNight.setTime(0.00); },
    predawn()  { return window.dayNight.setTime(0.15); },
    dawn()     { return window.dayNight.setTime(0.25); },
    morning()  { return window.dayNight.setTime(0.35); },
    noon()     { return window.dayNight.setTime(0.50); },
    afternoon(){ return window.dayNight.setTime(0.60); },
    dusk()     { return window.dayNight.setTime(0.75); },
    evening()  { return window.dayNight.setTime(0.85); },
    // Pause/play (intercept .tick by zeroing delta-of-time)
    pause()  { weatherSystem._paused = true;  return "paused at " + weatherSystem.timeOfDayLabel(); },
    play()   { weatherSystem._paused = false; return "playing"; },
    toggle() { weatherSystem._paused = !weatherSystem._paused; return weatherSystem._paused ? "paused" : "playing"; },
    // Cycle length (real seconds per in-game day). Default ~600s.
    setCycle(seconds) {
        const s = Math.max(10, Math.min(86400, Number(seconds) || 600));
        weatherSystem.cycleSeconds = s;
        return `cycle = ${s}s/day`;
    },
    // Fast-forward to a time without skipping weather state aging.
    // Useful for "skip to dawn" without changing weather.
    advanceTo(t) { return window.dayNight.setTime(t); },
    // v824 — derived weather readings
    get windSpeed()   { return weatherSystem._derived?.windSpeed ?? 0; },
    get temperature() { return weatherSystem._derived?.temperature ?? 15; },
    get nightT()      { return weatherSystem._derived?.nightT ?? 0; },   // 0 day, 1 night
    // v825 — lunar phase. 0 = new moon (dark), 0.5 = full moon (bright), 1 = new again.
    get lunarPhase() {
        const lunarAge = ((weatherSystem._lunarDay ?? 0) + weatherSystem.timeOfDay) % 29.5;
        return lunarAge / 29.5;
    },
    get lunarDay()   { return weatherSystem._lunarDay ?? 0; },
    get lunarLabel() {
        const p = window.dayNight.lunarPhase;
        if (p < 0.03 || p > 0.97) return "new moon";
        if (p < 0.22) return "waxing crescent";
        if (p < 0.28) return "first quarter";
        if (p < 0.47) return "waxing gibbous";
        if (p < 0.53) return "full moon";
        if (p < 0.72) return "waning gibbous";
        if (p < 0.78) return "last quarter";
        return "waning crescent";
    },
    setLunarDay(d) {
        const v = Math.max(0, Math.min(29.5, Number(d) || 0));
        weatherSystem._lunarDay = v;
        return `lunar day = ${v.toFixed(2)} (${window.dayNight.lunarLabel})`;
    },
};

// v823 — Weather override API (sits alongside dayNight). The
// WeatherSystem already has a state field; the random state machine
// reasserts itself every 60-120s. Use .pin() to lock a state until
// you call .unpin().
window.weather = window.weather || {};
Object.assign(window.weather, {
    get state()   { return weatherSystem.state; },
    get pinned()  { return !!weatherSystem._pinned; },
    setState(s) {
        const known = ["clear", "cloudy", "rain", "snow", "storm", "blizzard"];
        if (!known.includes(s)) return { error: `unknown state '${s}'. Known: ${known.join(", ")}` };
        const old = weatherSystem.state;
        weatherSystem.state = s;
        weatherSystem._stateAge = 0;
        // v856 — engine event on explicit setState transitions
        if (s !== old) {
            try {
                window.dispatchEvent(new CustomEvent("engine:weatherChanged", {
                    detail: { kind: s, prev: old, manual: true },
                }));
            } catch {}
        }
        return { ok: true, state: s };
    },
    pin(s) {
        if (s) window.weather.setState(s);
        weatherSystem._pinned = true;
        return `pinned to '${weatherSystem.state}'`;
    },
    unpin() {
        weatherSystem._pinned = false;
        return "unpinned (auto state machine resumes)";
    },
    clear()    { return window.weather.setState("clear"); },
    cloudy()   { return window.weather.setState("cloudy"); },
    rain()     { return window.weather.setState("rain"); },
    snow()     { return window.weather.setState("snow"); },
    storm()    { return window.weather.setState("storm"); },
    blizzard() { return window.weather.setState("blizzard"); },
});

// v823 — Patch WeatherSystem.tick to honor pause + pin without forking
// the file. We wrap the original method.
(function patchWeatherTick() {
    const origTick = weatherSystem.tick.bind(weatherSystem);
    weatherSystem.tick = function (delta, camera) {
        // If paused: don't advance timeOfDay or state machine.
        if (this._paused) {
            // Recompute sun colors using current timeOfDay (call with 0 delta
            // to keep sky/sun in sync if any external mutation happened).
            return origTick(0, camera);
        }
        // If pinned: capture state, run tick, restore state if it drifted.
        if (this._pinned) {
            const pinned = this.state;
            const r = origTick(delta, camera);
            if (this.state !== pinned) {
                // _pickNextState fired — undo
                this.state = pinned;
                this._stateAge = 0;
            }
            return r;
        }
        return origTick(delta, camera);
    };
})();

// v823 — On-screen HUD showing current time + weather. Lightweight
// DOM overlay top-right of canvas. Click to toggle 12/24h. Updated
// once per second from the same frame loop the engine drives.
(function dayNightHud() {
    if (typeof document === "undefined") return;
    const hud = document.createElement("div");
    hud.id = "dayNightHud";
    Object.assign(hud.style, {
        position: "fixed",
        top: "8px", right: "8px",
        background: "rgba(0, 0, 0, 0.45)",
        color: "#cfe", fontFamily: "monospace",
        fontSize: "11px", padding: "4px 8px",
        borderRadius: "3px",
        pointerEvents: "auto", cursor: "pointer", userSelect: "none",
        zIndex: "200",
        display: "none",   // hidden until first tick paints it
        border: "1px solid rgba(140, 200, 255, 0.18)",
    });
    document.body.appendChild(hud);
    // v825 — HUD format preference loaded from restored state; falls back to 24h
    let use24h = weatherSystem._hudFormat24h ?? true;
    hud.addEventListener("click", () => {
        use24h = !use24h;
        weatherSystem._hudFormat24h = use24h;
        _saveDayNight();    // persist immediately on toggle
    });
    let lastShown = 0;
    let _hudOff = false;   // v1974 — hard off switch the tick respects, so the retired top-right timer stays gone
    window.dayNight._tickHud = function() {
        if (_hudOff) return;   // v1974 — retired timer: never paint/reveal it
        const now = performance.now();
        if (now - lastShown < 250) return;     // throttle to ~4Hz
        lastShown = now;
        const t = weatherSystem.timeOfDay;
        const totalMin = Math.floor(t * 24 * 60);
        const hh = Math.floor(totalMin / 60);
        const mm = totalMin % 60;
        let timeStr;
        if (use24h) {
            timeStr = `${String(hh).padStart(2, "0")}:${String(mm).padStart(2, "0")}`;
        } else {
            const ampm = hh < 12 ? "am" : "pm";
            const h12 = hh === 0 ? 12 : (hh > 12 ? hh - 12 : hh);
            timeStr = `${h12}:${String(mm).padStart(2, "0")}${ampm}`;
        }
        const weatherIcon = {
            clear: "☀", cloudy: "☁", rain: "🌧", snow: "❄", storm: "⛈", blizzard: "🌨",
        }[weatherSystem.state] || "·";
        const pausedTag = weatherSystem._paused ? " ⏸" : "";
        const pinTag = weatherSystem._pinned ? " 📌" : "";
        // v824 — show wind + temperature derived from current weather state
        const d = weatherSystem._derived || {};
        let extra = "";
        if (typeof d.temperature === "number") {
            const tStr = (d.temperature >= 0 ? "+" : "") + d.temperature.toFixed(0) + "°";
            const wStr = d.windSpeed > 0 ? ` · ${d.windSpeed.toFixed(0)}m/s` : "";
            extra = ` · ${tStr}${wStr}`;
        }
        hud.style.display = "";
        hud.textContent = `${timeStr} · ${weatherIcon} ${weatherSystem.state}${extra}${pausedTag}${pinTag}`;
    };
    // Allow hiding entirely
    window.dayNight.showHud = () => { _hudOff = false; hud.style.display = ""; };
    window.dayNight.hideHud = () => { _hudOff = true; hud.style.display = "none"; };
    try { window.dayNight.hideHud(); } catch {}   // v1579 retired the top-right timer; v1974 makes the hide stick (tick respects _hudOff)
})();

// v824 — F-key shortcuts for the day/night presets. F1 is reserved
// for the perf overlay; we use F2-F6. The browser swallows some
// F-keys (F11 fullscreen, F12 devtools) but F2-F6 are reliably
// available across Chrome/Firefox/Edge.
window.addEventListener("keydown", (e) => {
    if (!window.dayNight) return;
    // Allow typing in inputs without triggering shortcuts
    const ae = document.activeElement;
    if (ae && (ae.tagName === "INPUT" || ae.tagName === "TEXTAREA" || ae.isContentEditable)) return;
    let handled = true;
    if (e.code === "F2") window.dayNight.dawn();
    else if (e.code === "F3") window.dayNight.noon();
    else if (e.code === "F4") window.dayNight.dusk();
    else if (e.code === "F5") window.dayNight.midnight();
    else if (e.code === "F6") window.dayNight.toggle();
    else if (e.key === "?" && !e.repeat) window.dayNight.showHelp();
    else handled = false;
    if (handled) e.preventDefault();
});

// v825 — Keymap help dialog. Triggered by `?` key or window.dayNight.showHelp().
// Self-contained DOM overlay; ESC or click outside closes.
(function helpOverlay() {
    if (typeof document === "undefined") return;
    let overlay = null;
    window.dayNight.showHelp = () => {
        if (overlay) return;       // already open
        overlay = document.createElement("div");
        Object.assign(overlay.style, {
            position: "fixed", inset: "0",
            background: "rgba(0, 0, 0, 0.55)",
            display: "flex", alignItems: "center", justifyContent: "center",
            zIndex: "2200", cursor: "pointer",
        });
        const dlg = document.createElement("div");
        Object.assign(dlg.style, {
            background: "rgba(18, 24, 36, 0.97)",
            border: "1px solid rgba(140, 200, 255, 0.3)",
            borderRadius: "8px", padding: "18px 22px",
            color: "#cde", fontSize: "12px",
            fontFamily: "monospace", lineHeight: "1.6",
            minWidth: "320px", maxWidth: "480px",
            cursor: "default",
        });
        dlg.addEventListener("click", (e) => e.stopPropagation());
        dlg.innerHTML = `
            <div style="font-size:14px;font-weight:600;color:#bfe;margin-bottom:10px">⌨ Keyboard Shortcuts</div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:18px">
                <div>
                    <div style="font-size:11px;color:#7af;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:6px;border-bottom:1px solid #234;padding-bottom:3px">Day / Night</div>
                    <div style="display:grid;grid-template-columns:50px 1fr;gap:3px 10px">
                        <kbd style="text-align:right;color:#9cf">F2</kbd><span>Jump to dawn</span>
                        <kbd style="text-align:right;color:#9cf">F3</kbd><span>Jump to noon</span>
                        <kbd style="text-align:right;color:#9cf">F4</kbd><span>Jump to dusk</span>
                        <kbd style="text-align:right;color:#9cf">F5</kbd><span>Jump to midnight</span>
                        <kbd style="text-align:right;color:#9cf">F6</kbd><span>Pause / play time</span>
                    </div>
                </div>
                <div>
                    <div style="font-size:11px;color:#7af;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:6px;border-bottom:1px solid #234;padding-bottom:3px">Diagnostics</div>
                    <div style="display:grid;grid-template-columns:50px 1fr;gap:3px 10px">
                        <kbd style="text-align:right;color:#9cf">F1</kbd><span>Perf overlay</span>
                        <kbd style="text-align:right;color:#9cf">\`</kbd><span>Perf overlay (alt)</span>
                        <kbd style="text-align:right;color:#9cf">?</kbd><span>Show this help</span>
                        <kbd style="text-align:right;color:#9cf">Esc</kbd><span>Close this help</span>
                    </div>
                </div>
                <div style="grid-column:1/-1">
                    <div style="font-size:11px;color:#7af;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:6px;border-bottom:1px solid #234;padding-bottom:3px">Camera / Rig</div>
                    <div style="display:grid;grid-template-columns:70px 1fr 70px 1fr;gap:3px 10px">
                        <kbd style="text-align:right;color:#9cf">WASD</kbd><span>Move</span>
                        <kbd style="text-align:right;color:#9cf">Space</kbd><span>Up / fire</span>
                        <kbd style="text-align:right;color:#9cf">Shift</kbd><span>Down / strafe</span>
                        <kbd style="text-align:right;color:#9cf">Drag</kbd><span>Look around</span>
                        <kbd style="text-align:right;color:#9cf">Shift+LMB</kbd><span>Drag rig bones (rig editor)</span>
                        <kbd style="text-align:right;color:#9cf">Click HUD</kbd><span>Toggle 12/24h time</span>
                    </div>
                </div>
            </div>
            <div style="font-size:11px;color:#789;margin-top:14px;border-top:1px solid #234;padding-top:10px">
                Console: <code style="color:#cde">window.dayNight</code> · <code style="color:#cde">window.weather</code> · <code style="color:#cde">window.debugDraw</code> · <code style="color:#cde">window.worldLabels</code>
            </div>
            <div style="text-align:right;margin-top:14px">
                <button style="background:#345;color:#cde;border:1px solid #567;border-radius:4px;padding:5px 12px;cursor:pointer;font-size:11px;font-family:inherit" id="dnHelpClose">Close (Esc)</button>
            </div>
        `;
        overlay.appendChild(dlg);
        const close = () => { try { document.body.removeChild(overlay); } catch {} overlay = null; };
        overlay.addEventListener("click", close);
        dlg.querySelector("#dnHelpClose").addEventListener("click", close);
        const esc = (e) => {
            if (e.key === "Escape") {
                e.preventDefault();
                close();
                window.removeEventListener("keydown", esc, true);
            }
        };
        window.addEventListener("keydown", esc, true);
        document.body.appendChild(overlay);
    };
})();

// v824 — save/restore for timeOfDay + weather state. Uses localStorage
// (not the world IDB payload) because the values are small + structured
// and we want them to apply before the first weather tick. Saved every
// 10s + on beforeunload; restored synchronously during init below.
const DAYNIGHT_LS_KEY = "engine:dayNight:v1";
function _saveDayNight() {
    try {
        localStorage.setItem(DAYNIGHT_LS_KEY, JSON.stringify({
            timeOfDay:     weatherSystem.timeOfDay,
            state:         weatherSystem.state,
            stateAge:      weatherSystem._stateAge,
            paused:        !!weatherSystem._paused,
            pinned:        !!weatherSystem._pinned,
            cycleSeconds:  weatherSystem.cycleSeconds,
            lunarDay:      weatherSystem._lunarDay,      // v825 — lunar phase
            hudFormat24h:  weatherSystem._hudFormat24h ?? true,   // v825 — HUD pref
            savedAt:       Date.now(),
        }));
    } catch (e) { /* quota or unavailable — silent */ }
}
function _restoreDayNight() {
    try {
        const raw = localStorage.getItem(DAYNIGHT_LS_KEY);
        if (!raw) return false;
        const d = JSON.parse(raw);
        if (typeof d.timeOfDay === "number") weatherSystem.timeOfDay = d.timeOfDay;
        if (typeof d.state === "string")     weatherSystem.state = d.state;
        if (typeof d.stateAge === "number")  weatherSystem._stateAge = d.stateAge;
        if (typeof d.paused === "boolean")   weatherSystem._paused = d.paused;
        if (typeof d.pinned === "boolean")   weatherSystem._pinned = d.pinned;
        if (typeof d.cycleSeconds === "number") weatherSystem.cycleSeconds = d.cycleSeconds;
        if (typeof d.lunarDay === "number")  weatherSystem._lunarDay = d.lunarDay;     // v825
        if (typeof d.hudFormat24h === "boolean") weatherSystem._hudFormat24h = d.hudFormat24h;
        console.log(`[dayNight] restored: t=${weatherSystem.timeOfDay.toFixed(3)} state=${weatherSystem.state}${d.paused ? " ⏸" : ""}${d.pinned ? " 📌" : ""}`);
        return true;
    } catch (e) {
        console.warn("[dayNight] restore failed:", e?.message);
        return false;
    }
}
// Restore immediately (synchronous) — must happen before first tick
_restoreDayNight();
// Autosave every 10s + on unload + on tab-hidden (mobile-safe)
setInterval(_saveDayNight, 10_000);
window.addEventListener("beforeunload", _saveDayNight);
// v825 — visibilitychange handler. iOS/Android browsers sometimes skip
// beforeunload (tab swipe-close, app backgrounded). Save when the tab
// becomes hidden so mobile users don't lose their state.
document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") _saveDayNight();
});
// Expose for manual control
window.dayNight.save    = _saveDayNight;
window.dayNight.restore = _restoreDayNight;
window.dayNight.clear   = () => { try { localStorage.removeItem(DAYNIGHT_LS_KEY); return "cleared"; } catch { return "failed"; } };

// Round 157 — atmosphere layer. Self-contained module owning a cloud
// sprite layer at sky altitude + lightning streak visualizer that
// fires on storm flashes. Reads weather state each tick. Renders
// after sky, before opaque entities so terrain can occlude clouds.
const atmosphereSystem = new AtmosphereSystem(gl, weatherSystem);
// v1278 — clouds. #1 cloud shadows (in the voxel shader) + #2 volumetric layer,
// both toggled in Settings -> Graphics (Render), persisted in localStorage. Default off.
// v1279 — own key "voxelengine.cloudsFx" so it can't collide with the sprite-cloud
// layer's "voxelengine.clouds" (which stores a type string, not JSON).
const cloudVolume = new CloudVolume(gl);
const _cloudCfg = (() => { try { return JSON.parse(localStorage.getItem("voxelengine.cloudsFx") || "{}"); } catch { return {}; } })();
// v2371 -- volumetric clouds ON by default (CloudVolume already self-shadows against the orbiting sun via a per-frame
// setSun + light-march; it was just gated off). A saved toggle still wins; ?clouds=flat forces the cheap billboard
// layer, ?clouds=volumetric forces the raymarch. This is why index.html now shows the sun lighting the clouds in 3D.
{ try { const u = new URLSearchParams(location.search).get("clouds");
    if (u === "flat") _cloudCfg.volumetric = false; else if (u === "volumetric") _cloudCfg.volumetric = true;
    else if (_cloudCfg.volumetric === undefined) _cloudCfg.volumetric = true; } catch {} }
function applyCloudSettings(){
    renderer.cloudShadow = { on: !!_cloudCfg.shadows, coverage: _cloudCfg.coverage ?? 0.5, scale: _cloudCfg.scale ?? 0.0035, darken: _cloudCfg.darken ?? 0.45 };
    if (cloudVolume) cloudVolume.enabled = !!_cloudCfg.volumetric;
}
function setCloudSetting(key, val){ _cloudCfg[key] = val; try { localStorage.setItem("voxelengine.cloudsFx", JSON.stringify(_cloudCfg)); } catch {} applyCloudSettings(); }
window.cloudSettings = { get: () => ({ ..._cloudCfg }), set: setCloudSetting };
applyCloudSettings();
// small persistent toggles (Settings panel isn't instantiated in this build, so this
// is the reliable "checkbox setting" surface). Bottom-left, dim until enabled.
try {
    addEventListener("DOMContentLoaded", () => {
        const wrap = document.createElement("div");
        wrap.style.cssText = "position:fixed;left:8px;bottom:8px;z-index:99997;display:flex;gap:6px;font:11px system-ui;";
        const mk = (key, label, title) => {
            const b = document.createElement("button");
            b.title = title; b.textContent = label;
            b.style.cssText = "padding:5px 9px;border-radius:7px;border:1px solid #2a4a66;background:#0b1622;color:#9fd0ff;cursor:pointer;opacity:0.5;";
            const sync = () => { const on = !!_cloudCfg[key]; b.style.opacity = on ? "1" : "0.5"; b.style.borderColor = on ? "#5fa8e0" : "#243a4a"; };
            b.addEventListener("click", () => { setCloudSetting(key, !_cloudCfg[key]); sync(); });
            sync(); return b;
        };
        wrap.appendChild(mk("shadows", "☁ Shadows", "Cloud shadows on the ground (cheap)"));
        wrap.appendChild(mk("volumetric", "☁ Volumetric", "Raymarched volumetric clouds (heavier — tune on your rig)"));
        document.body.appendChild(wrap);
    });
} catch (e) {}

// Autosave every 30s + on unload — small enough to not stall the loop,
// frequent enough that an accidental tab close doesn't lose much.
//
// Round 168 (v663) — persistence is now IndexedDB-backed (v662 had a
// localStorage quota circuit breaker; v663 removed the 5MB cap entirely
// by switching backends). IDB writes are async + non-blocking + support
// Uint8Arrays directly (no base64 inflate). Saves no longer stall the
// main thread; the every-30s lockup pattern is gone.
//
// The circuit breaker stays as defense-in-depth — IDB can theoretically
// hit quota too (full disk, restrictive browser policy, private browsing),
// but in practice almost never does.
const _autosaveHandle = setInterval(async () => {
    const r = await persistence.save();
    persistence.saveCamera(camera);
    if (!r.ok) {
        if (r.fatalQuota) {
            console.warn(
                `[main] autosave disabled this session — IndexedDB quota exceeded` +
                (r.jsonBytes ? ` (~${(r.jsonBytes/1024/1024).toFixed(1)}MB payload)` : ``) +
                `. Storage is full or restricted. Options:\n` +
                `  • hardResetWorld()             — wipe everything and start fresh\n` +
                `  • persistence.resumeAutosave() — retry after freeing browser storage\n` +
                `  • navigator.storage.estimate().then(console.log) — see what's available\n` +
                `  • ignore — engine plays fine, you just lose this session on tab close`
            );
            clearInterval(_autosaveHandle);
        } else {
            console.warn(`[main] autosave failed: ${r.error}`);
        }
    }
}, 30_000);
window._autosaveHandle = _autosaveHandle;   // exposed so persistence.resumeAutosave can re-arm

window.addEventListener("beforeunload", () => {
    // Fire-and-forget. IDB transactions don't await reliably during unload,
    // but modern browsers usually let in-flight transactions complete. If
    // they don't, the next autosave cycle picks up the work — we lose at
    // most one 30s window of edits, same as the v662 behavior.
    persistence.save();
    persistence.saveCamera(camera);
});

// ----------------------------------------------------------------------
// NETWORK + EXCEL BRIDGE — unchanged
// ----------------------------------------------------------------------
const net    = new NetClient();
const router = new CommandRouter(world, net);
const bridge = new WSBridge(router);
// v735 — expose globally so UI panels (Shield debug panel etc) can
// subscribe to typed messages via bridge.on("shield:logcat:line", fn).
try { window._wsBridge = bridge; } catch {}

// v742 — engine console capture. When the bridge broadcasts
// {type:"debug:capture:state", on:true} we wrap console.log/info/warn/
// error to ALSO push each call to the bridge as a debug:push msg. The
// browser debug viewer (/debug.html) renders them alongside Shield
// logcat + phone TV Remote status. Idempotent: subscribing while
// already captured is a no-op; on:false restores the original methods.
(function setupConsoleCapture() {
    const ORIG = { log: console.log.bind(console), info: console.info.bind(console),
                   warn: console.warn.bind(console), error: console.error.bind(console) };
    let capturing = false;
    function fmt(args) {
        try {
            return args.map(a => {
                if (typeof a === "string") return a;
                if (a instanceof Error)    return a.message + (a.stack ? "\n" + a.stack.split("\n").slice(0, 4).join("\n") : "");
                try { return JSON.stringify(a); } catch { return String(a); }
            }).join(" ");
        } catch { return "(unserializable)"; }
    }
    function push(level, args) {
        try {
            // v969 — benign "optional service isn't running" noise should NOT
            // raise alarm in the debug views / avatar. Downgrade known patterns
            // from error/warn to info so they're still visible but not flagged.
            if ((level === "error" || level === "warn") && window._benignError && window._benignError(fmt(args))) level = "info";
            if (bridge?.ws?.readyState === 1) {
                bridge.ws.send(JSON.stringify({
                    type: "debug:push", src: "engine", level, line: fmt(args).slice(0, 2000),
                }));
            }
        } catch {}
    }
    function setOn(on) {
        if (on === capturing) return;
        if (on) {
            console.log   = (...a) => { ORIG.log(...a);   push("log",   a); };
            console.info  = (...a) => { ORIG.info(...a);  push("info",  a); };
            console.warn  = (...a) => { ORIG.warn(...a);  push("warn",  a); };
            console.error = (...a) => { ORIG.error(...a); push("error", a); };
            capturing = true;
            ORIG.info("[debug-capture] engine console mirroring ON");
        } else {
            console.log   = ORIG.log;
            console.info  = ORIG.info;
            console.warn  = ORIG.warn;
            console.error = ORIG.error;
            capturing = false;
            ORIG.info("[debug-capture] engine console mirroring OFF");
        }
    }
    // Listen for the state broadcast via the WSBridge typed-message API.
    bridge.on("debug:capture:state", (m) => setOn(!!m.on));
    // Expose a manual handle for console-driven testing
    try { window._debugCapture = { on: () => setOn(true), off: () => setOn(false), state: () => capturing }; } catch {}
})();

// v746 — engine startup banner. Fires once when the bridge WS first
// connects, regardless of debug-capture state, so the unified debug
// viewer always shows a clear "engine X.X.X connected" line when the
// browser tab loads. Re-fires on reconnect after a break (e.g. bridge
// restart) so the user can see clean session boundaries.
(function setupStartupBanner() {
    let hasSentSinceConnect = false;
    function pushBanner() {
        try {
            if (bridge?.ws?.readyState !== 1) return;
            const ua = (navigator.userAgent || "").slice(0, 80);
            const renderer = probeGpuString();   // v2777 - cached + releases its throwaway context (was leaking one per WS reconnect)
            const banner = `[engine ${ENGINE_VERSION}] booted · ${ua.split(") ")[0].split("(").pop() || "browser"} · GPU: ${renderer}`;
            bridge.ws.send(JSON.stringify({ type: "debug:push", src: "engine", level: "info", line: banner }));
            // Also push a multi-line "ready" stamp so the viewer can spot
            // engine restart boundaries even mid-session.
            const url = location.pathname + (location.hash || "");
            bridge.ws.send(JSON.stringify({ type: "debug:push", src: "engine", level: "info", line: `[engine ${ENGINE_VERSION}] page=${url} ts=${new Date().toLocaleString()}` }));
        } catch {}
    }
    // The WSBridge sets bridge.connected and calls console.log on open.
    // We poll briefly until connected, then push the banner.
    let attempts = 0;
    const tick = () => {
        attempts++;
        if (bridge?.connected && bridge.ws?.readyState === 1) {
            if (!hasSentSinceConnect) {
                pushBanner();
                hasSentSinceConnect = true;
            }
        } else {
            hasSentSinceConnect = false;   // reset so we re-banner after a reconnect
        }
        if (attempts < 600) setTimeout(tick, 1000);   // poll up to 10 minutes then stop
    };
    setTimeout(tick, 250);
})();

