        const ticker = document.createElement("div"); ticker.style.cssText = "padding:2px 14px 14px;overflow:auto;flex:1 1 auto;display:flex;flex-direction:column;gap:3px;";
        ov.append(hdr, svg, chips, logHdr, ticker); document.body.appendChild(ov); _naEl = ov;
