            const STATES = ["clear", "cloudy", "rain", "snow", "storm", "blizzard"];
            const FORCE  = ["rain", "storm", "mist", "snow"];
            const CLOUDS = ["cumulus", "cumulonimbus", "stratus", "stratocumulus", "cirrus", "nimbostratus"];
            const TIME   = { day: "noon", night: "midnight", dawn: "dawn", dusk: "dusk", noon: "noon", morning: "morning", evening: "evening", afternoon: "afternoon" };
            let did = null;
            if (FORCE.includes(cmd)) { window.weather?.force?.(cmd); did = "weather → " + cmd; }
            else if (STATES.includes(cmd)) { window.weather?.setState?.(cmd); did = "weather → " + cmd; }
            else if (["clearsky", "sun", "sunny"].includes(cmd)) { window.weather?.clear?.(); window.clouds?.off?.(); did = "cleared"; }
            else if (cmd === "clouds") { if (!arg || arg === "off") { window.clouds?.off?.(); did = "clouds off"; } else if (CLOUDS.includes(arg)) { window.clouds?.set?.(arg); did = "clouds → " + arg; } }
            else if (TIME[cmd]) { window.dayNight?.[TIME[cmd]]?.(); did = "time → " + cmd; }
            else if (cmd === "sky" && TIME[arg]) { window.dayNight?.[TIME[arg]]?.(); did = "time → " + arg; }
            else if (cmd === "kaiju") { if (arg === "off" || arg === "stop") { window.kaijuSim?.stop?.(); did = "kaiju off"; } else { window.kaijuSim?.start?.(); did = "kaiju on"; } }
