// Round 90 — pre-register description prompts for every variant defined
// in gpu/assetVariants.js. So when the asset loader first encounters
// "tree_oak_2" (or any variant) and asks Ollama for an OBJ, the prompt
// is the specific variant description (e.g. "a young oak with full round
// canopy and slim trunk") rather than the generic _defaultDescription
// fallback. This makes each variant visually distinct.
(async () => {
    try {
        const { registerAllDescriptions, addRuntimeVariant } = await import("./gpu/assetVariants.js");
        const n = registerAllDescriptions(assetLoader);
        console.log(`[assetVariants] registered ${n} variant descriptions`);

        // Round 94 — register procedural dome+barrel meshes for OGRE
        // hardpoints (and the main chassis turret). Pre-cached so the
        // first hardpoint spawn renders as a real composite instead of
        // a cube. Bypasses Ollama entirely — these are hand-authored
        // geometry, not asset-pipeline driven.
        try {
            const { registerAllHardpointMeshes } = await import("./gpu/hardpointMeshes.js");
            registerAllHardpointMeshes(assetLoader);
        } catch (e) {
            console.warn("[hardpointMeshes] registration failed:", e);
        }

        // Round 91 — restore persisted runtime variants + failed names
        // from the ai-bridge. After this, VariantExpander's prior
        // additions (and the prior session's failed-OBJ names) are
        // back in play. Best-effort — bridge may not be running.
        try {
            const lr = await fetch("/variants/list", { cache: "no-cache" });
            if (lr.ok) {
                const { variants } = await lr.json();
                let restored = 0;
                for (const v of variants || []) {
                    const full = addRuntimeVariant(v.baseKind, v.suffix, v.description);
                    if (full) {
                        assetLoader.registerDescription(full, v.description);
                        restored++;
                    }
                }
                if (restored > 0) console.log(`[assetVariants] restored ${restored} persisted variants`);
            }
            const fr = await fetch("/variants/failed", { cache: "no-cache" });
            if (fr.ok) {
                const { names } = await fr.json();
                if (Array.isArray(names) && names.length > 0) {
                    assetLoader.seedFailedNames(names);
                    console.log(`[assetVariants] restored ${names.length} failed-OBJ names`);
                }
            }

            // Round 96 — auto-grow sparse variants. Opt-in via Settings
            // toggle "Auto-grow" (default OFF — saved to localStorage as
            // voxelEngine.autoGrowVariants). When ON: scan the catalog,
            // and for any base kind below SPARSE_THRESHOLD entries call
            // variantExpander.expand() to grow it. Runs once at startup,
            // 4 seconds after restore so the bridge has time to settle.
            // Each kind sequenced with a short pause so we don't slam
            // Ollama with 12 simultaneous generation requests.
            try {
                let prefOn = false;
                try { prefOn = (localStorage.getItem("voxelEngine.autoGrowVariants") === "1"); } catch {}
                if (prefOn) {
                    const { variantNames } = await import("./gpu/assetVariants.js");
                    const SPARSE_THRESHOLD = 3;
                    const TARGET = 3;
                    const SCAN_KINDS = [
                        "tree_oak", "tree_pine", "tree_palm",
                        "civ_ring_wall", "civ_plaza", "civ_spire_field", "civ_tower",
                        "kaiju_tech", "kaiju_space", "kaiju_hell", "kaiju_sky", "kaiju_ice",
                    ];
                    setTimeout(async () => {
                        // Late-bound — variantExpander is constructed
                        // farther down the file. Check globally so this
                        // doesn't crash if startup order shifts.
                        const expander = window.variantExpander || globalThis.variantExpander;
                        if (!expander?.expand) {
                            console.warn("[autoGrow] expander not ready; skipping");
                            return;
                        }
                        const sparse = [];
                        for (const k of SCAN_KINDS) {
                            // variantNames returns [base, ...suffixed]
                            const count = (variantNames(k) || []).length;
                            if (count < SPARSE_THRESHOLD) {
                                sparse.push({ kind: k, need: TARGET - count });
                            }
                        }
                        if (sparse.length === 0) {
                            console.log("[autoGrow] all kinds at or above threshold; nothing to do");
                            return;
                        }
                        console.log(`[autoGrow] ${sparse.length} sparse kinds — growing sequentially`);
                        for (const { kind, need } of sparse) {
                            try {
                                const added = await expander.expand(kind, need);
                                console.log(`[autoGrow] ${kind}: +${added}`);
                            } catch (e) {
                                console.warn(`[autoGrow] ${kind} failed:`, e?.message ?? e);
                            }
                            // Brief pause between kinds to keep Ollama load steady
                            await new Promise(r => setTimeout(r, 400));
                        }
                        console.log("[autoGrow] startup scan complete");
                    }, 4000);
                }
            } catch (e) {
                console.warn("[autoGrow] startup scan failed:", e);
            }
        } catch (e) {
            // Bridge unreachable — fine, run with the hand-authored catalog only
        }
    } catch (e) {
        console.warn("[assetVariants] description registration failed:", e);
    }
})();
