// v436 — SWIMMER LOCOMOTION. Rigged fish/eels undulate via their swim
// clip; this drives the whole entity through the water — wander, gentle
// turns, vertical bob, and a reflecting boundary box — so they actually
// swim *around* rather than in place. Ticked from the render loop.
const _rigSwimmers = [];
let _rigYawOffset = 0;   // global facing tweak (see rig.swimTune)
// v437 (A) — terrain height for keeping swimmers above ground / walkers on it.
// v677 — in BLANK SANDBOX / exclusive-isolation modes the voxel world is
// hidden behind a wad_plate "stage" entity. world._heightAt returns the
// raw terrain height (≈0 in the void) which pulled swimmers down BELOW
// the stage. Now: if isolation is active and a stage floor exists, return
// its top Y so creatures sit on the stage instead.
const _terrainTopAt = (x, z) => {
    try {
        const sf = window._stage?._floorTopY;
        if (typeof sf === "number" &&
            (window._demoIsolation === "exclusive" || window._demoIsolation === "clean")) {
            return sf;
        }
        return world._heightAt ? (world._heightAt(x | 0, z | 0) | 0) : 0;
    } catch { return 0; }
};
function _updateRigSwimmers(dt) {
    if (!_rigSwimmers.length || !router) return;
    const d = Math.min(dt, 0.05);
    for (const s of _rigSwimmers) {
        // Swimmers: if a steep rise is ahead, veer to avoid plowing into a hill.
        if (s.mode !== "walk") {
            const ax = s.x + Math.cos(s.heading) * 5, az = s.z + Math.sin(s.heading) * 5;
            if (_terrainTopAt(ax, az) > _terrainTopAt(s.x, s.z) + 4) s.turn += s.turnSign * 2.0 * d;
        }
        s.turn += (Math.random() - 0.5) * s.turnJitter * d;
        if (s.turn >  s.maxTurn) s.turn =  s.maxTurn;
        if (s.turn < -s.maxTurn) s.turn = -s.maxTurn;
        s.heading += s.turn * d;
        s.x += Math.cos(s.heading) * s.speed * d;
        s.z += Math.sin(s.heading) * s.speed * d;
        const b = s.bounds;
        if (s.x < b.minX) { s.x = b.minX; s.heading = Math.PI - s.heading; s.turn = 0; }
        else if (s.x > b.maxX) { s.x = b.maxX; s.heading = Math.PI - s.heading; s.turn = 0; }
        if (s.z < b.minZ) { s.z = b.minZ; s.heading = -s.heading; s.turn = 0; }
        else if (s.z > b.maxZ) { s.z = b.maxZ; s.heading = -s.heading; s.turn = 0; }
        const th = _terrainTopAt(s.x, s.z);
        let y;
        if (s.mode === "walk") {
            // Walkers ride the terrain surface (feet planted).
            y = th + s.groundOffset;
        } else {
            // v450 — hover relative to the GROUND, not the camera. Previously
            // baseY was camera.y-4, so swimming away from a high vantage left
            // the creatures floating in the sky. Now they track the terrain
            // beneath them and bob just above it wherever they wander.
            s.bobT += d;
            y = th + s.clearance + Math.sin(s.bobT * s.bobFreq + s.bobPhase) * s.bobAmp;
        }
        const yaw = Math.atan2(Math.cos(s.heading), Math.sin(s.heading)) + s.yawOffset + _rigYawOffset;
        try { router.exec({ type: "entity:move", id: s.id, x: s.x, y, z: s.z, yaw }); } catch {}
    }
}
window._rigSwimmers = _rigSwimmers;

// v435 — AUTO SPINE RIG + PROCEDURAL SWIM. rig.fish()/rig.eel() generate a
// body, fit a bone chain down its long axis, auto-skin it, and play a
// baked traveling-wave "swim" clip. rig.asset(name) does the same to any
// already-loaded mesh. "swim" is the default (first) clip so it animates
