// v1373 — feed the asset-roles "kaiju" library to KaijuManager so DOWNLOADED models
// can serve as kaiju bodies. Preloads a few (themed by folder -> kind) then registers;
// _tryAttachMesh uses them when there's no kaiju_<kind> asset, else the cube renderer.
(async () => {
    try {
        const j = await fetch("/assets/roles").then(r => r.json());
        if (!j || !j.ok || !j.models || !Array.isArray(j.models.kaiju)) return;
        const FOLDER_KINDS = { Demons: ["hell"], Mechs: ["tech"], Skulls: ["hell", "cave", "underground"], Creatures: ["sky", "space", "water", "cave", "underground"], Characters: ["sky"], Helmets: ["tech"] };
        const byKind = {}, any = [];
        for (const m of j.models.kaiju.slice(0, 24)) {
            const name = String(m.name).replace(/\.(glb|gltf|vrm|fbx|obj)$/i, "");
            try { await assetLoader.loadAsset(name); } catch (e) { continue; }
            if (!assetLoader.cache?.get(name)) continue;
            any.push(name);
            for (const kind of (FOLDER_KINDS[m.folder] || [])) (byKind[kind] = byKind[kind] || []).push(name);
        }
        if (any.length && kaijuManager.setLibraryModels) { kaijuManager.setLibraryModels(byKind, any); console.log(`[main] kaiju library bodies: ${any.length} model(s) across kinds [${Object.keys(byKind).join(", ")}]`); }
    } catch (e) {}
})();

