// Discoverability pass — one-tap triggers for the five "set piece" systems
// that previously only had console handles (or none). Each reuses the proven
// summon / fire / crown / launch paths so a button can never drift from the
// actual sim. Surfaced as World-tab buttons further down. All handles below
// (window.summon, window.kaiju.*) are resolved lazily at click-time, so it's
// fine that some are defined later in the file.
window.kaijuShowcase = {
    // Tech alien invasion — a cluster of tech-race kaiju (metallic, ion-lance;
    // they shed "metal tree" MEMORY pillars as they roam).
    techInvasion: (n = 4) => {
        const out = [];
        for (let i = 0; i < n; i++) { try { const k = window.summon("tech"); if (k) out.push(k.id); } catch {} }
        try { window.kaijuSim?.start?.(); } catch {}
        try { window.kpop?.info?.("Tech invasion", out.length + " tech kaiju landed — watch for metal trees"); } catch {}
        console.log("[showcase] tech invasion →", out);
        return out;
    },
    // Crown a king — promote a live kaiju (or a freshly summoned one) to a
    // cross-kind king: bigger, faster minion cadence, a buff aura for nearby
    // kaiju of ANY kind, and king-tier attack rotations.
    crownKing: () => {
        let k = kaijuManager.kaiju.values().next().value;
        if (!k) { try { k = window.summon("hell"); } catch {} }
        if (!k) { console.warn("[showcase] no kaiju to crown"); return null; }
        try { window.kaiju.crown(k.id); } catch {}
        try { window.kpop?.info?.("A king rises", k.name + " now rules across kinds"); } catch {}
        return k.id;
    },
    // Rivalry duel — two rival-faction kaiju side by side (sky vs hell are
    // classic rivals). KaijuRivalry makes them open fire on each other; we
    // also nudge a first exchange so the duel reads immediately.
    duel: (a = "sky", b = "hell") => {
        let ka = null, kb = null;
        try { ka = window.summon(a); } catch {}
        try { kb = window.summon(b); } catch {}
        try { window.kaijuSim?.start?.(); } catch {}
        if (ka && kb) {
            const atkA = (typeof KIND_TO_ATTACK !== "undefined" && KIND_TO_ATTACK[a]) || "lightning";
            const atkB = (typeof KIND_TO_ATTACK !== "undefined" && KIND_TO_ATTACK[b]) || "fireball";
            setTimeout(() => { try { window.kaiju.fire(ka.id, atkA, kb.position); } catch {} }, 500);
            setTimeout(() => { try { window.kaiju.fire(kb.id, atkB, ka.position); } catch {} }, 950);
        }
        try { window.kpop?.info?.("Kaiju duel", a + " vs " + b + " — rivals open fire"); } catch {}
        return { a: ka?.id ?? null, b: kb?.id ?? null };
    },
    // Hellgate — a lava portal next to a civilization; it besieges them and a
    // hell queen rises to lead the minion wave.
    hellgate: () => { try { return window.hellgate?.openNear?.(); } catch { return null; } },
    // Tree-hurl cinematic — a kaiju uproots and hurls a tree while the camera
    // follows the projectile through its arc.
    throwCinematic: () => {
        let k = kaijuManager.kaiju.values().next().value;
        if (!k) { try { k = window.summon("sky"); } catch {} }
        if (!k) { console.warn("[showcase] no kaiju for throw"); return null; }
        const yaw = camera?.yaw || 0, fx = -Math.sin(yaw), fz = -Math.cos(yaw);
        const to = { x: (camera?.position?.x ?? 0) + fx * 40, y: (camera?.position?.y ?? 20), z: (camera?.position?.z ?? 0) + fz * 40 };
        const from = { x: k.position.x, y: k.position.y + 6, z: k.position.z };
        try {
            try { if (kaijuManager.throwCinematic) kaijuManager.throwCinematic.enabled = true; } catch {}
            const projectile = projectileManager.launch({ from, to, kind: "tree_pine", scale: 1.4, ownerKaijuId: k.id, trail: "ember", trailColor: [0.9, 0.7, 0.35] });
            try { kaijuManager.throwCinematic?.onThrow?.(projectile); } catch {}
            try { window.kpop?.info?.("Tree hurl", k.name + " uproots and hurls a tree"); } catch {}
            return true;
        } catch (e) { console.warn("[showcase] throw failed", e?.message); return false; }
    },
};
console.log("[showcase] window.kaijuShowcase.{techInvasion,crownKing,duel,hellgate,throwCinematic}() — also under \u2699 World");



