                    img.style.cssText = "max-width:97%;max-height:97%;object-fit:contain;border:1px solid #1b2c46;border-radius:10px;box-shadow:0 18px 60px rgba(0,0,0,.6);";
                    front.appendChild(img);

                    const back = document.createElement("div");
                    back.style.cssText = "position:absolute;inset:0;backface-visibility:hidden;-webkit-backface-visibility:hidden;transform:rotateY(180deg);display:flex;align-items:center;justify-content:center;background:transparent;border-radius:10px;";
                    const cap = document.createElement("div");
                    cap.id = "archBackCap";
                    cap.style.cssText = "position:absolute;top:10px;left:50%;transform:translateX(-50%);font:12px ui-monospace,monospace;color:#8fb4e0;background:rgba(3,6,12,.55);padding:4px 12px;border-radius:20px;pointer-events:none;";
                    cap.textContent = "live engine render \u2014 the diagram\u2019s flip side";
                    const gimg = document.createElement("img");
                    gimg.id = "archGeminiImg";
                    gimg.style.cssText = "display:none;max-width:70%;max-height:80%;object-fit:contain;border:1px solid #2a3f63;border-radius:12px;box-shadow:0 18px 60px rgba(0,0,0,.7);background:rgba(3,6,12,.4);";
                    back.append(cap, gimg);

                    card.append(front, back);
                    o.appendChild(card);

                    // flip button (captures clicks; rest of overlay passes through)
                    const flipBtn = document.createElement("button");
                    flipBtn.textContent = "\u27F2 rotate";
