                    gemBtn.style.cssText = "position:fixed;right:120px;bottom:18px;z-index:8001;pointer-events:auto;padding:8px 16px;background:rgba(30,20,46,.92);color:#e6cfff;border:1px solid #5a3f7a;border-radius:8px;cursor:pointer;font:12px ui-monospace,monospace;box-shadow:0 6px 20px rgba(0,0,0,.5);";
                    o._flipped = false;
                    flipBtn.addEventListener("click", () => { o._flipped = !o._flipped; card.style.transform = o._flipped ? "rotateY(180deg)" : "rotateY(0deg)"; });
                    gemBtn.addEventListener("click", async () => {
                        if (!o._flipped) { o._flipped = true; card.style.transform = "rotateY(180deg)"; }
                        cap.textContent = "grabbing a voxel object from Gemini\u2026"; gemBtn.disabled = true;
                        try {
                            const r = await fetch("/ai/image", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ prompt: "a single charming voxel-art object, isometric, crisp cubes, vivid palette, centered on a plain dark background, game asset render" }) }).then(x => x.json());
                            if (r && r.ok && r.image) { gimg.src = "data:" + (r.mime || "image/png") + ";base64," + r.image; gimg.style.display = "block"; cap.textContent = r.caption ? ("Gemini voxel \u2014 " + r.caption.slice(0, 60)) : "Gemini-grabbed voxel object"; }
                            else { cap.textContent = "\u2717 " + ((r && r.error) || "image grab failed (set a Gemini key)"); }
                        } catch (e) { cap.textContent = "\u2717 " + e.message; }
                        gemBtn.disabled = false;
                    });
                    o.appendChild(flipBtn); o.appendChild(gemBtn);
