    list: () => {
        const out = centipedeManager.list();
        console.table(out);
        return out;
    },
    // Hit a specific segment of a centipede to trigger the split.
    // segIdx: 0-based index into the body segments (0 = first segment
    // behind the head). Pass -1 to kill the head (whole chain dies).
    hit: (id, segIdx) => centipedeManager.hit(id, segIdx),
    // Convenience: hit middle of a chain
    bisect: (id) => {
        const c = centipedeManager.centipedes.get(id);
        if (!c) { console.warn("[centipede.bisect] not found:", id); return false; }
        const mid = Math.floor(c.segments.length / 2);
        return centipedeManager.hit(id, mid);
    },
    clear: () => centipedeManager.clear(),
    // v759 — attack policy delegation. Lets demos enable kaiju-style
    // ranged attacks on centipedes that route through ProjectileManager.
