// v513 — AI MODEL REGISTRY. Lists detected models/services + per-model enable
// flags (default ON, persisted). The acquisition pipeline checks isEnabled(key)
// before running a step, so unchecking e.g. "trellis" makes the pipeline skip
// it without even trying — handy for slow models you'd rather not run.
//
// v632 — added per-generation source preference (auto / trellis2 / kaggle) so
// you can pick local-ComfyUI vs cloud-Kaggle for the image→3D step. Persisted
// to localStorage; downstream pipeline rungs that honor it will read it via
// window.aiModels.preferredSource. detect() now actually probes ComfyUI's
// /object_info (through the bridge's /comfyui/ proxy to dodge CORS) to verify
// the Trellis2 / HiTem3D node CLASSES are loaded — not just "ComfyUI is up".
window.aiModels = {
    _key: "voxelengine.aiModelDisabled",
    _srcKey: "voxelengine.aiPreferredSource",
    _disabled: new Set(),
    _load() {
        try { this._disabled = new Set(JSON.parse(localStorage.getItem(this._key) || "[]")); } catch { this._disabled = new Set(); }
        try { this._preferred = localStorage.getItem(this._srcKey) || "auto"; } catch { this._preferred = "auto"; }
    },
    _save() { try { localStorage.setItem(this._key, JSON.stringify([...this._disabled])); } catch {} },
    isEnabled(key) { return !this._disabled.has(String(key).toLowerCase()); },      // default ON
    setEnabled(key, on) { key = String(key).toLowerCase(); if (on) this._disabled.delete(key); else this._disabled.add(key); this._save(); },
    // v632 — source preference. Values: "auto" (default) | "trellis2" | "kaggle".
    // The AssetAcquisitionService pipeline currently only has local Trellis +
    // HiTem3D rungs (no Kaggle/Hunyuan3D rung yet — that's a manual submit via
    // the Kaggle panel). Code that wants to honor the preference reads:
    //   window.aiModels.preferredSource    -> the string
    //   window.aiModels.setPreferredSource("trellis2")
    // The pipeline rung wire-through lands in a follow-up; this setting is the
    // foundation + a clear API.
    get preferredSource() { return this._preferred || "auto"; },
    setPreferredSource(v) {
        const allowed = new Set(["auto", "trellis2", "kaggle"]);
        const next = allowed.has(String(v)) ? String(v) : "auto";
        this._preferred = next;
        try { localStorage.setItem(this._srcKey, next); } catch {}
        console.log(`[aiModels] preferred 3D source = ${next}`);
        return next;
    },
    // Heavy pipeline steps the acquisition gate respects. `key` matches the step
    // name in AssetAcquisitionService so unchecking here skips that step.
    _steps: [
        { key: "trellis",  label: "Trellis 2 (local, ComfyUI fork)", group: "3D mesh (ComfyUI)", gated: true,
          hint: "visualbruno/ComfyUI-Trellis2. Install via Install Panel → 🌀 Trellis2 group (wheels → DINOv3 → FP8 weights → patches). Local image→3D, runs on your GPU." },
        { key: "hitem3d",  label: "HiTem3D — image→3D mesh",   group: "3D mesh (ComfyUI)", gated: true },
        // v641 — Kaggle (cloud) added as a 3D-mesh rung. When local trellis +
        // hitem3d are disabled OR fail (cooldown), the AAS submits a Hunyuan3D
        // job to Kaggle and resolves the mesh later when the bridge's
        // background poller catches the completion. ~15-45 min wall clock.
        { key: "kaggle",   label: "Kaggle Hunyuan3D — cloud GPU", group: "3D mesh (cloud)", gated: true,
          hint: "Submits a Hunyuan3D Kaggle job when local 3D is unavailable. Asset returns LATER (15-45 min) — the bridge auto-polls and swaps the mesh in when ready. Needs kaggle.json (legacy key) + classic CLI." },
    ],
    async detect() {
        const out = this._steps.map(s => ({ ...s, present: null }));
        let comfyOk = false;
        try { comfyOk = !!(await comfyui?.probe?.()); } catch {}
        // v632 — actually probe ComfyUI's node registry through the bridge proxy
        // (the browser can't hit ComfyUI directly: anti-DNS-rebind CORS block).
        // /object_info returns every loaded node class keyed by class name.
        let nodeKeys = [];
        if (comfyOk) {
            try {
                const r = await fetch("/comfyui/object_info");
                if (r.ok) { const j = await r.json(); nodeKeys = Object.keys(j || {}); }
            } catch {}
        }
        const lower = nodeKeys.map(k => k.toLowerCase());
        for (const e of out) {
            if (!e.group.startsWith("3D")) continue;
            if (e.key === "kaggle") continue;     // handled below — not a ComfyUI node
            if (!comfyOk) { e.present = false; continue; }
            if (nodeKeys.length === 0) { e.present = !!comfyOk; continue; }  // proxy fail → optimistic
            if (e.key === "trellis")      e.present = lower.some(k => k.includes("trellis"));
            else if (e.key === "hitem3d") e.present = lower.some(k => k.includes("hitem3d") || k.includes("hi_tem3d") || k.includes("hitem_3d"));
            else e.present = !!comfyOk;
        }
        // v641/v643 — Kaggle "present" check: the v641 authOk-only logic was
        // too strict — if the CLI smoke-test (`kaggle datasets list`) flakes
        // due to a version mismatch on PATH vs the embedded python, authOk
        // turns false even though jobs still submit fine via the legacy
        // KAGGLE_USERNAME/KAGGLE_KEY env vars. So: present = configured OR
        // authOk. If neither is true, we genuinely have no Kaggle.
        try {
            const kr = await fetch("/kaggle/status", { cache: "no-store" });
            if (kr.ok) {
                const ks = await kr.json();
                for (const e of out) if (e.key === "kaggle") {
                    e.present = !!(ks?.configured || ks?.authOk);
                    // Stash extra info so the panel can say "(authed)" vs "(creds set, CLI off)"
                    e.detail = ks?.authOk ? "authed" : (ks?.configured ? "creds set" : "no creds");
                }
            }
        } catch {}
        try {
            const ms = await ollama?.listModels?.();
            if (Array.isArray(ms)) for (const m of ms) out.push({ key: "llm:" + m.name, label: m.name, group: "LLM (Ollama)", present: true });
        } catch {}
        try {
            const ds = await diffuser?.listModels?.();
            if (Array.isArray(ds)) for (const m of ds) { const nm = (typeof m === "string" ? m : m.name) || "model"; out.push({ key: "diff:" + nm, label: nm, group: "Texture (diffuser)", present: true }); }
        } catch {}
        return out;
    },
};
window.aiModels._load();
console.log("[aiModels] ready — SETTINGS → AI / Background → detected models, or window.aiModels.detect()");
console.log(`[aiModels] preferred 3D source = ${window.aiModels.preferredSource} (set with aiModels.setPreferredSource('auto'|'trellis2'|'kaggle'))`);

