// Round 166 — auto-start the diffuser at boot if it's installed and
// not already running. The user explicitly asked for "assume we want
// it on if we have it installed". Decision logic:
//   1. Ask the bridge GET /diffuser/config (returns installed model
//      list + running state).
//   2. If already running → no-op.
//   3. If models[] is empty → no-op (nothing to launch).
//   4. Otherwise pick the user's last-used model (voxelengine.diffuserModel)
//      if present in the installed list, else pick the first installed.
//   5. POST /diffuser/launch with that model. Bridge spawns the server.
//      The ollamaPanel will pick up readiness via its existing polling
//      next time the user opens it.
// Disabled via localStorage voxelengine.diffuserAutoStart === "0".
(async () => {
    try {
        const pref = localStorage.getItem("voxelengine.diffuserAutoStart");
        if (pref === "0") return;   // user opted out
        const r = await fetch("/diffuser/config");
        if (!r.ok) return;
        const j = await r.json();
        if (!j.ok || j.running) return;
        if (!Array.isArray(j.models) || j.models.length === 0) return;
        const lastUsed = localStorage.getItem("voxelengine.diffuserModel");
        const model = (lastUsed && j.models.includes(lastUsed))
            ? lastUsed
            : j.models[0];
        const launchRes = await fetch("/diffuser/launch", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ model }),
        });
        const jj = await launchRes.json();
        if (jj.ok) {
            console.log(`[main] diffuser auto-started: ${model} (pid ${jj.pid}). Disable via voxelengine.diffuserAutoStart=0.`);
        } else {
            console.warn(`[main] diffuser auto-start failed: ${jj.error || "unknown"}`);
        }
    } catch (e) {
        // Bridge unreachable — fine, the diffuser stays manual.
    }
})();

// Round 181 — one-time auto-start: if ComfyUI is installed (a recognized
// portable layout in C:\VoxelBAK or similar) but not currently running,
// spawn it transparently at engine boot. Same pattern as the diffuser
// auto-start above. Steps:
//   1. GET /comfyui/state → { running, installed, installPath }
//   2. If running → no-op.
//   3. If not installed → no-op (user is fine without it; the Trellis
//      step in the bench will show a clear "install Trellis2" error).
//   4. POST /comfyui/launch (uses the path the bridge already found).
// Disabled via localStorage voxelengine.comfyuiAutoStart === "0".
// Override the install path via voxelengine.comfyuiInstallPath.
(async () => {
    try {
        const pref = localStorage.getItem("voxelengine.comfyuiAutoStart");
        if (pref === "0") return;   // user opted out
        const r = await fetch("/comfyui/state");
        if (!r.ok) return;
        const j = await r.json();
        if (j.running) return;
        if (!j.installed) return;   // nothing to launch; quietly skip
        const override = localStorage.getItem("voxelengine.comfyuiInstallPath") || null;
        const launchRes = await fetch("/comfyui/launch", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(override ? { installPath: override } : {}),
        });
        const jj = await launchRes.json();
        if (jj.ok) {
            console.log(`[main] comfyui auto-started: ${jj.installPath} via ${jj.launcherKind === "gpu" ? "GPU" : "CPU"} launcher (pid ${jj.pid}). Disable via voxelengine.comfyuiAutoStart=0.`);
        } else {
            console.warn(`[main] comfyui auto-start failed: ${jj.error || "unknown"}`);
        }
    } catch (e) {
        // Bridge unreachable — fine, ComfyUI stays manual.
    }
})();

// Round 186 — cold-start parallel pre-prime. Fires tiny warmup requests
// at boot so the first OBJ/narrative/diffuser call from the bench
// doesn't pay 30-60s of model-load latency. Runs in parallel after a
// short delay (let auto-started services come up first). Default warms
// only Ollama models; Diffuser warmup is opt-in via localStorage since
// it uses GPU and contends with Ollama loads.
// Toggles:
//   voxelengine.coldStartPrime    = "0"  → disable entirely
//   voxelengine.coldStartOllama   = "0"  → skip Ollama only
//   voxelengine.coldStartDiffuser = "1"  → opt in to Diffuser
//   voxelengine.coldStartModels   = "modelA,modelB"  → override list
(async () => {
    try {
        if (localStorage.getItem("voxelengine.coldStartPrime") === "0") return;
        // 3s delay so the diffuser/comfyui auto-start spawns above have
        // a chance to begin (Ollama is usually already up; diffuser is
        // what most needs the head start). The primer itself doesn't
        // care if a service isn't ready — it just gets HTTP errors and
        // logs them. The delay just makes the log line cleaner when
        // services are still booting.
        await new Promise(r => setTimeout(r, 3000));
        const mod = await import("./ai/ColdStartPrimer.js");
        const result = await mod.primeAll();
        mod.logPrimeResults(result);
    } catch (e) {
        console.warn("[coldstart] primer failed to load:", e?.message || e);
    }
})();

// Round 189 — Live pipeline demo trigger. Mounts a small "🌊 Demo" button
// bottom-right (near the Cast button). Clicking it spawns the HUD overlay
// (semi-transparent, draggable, minimizable) and runs N=5 parallel asset
// generations through narrative → OBJ → texture → Trellis, INSTALLING
// each result into the live engine as it completes so kaiju/civs visibly
// morph from procedural to AI-generated geometry while you watch.
// Console alternative: window.livePipeline.start({ count: 5, skipTrellis: true })
(async () => {
    try {
        const { createLivePipelineHUD } = await import("./ui/livePipelineHUD.js");
        const { LivePipelineDemo }      = await import("./ai/LivePipelineDemo.js");
        const hud  = createLivePipelineHUD({ title: "🌊 LIVE PIPELINE" });
        document.body.appendChild(hud.element);
        const demo = new LivePipelineDemo({ hud });
        window.livePipeline = {
            start: (opts) => demo.start(opts || {}),
            stop:  ()     => demo.stop(),
            hud,
            demo,
        };

        // Trigger button — sits next to (above) the Cast button. Same
        // visual language so they read as a related cluster of overlays.
        if (localStorage.getItem("voxelengine.livePipelineButton") !== "0") {
            const btn = document.createElement("button");
            btn.id = "live_pipeline_trigger";
            btn.textContent = "🌊 Demo";
            btn.title = "Run parallel AI pipeline demo — generates 5 kaiju/civ assets and installs them in the live engine";
            btn.style.cssText =
                // Round 190 — moved from bottom-right (was sitting inside
                // the parallax preview's panel area at bottom:56/right:16,
                // conflicting with that preview's controls) to top-right.
                // Top-right is otherwise empty, no UI lives there.
                "position:fixed; top:14px; right:16px; z-index:8500; " +
                "padding:6px 12px; background:rgba(10,10,30,0.85); color:#6db9ff; " +
                "border:1px solid #355; border-radius:4px; cursor:pointer; " +
                "font-family:monospace; font-size:12px; user-select:none;";
            btn.addEventListener("click", async () => {
                if (demo.isRunning()) {
                    // Mid-run: clicking again toggles HUD expanded state
                    if (hud.expanded) hud.setExpanded(false);
                    else              hud.setExpanded(true);
                    return;
                }
                btn.disabled = true; btn.style.opacity = "0.5";
                btn.textContent = "🌊 Running…";
                try {
                    // Default: 5 jobs, Trellis included. User can override
                    // via window.livePipeline.start({ skipTrellis: true })
                    // from console for a faster shake-out run.
                    await demo.start({ count: 5 });
                } finally {
                    btn.disabled = false; btn.style.opacity = "1";
                    btn.textContent = "🌊 Demo";
                }
            });
            // v1574 — no longer a floating screen-corner button: hidden here and re-parented
            // into the Kaiju panel (after kaijuPanel is created) as an option there.
            btn.style.display = "none"; window._pipelineDemoBtn = btn;
            document.body.appendChild(btn);
        }

        // v642 — Always-on pipeline observer badge. The 🌊 Demo button is a
        // TRIGGER (starts a 5-job demo run); this badge is an OBSERVER that
        // shows live AAS activity at all times. Resolves the user's "is it
        // starting because I'm looking at it?" — now there's a passive
        // indicator. Click to toggle the full HUD in observer mode (without
        // kicking off a demo).
        if (localStorage.getItem("voxelengine.pipelineBadge") !== "0") {
            // v1579 - the top-center "pipeline idle" pill was retired; this OBSERVER now feeds the
            // STATUS panel's PIPELINE row (window._hud.setPipeline). The row's own click toggles the HUD.
            const SPIN = ["\u280b","\u2819","\u2839","\u2838","\u283c","\u2834","\u2826","\u2827","\u2807","\u280f"];
            let spinIdx = 0;
            function refresh() {
                const setP = (html, color) => { try { window._hud && window._hud.setPipeline && window._hud.setPipeline(html, color); } catch {} };
                let s = null; try { s = window.assetService?.status?.(); } catch {}
                if (!s) { setP("idle", "#8aa"); return; }
                const active = s.active || 0, queued = s.queued || 0, done = s.done || 0, fails = s.threeDFails || 0, kaggleP = s.kagglePending || 0;
                const inflight = (s.inflight || []).slice(0, 2).join(",");
                if (active > 0 || queued > 0) {
                    setP(`${SPIN[spinIdx = (spinIdx + 1) % SPIN.length]} <span style="color:#6db9ff">${active}</span><span style="color:#888">/${queued}q</span>`
                        + (inflight ? ` <span style="color:#9bc">${inflight}</span>` : "")
                        + (kaggleP ? ` <span style="color:#c9b">\u2601${kaggleP}</span>` : "")
                        + ` <span style="color:#888">\u00b7${done}\u2713</span>`, "#6db9ff");
                } else if (kaggleP > 0) {
                    setP(`\u2601 <span style="color:#c9b">${kaggleP} on Kaggle</span> <span style="color:#888">\u00b7${done}\u2713</span>`, "#c9b");
                } else {
                    setP(`<span style="color:${fails > 0 ? "#caa05a" : "#4a6"}">idle</span> <span style="color:#888">\u00b7${done}\u2713${fails > 0 ? ` \u00b7${fails}\u26a0` : ""}</span>`, fails > 0 ? "#caa05a" : "#4a6");
                }
            }
            setInterval(refresh, 1500);
            refresh();
        }
    } catch (e) {
        console.warn("[livepipeline] setup failed:", e?.message || e);
    }
})();

// v642 — LIVE AAS pipeline observer badge. Distinct from the 🌊 Demo button:
// the Demo button TRIGGERS 5 parallel generations (user's confusion: "is the
// pipeline running because I'm looking at it?"). This badge is purely
// OBSERVATIONAL — it polls window.assetService.status() every 1.5s and shows
// what's actually happening regardless of any button click. Click toggles
// the LivePipelineHUD show/hide for a deeper drill-in.
//
// States:
//   ✓ idle           — no active, no queued, no kaggle pending
//   🌀 N/M           — N active, M queued (spinning emoji = real work)
//   ☁ K pending      — K Kaggle jobs awaiting cloud completion
//   combined         — both 🌀 and ☁ when both apply
//
// Positioned at top:48px right:16px so it sits BELOW the 🌊 Demo button —
// reads as a cluster of pipeline-related overlays.
(() => {
    try {
        return;   // v1579 - removed: the top-right "idle" badge is gone; pipeline state now lives in the STATUS panel PIPELINE row
        const badge = document.createElement("button");
        badge.id = "aas_observer_badge";
        badge.title = "Live pipeline observer — shows what the AAS is actually doing.\nClick to open the pipeline HUD.\nlocalStorage.voxelengine.aasObserverBadge='0' to hide.";
        badge.style.cssText =
            "position:fixed; top:48px; right:16px; z-index:8500; " +
            "padding:5px 10px; background:rgba(8,10,22,0.85); color:#9fb6e8; " +
            "border:1px solid #2a3a55; border-radius:4px; cursor:pointer; " +
            "font-family:monospace; font-size:11px; user-select:none; " +
            "min-width:80px; text-align:center;";
        badge.textContent = "✓ idle";
        document.body.appendChild(badge);
        // Click → toggle the LivePipelineHUD visibility (observer mode).
        // The HUD is meant to show jobs from a PipelineManager, but even when
        // empty the strip provides a hook for users to see the structure.
        badge.addEventListener("click", () => {
            try {
                const hud = window.livePipeline?.hud;
                if (!hud) { console.log("[aas-observer] HUD not yet loaded"); return; }
                // Toggle visibility: if hidden, show; if shown, expand/collapse;
                // if expanded, hide.
                if (!hud.element || hud.element.style.opacity === "0" || hud.element.style.opacity === "") {
                    hud.show();
                } else if (!hud.expanded) {
                    hud.setExpanded(true);
                } else {
                    hud.hide();
                }
            } catch (e) { console.warn("[aas-observer] click failed:", e?.message); }
        });
        // Poll loop — every 1500ms read assetService.status() and re-render.
        const POLL_MS = 1500;
        const render = () => {
            try {
                const s = window.assetService?.status?.();
                if (!s) { badge.textContent = "(no svc)"; badge.style.color = "#666"; return; }
                const a = s.active || 0, q = s.queued || 0, k = s.kagglePending || 0;
                const parts = [];
                if (a > 0)  parts.push(`🌀 ${a}${q > 0 ? "/" + q : ""}`);
                else if (q > 0) parts.push(`⏳ ${q}`);
                if (k > 0)  parts.push(`☁ ${k}`);
                if (parts.length === 0) {
                    badge.textContent = "✓ idle";
                    badge.style.color = "#5e7a55";
                    badge.style.borderColor = "#2a3a55";
                } else {
                    badge.textContent = parts.join("  ");
                    badge.style.color = (a > 0) ? "#6db9ff" : "#9fb6e8";
                    badge.style.borderColor = (a > 0) ? "#3a5a8a" : "#2a3a55";
                }
            } catch (e) { /* assetService not ready yet — leave as-is */ }
        };
        setInterval(render, POLL_MS);
        setTimeout(render, 500);   // first paint quickly once the service exists
        console.log("[aas-observer] live pipeline badge mounted — polls every 1.5s. Click for HUD. localStorage.voxelengine.aasObserverBadge='0' to hide.");
    } catch (e) {
        console.warn("[aas-observer] setup failed:", e?.message || e);
    }
})();

// Round 182 — spectatorCast toggle button. Mounts a small "📡 Cast" button
// (v703: now in the left miniIconStack rail, was bottom-center pill).
// Clicking it starts/stops the canvas → JPEG → WS broadcast.
// Remote browsers connect to /spectator.html to see the stream; VBA/Excel
// poll GET /spectator/latest.jpg every ~200ms via an Image control.
// Skipped if voxelengine.spectatorCastButton === "0" (in case the user
// wants to drive it purely from the console: spectatorCast.start()).
// Round 184 — added auto-resume: if the prior session was casting when
// the page was closed, kick cast back on at boot. Mirror of the
// diffuser/comfyui auto-start pattern.
(async () => {
    try {
        if (localStorage.getItem("voxelengine.spectatorCastButton") === "0") return;
        const { mountMiniIcon } = await import("./ui/miniIconStack.js");
        let btn = null;
        const startCast = () => {
            const fps     = parseInt(localStorage.getItem("voxelengine.spectatorFps")     || "5",   10);
            const quality = parseFloat(localStorage.getItem("voxelengine.spectatorQuality") || "0.6");
            spectatorCast.start({ fps, quality });
            setTimeout(() => btn?.refreshActive && btn.refreshActive(), 0);
        };
        btn = mountMiniIcon({
            id: "spectator_cast_toggle",
            icon: "📡",
            label: "Cast",
            color: "green",
            title: "Toggle viewport casting — JPEG snapshots over WS.\nRemote viewers: /spectator.html\nExcel/VBA: GET /spectator/latest.jpg",
            onClick: () => {
                if (spectatorCast.isRunning()) spectatorCast.stop();
                else startCast();
            },
            getActive: () => spectatorCast.isRunning(),
        });
        // v703 — note: the miniIconStack helper handles button styling
        // via its getActive callback (spectatorCast.isRunning()), so no
        // manual refresh() call is needed here. Active state propagates
        // automatically on each click; setTimeout above keeps it in sync
        // for the auto-resume path.

        // Round 184 — auto-resume if the prior session was casting.
        // spectatorCast writes "1" to LS_AUTO_RESUME on start, "0" on
        // explicit stop. A bridge-disconnect-induced stop leaves it
        // at "1", so reconnect → reload picks up casting again.
        if (localStorage.getItem("voxelengine.spectatorAutoResume") === "1") {
            // Give the engine a beat to mount the canvas + the WS bridge
            // to come up. 800ms is comfortable; spectatorCast itself
            // also tolerates the bridge not being there yet (returns
            // false). If the start fails we'll just sit not-casting.
            setTimeout(() => {
                if (!spectatorCast.isRunning()) {
                    console.log("[main] spectator cast auto-resumed (prior session was active). Disable via voxelengine.spectatorAutoResume=0.");
                    startCast();
                }
            }, 800);
        }
    } catch (e) {
        // DOM not ready or other issue — non-critical
    }
})();

// Round 59 - one-time auto-pick: if the user hasn't manually chosen a
// model yet (no localStorage entry, so OllamaClient is using its
// DEFAULT_MODEL fallback), probe what's installed and switch to the
// best available match. The panel still lets the user override at any
// time. Fire-and-forget; if Ollama is down, we keep the default name
// and the narrative falls back to templates as usual.
(async () => {
    try {
        const userPicked = localStorage.getItem("voxelengine.ollamaModel");
        if (userPicked) return;     // respect the user's prior choice
        const best = await ollama.pickBestModel();
        if (best && best !== ollama.model) {
            ollama.setModel(best);
            console.log(`[main] auto-selected Ollama model: ${best}`);
        }
    } catch {}
})();

// Round 45 — wire Ollama into asset loader for auto-OBJ generation
// when an asset is missing. Loader fires fire-and-forget; default
// mesh shows immediately, real OBJ swaps in once Ollama responds.
assetLoader.ollama = ollama;

// Round 59 - mount the Ollama panel (right-edge minitab) so users can
// see installed models + switch without touching the console.
// Round 66 - also start the auto-re-probe loop so the engine recovers
// gracefully when the user starts Ollama or pulls a model mid-session.
import("./ui/ollamaPanel.js").then(m => {
    try { window._ollamaPanel = new m.OllamaPanel({ ollama, diffuser, embedded: true }); }
    catch (e) { console.warn("[main] OllamaPanel mount failed:", e.message); }
});
try { ollama.startAutoReprobe?.(30000); } catch {}

// Now that waterRenderer + tvWall + screenAgents are all built, give
// the CommandRouter the env it needs to dispatch the v2 sim:* / wave:*
// / tv:* command families. Pre-registered here so any command that
// arrives via WS the moment the relay connects is handled correctly.
router.register({
    waterRenderer, tvWall, tvOverlay, ollama, persistence, camera,
    ecs: ecsWorld,
    ecsTypes: { Position, Render, Tag },
    // Round 62 — exposed so entity:spawnMesh can eagerly create the
    // SkeletalAnimator at spawn time (instead of waiting for the first
    // draw frame), and entity:despawn can drop it cleanly.
    entityMeshRenderer,
});

// ----------------------------------------------------------------------
// EDITOR — mouse-driven voxel editing. Click to lock the camera, then
// left-click to remove voxels and right-click to place. Number keys 1–7
// switch material (palette overlay shows current selection).
// ----------------------------------------------------------------------
const editor = new EditorController(camera, world, router, highlight, {
    canvas, parent: document.body,
    debris: voxelDebris,
});

const screenAgents = new Map();

for (const s of tvWall.screens) {
    const agent = new TVScreenAgent({
        id: s.id,
        camera: s.camera,
        viewRadius: 35,
    });
    agent.narrative.useLLM(ollama);
    screenAgents.set(s.id, agent);
}

// CivilizationEventBus -> per-screen agents -> Director ingest
civEvents.subscribe((evt) => {
    // Per-screen narrative
    const screenStories = [];
    for (const agent of screenAgents.values()) {
        const story = agent.observe(evt);
        if (story) screenStories.push({ id: agent.id, story });
    }

    // Director eats per-screen output and composes the global script
    director.ingest(screenStories);
    director.compose();

    // Round 47 — surface significant events as toasts. Filter aggressively
    // so we don't spam the screen during demos.
    if (!toaster) return;
    if (evt?.type === "kaiju_spawn" && evt.kaiju) {
        toaster.warn(
            `Kaiju arrives`,
            `${evt.kaiju.name} (${evt.kaiju.kind}) — targeting ${evt.kaiju.targetCivId != null ? "civ #" + evt.kaiju.targetCivId : "the area"}`,
            3500,
        );
    } else if (evt?.type === "kaiju_king_promotion" && evt.kaiju) {
        toaster.error(
            `KING RISING`,
            `${evt.kaiju.name} has become a ${evt.kaiju.kind} king`,
            6000,
        );
        // Tama reacts with alarm
        if (tamagotchi) tamagotchi._handleMessage({ action: "alert" });
    } else if (evt?.type === "birth" && (evt.civ?.score ?? 0) > 0.7) {
        toaster.success(
            `Civilization rises`,
            `${evt.civ.name ?? "Unknown"} — ${evt.civ.style ?? ""}`,
            3000,
        );
    } else if (evt?.type === "collapse" && evt.civ) {
        toaster.warn(
            `Collapse`,
            `${evt.civ.name ?? "A civilization"} fades`,
            2500,
        );
    } else if (evt?.type === "kaiju_death" && evt.kaiju) {
        // Only toast if the player allied OR if the kaiju was a king
        const wasKing = evt.kaiju.becameKing;
        if (wasKing) {
            toaster.success(`King falls`, `${evt.kaiju.name} has been slain`, 4000);
            if (tamagotchi) tamagotchi._handleMessage({ action: "happy" });
        }
    }
});

// v508 — KAIJU DEATH GORE. On death the body bursts into blood + bone that
// flings outward, arcs under gravity, and fades over ~2s. KaijuManager despawns
// the mesh entity just BEFORE emitting kaiju_death, so the burst originates at
// the body's last position (reads as the body bursting apart). On by default;
// window.kaijuGore(false) to disable, or SETTINGS → Gameplay.
let _kaijuGoreOn = true;
window.kaijuGore = (on = true) => { _kaijuGoreOn = !!on; console.log("[kaiju gore]", _kaijuGoreOn ? "on" : "off"); return _kaijuGoreOn; };
const _kaijuDeathFx = (k) => {
    const g = window.gpuParticles; if (!g?.spawn || !k?.position) return;
    const { x, y, z } = k.position;
    const sz = Math.max(1, Math.min(10, (k.config?.scale ?? 2) * (k.absorbScale ?? 1)));
    const cy = y + sz * 0.5;                     // burst from the body's middle
    // blood — dark/bright red, flings out and rains down
    const N = Math.round(28 + sz * 5);
    for (let i = 0; i < N; i++) {
        const a = Math.random() * Math.PI * 2, s = (0.4 + Math.random()) * sz;
        g.spawn({ x, y: cy, z, vx: Math.cos(a) * s, vy: (Math.random() * 1.3 + 0.4) * sz, vz: Math.sin(a) * s,
            life: 1.4 + Math.random() * 1.1, size: 0.3 + Math.random() * 0.5,
            r: 0.55 + Math.random() * 0.28, g: 0.02 + Math.random() * 0.05, b: 0.02 + Math.random() * 0.04, shape: 0 });
    }
    // bone — off-white chunks, heavier, fly farther
    const Nb = Math.round(8 + sz * 2);
    for (let i = 0; i < Nb; i++) {
        const a = Math.random() * Math.PI * 2, s = (0.6 + Math.random() * 1.2) * sz;
        g.spawn({ x, y: cy, z, vx: Math.cos(a) * s, vy: (Math.random() * 1.7 + 0.7) * sz, vz: Math.sin(a) * s,
            life: 1.6 + Math.random() * 1.3, size: 0.5 + Math.random() * 0.5,
            r: 0.9, g: 0.88, b: 0.78, shape: 0 });
    }
    // a low spray that lingers and fades (the "settling" pool feel)
    for (let i = 0; i < 12; i++) {
        const a = Math.random() * Math.PI * 2, s = Math.random() * sz * 0.7;
        g.spawn({ x: x + Math.cos(a) * s, y: y + 0.4, z: z + Math.sin(a) * s, vx: Math.cos(a) * 0.4, vy: 0.2, vz: Math.sin(a) * 0.4,
            life: 2.2 + Math.random() * 1.3, size: 0.5 + Math.random() * sz * 0.2,
            r: 0.42 + Math.random() * 0.12, g: 0.02, b: 0.02, shape: 0 });
    }
};
civEvents.subscribe((evt) => {
    if (_kaijuGoreOn && evt?.type === "kaiju_death" && evt.kaiju) { try { _kaijuDeathFx(evt.kaiju); } catch {} }
});

// ----------------------------------------------------------------------
// SEED MEMORY for civilization scanner
// ----------------------------------------------------------------------
function seedInitialMemory() {
    const seeds = [
        { x: 12, y: 30, z: 8 },
        { x: -8, y: 30, z: 14 },
        { x: 5,  y: 30, z: -10 },
    ];
    for (const s of seeds) {
        for (let i = 0; i < 30; i++) {
            const dx = ((i & 1) ? 1 : 0) | (((i >> 1) & 1) ? -1 : 0);
            const dz = ((i >> 2) & 1) ? 1 : 0;
            memoryField.write(s.x + dx, s.y, s.z + dz, 1);
        }
    }

    // Build a visible obelisk at each cluster: 3x3 base + 4-voxel spire,
    // sitting on top of whatever the current terrain surface is at the
    // seed (x, z). Bright-cyan MEMORY voxels make them pop visually as
    // landmarks. The obelisks regenerate on every load (we clear the
    // chunk _modified flags afterward), so resetting the world or
    // shifting the terrain function never leaves stale cluster blocks.
    const VOXEL_MEMORY = 30;
    const touchedChunkKeys = new Set();
    for (const s of seeds) {
        // Walk down from sky height looking for the first solid cell.
        let topY = -1;
        for (let y = 80; y >= 0; y--) {
            if (!world.isAir(s.x, y, s.z)) { topY = y; break; }
        }
        if (topY < 0) {
            // v429 — the chunk at this seed isn't generated yet (memory
            // clusters can sit outside the streamed region at boot), so the
            // voxel probe finds only air. The OLD failsafe planted the
            // obelisk at y=20 — floating in the sky, at the same fixed seed
            // spot, on every single load. Use the procedural surface height
            // instead, which is valid even before the chunk is meshed.
            topY = world._heightAt ? Math.max(0, (world._heightAt(s.x, s.z) | 0) - 1) : 20;
        }

        // 3x3 base, one cell above the surface
        const baseY = topY + 1;
        for (let dx = -1; dx <= 1; dx++) {
            for (let dz = -1; dz <= 1; dz++) {
                world.setVoxel(s.x + dx, baseY, s.z + dz, VOXEL_MEMORY);
                touchedChunkKeys.add(
                    `${Math.floor((s.x + dx) / world.chunkSize)},${Math.floor((s.z + dz) / world.chunkSize)}`
                );
            }
        }
        // 4-tall spire above the base center
        for (let dy = 1; dy <= 4; dy++) {
            world.setVoxel(s.x, baseY + dy, s.z, VOXEL_MEMORY);
        }
    }

    // Clear _modified on the affected chunks so persistence treats the
    // obelisks as part of the procedural baseline, not user-modified
    // state that needs saving. Prevents duplicate writes on reload and
    // keeps World Reset clean.
    for (const key of touchedChunkKeys) {
        const c = world.chunks.get(key);
        if (c) c._modified = false;
    }

    console.log(`[main] seeded ${seeds.length} memory clusters with obelisks (${touchedChunkKeys.size} chunks touched)`);
}
// v444 — clean boot: the 3 memory-cluster obelisks are re-seeded in code on
// every load (they are not part of the save), which is why "reset" never
// removed them. They now only seed if explicitly opted in.
if ((() => { try { return localStorage.getItem("voxelengine.seedObelisks") === "1"; } catch { return false; } })()) {
    seedInitialMemory();
} else {
    console.log("[main] memory obelisks skipped (clean boot v444). localStorage.setItem('voxelengine.seedObelisks','1') + reload to bring them back.");
}

// ----------------------------------------------------------------------
// GLOBAL DEBUG API — unchanged from v103
// ----------------------------------------------------------------------
window.VOXEL = {
    set(x, y, z, v) {
        router.exec({ type: "voxel:set", x, y, z, v });
    },
    get(x, y, z) {
        return router.exec({ type: "voxel:get", x, y, z });
    },
    cube(x1, y1, z1, x2, y2, z2, v = 1) {
        for (let x = x1; x <= x2; x++)
            for (let y = y1; y <= y2; y++)
                for (let z = z1; z <= z2; z++)
                    router.exec({ type: "voxel:set", x, y, z, v });
    },
};

window.SIM = {
    memoryField, gpuMemory, signalBus, aiManager,
    civManager, civLoop, optimizer, narrative, director,
    ecsWorld,
};

// ----------------------------------------------------------------------
camera.position.y = 60;
camera.position.z = 80;

// ----------------------------------------------------------------------
// CAMERA PANEL + DEMO MENU
// ----------------------------------------------------------------------
// Both UI panels live as fixed-position divs on top of the canvas.
// CameraPanel manages TV-wall layout + per-screen camera snapping;
// DemoMenu reads /demos/list from the relay server and applies the
// chosen demo's spec (camera pose, optional voxel writes, optional
// entity spawns) via the command router so persistence + WSBridge
// fire normally.
const cameraPanel = new CameraPanel({
    parent: document.body,
    camera,
    tvWall,
});

// v445 — auto-camera kill switch. The engine's narrative/demo sequences
// (the "Birth:"/"Combat:" cinematics) move the camera on their own; some
// players want to keep manual control. autoCam.stop() halts any in-flight
// move and prevents future ones; autoCam.start() re-enables.
window._autoCamEnabled = true;
window.autoCam = {
    stop()  { window._autoCamEnabled = false; try { _cancelSequence(); } catch {} console.log("[autoCam] auto-camera OFF — sequences no longer move the camera"); return false; },
    start() { window._autoCamEnabled = true; console.log("[autoCam] auto-camera ON"); return true; },
    toggle(){ return window._autoCamEnabled ? this.stop() : this.start(); },
    status(){ console.log(`[autoCam] ${window._autoCamEnabled ? "ON" : "OFF"}`); return window._autoCamEnabled; },
};
console.log("[AUTO-CAM] 'autoCam.stop()' to stop the camera auto-moving to views · 'autoCam.start()' to allow it");

function applyDemo(spec) {
    if (!spec) return;
    // Cancel any in-flight sequence — the new demo takes over.
    _cancelSequence();

    // v445 — auto-camera kill switch. When disabled (autoCam.stop()),
    // narrative/demo sequences still apply their world changes but never
    // move the camera, so the view stays exactly where the player left it.
    const camOK = (window._autoCamEnabled !== false);

    // SEQUENCE — multi-step cinematic. Tweens camera through each step.
    if (camOK && Array.isArray(spec.sequence) && spec.sequence.length > 0) {
        console.log(`[demo] starting sequence "${spec.name ?? "?"}" (${spec.sequence.length} steps)`);
        _runSequenceStep(spec.sequence, 0, _captureCameraState());
    } else if (camOK && spec.camera) {
        _applyCameraSpec(spec.camera);
    }

    if (Array.isArray(spec.voxels)) {
        for (const v of spec.voxels) {
            router.exec({ type: "voxel:set",
                x: +v.x, y: +v.y, z: +v.z, v: +v.v });
        }
    }
    // High-level structures (box / column / ring / disk / line) — expanded
    // into voxel writes via structureBuilder, then dispatched through the
    // router same as raw voxels. Hard-capped at 2000 voxels per build to
    // prevent a runaway generation from dumping the world.
    if (Array.isArray(spec.structures)) {
        const expanded = expandStructures(spec.structures);
        for (const v of expanded) {
            router.exec({ type: "voxel:set",
                x: v.x, y: v.y, z: v.z, v: v.v });
        }
        console.log(`[demo] expanded ${spec.structures.length} structures into ${expanded.length} voxels`);
    }
    if (Array.isArray(spec.entities)) {
        for (const e of spec.entities) {
            router.exec({ type: "entity:spawnMesh",
                assetId: e.assetId, x: +e.x, y: +e.y, z: +e.z,
                scale: e.scale ?? 1, kind: e.kind ?? "prop" });
        }
    }
    // Round 57 - declarative centipede spawn. Accepts either a single
    // object { count, x, z } or an array of them for multi-spawn demos.
    if (spec.centipede) {
        const specs = Array.isArray(spec.centipede) ? spec.centipede : [spec.centipede];
        for (const c of specs) {
            if (window.centipede?.spawn) {
                window.centipede.spawn(
                    +(c.count ?? 8),
                    +(c.x ?? 0),
                    +(c.z ?? 0),
                );
            }
        }
    }
    console.log(`[demo] applied "${spec.name ?? "?"}"` +
        (spec.voxels ? ` voxels=${spec.voxels.length}` : "") +
        (spec.entities ? ` entities=${spec.entities.length}` : ""));
}

// ---- Sequence player (smooth camera tween between keyframes) -------
let _seqRAF = null;          // active requestAnimationFrame handle

function _captureCameraState() {
    return {
        x: camera.position.x, y: camera.position.y, z: camera.position.z,
        yaw: camera.yaw, pitch: camera.pitch,
    };
}

function _applyCameraSpec(c) {
    if (!c) return;
    // Round 379 — when an absolute (x,y,z) is provided, route through
    // findSafePosition so the keyframe can't land us inside a wall
    // column. The existing _clampCameraToGround below handles the
    // below-surface case; safety adds the inside-solid case.
    let safeX = c.x, safeY = c.y, safeZ = c.z;
    if (c.x != null && c.y != null && c.z != null && typeof window !== "undefined" && window._findSafePosition) {
        const safe = window._findSafePosition(+c.x, +c.y, +c.z, {
            warnOnAdjust: false,
            // Sequences often script low-altitude flyovers; keep
            // search radius modest so we don't snap far from intent.
            maxLift: 8, maxRadius: 3,
        });
        if (safe.success) {
            safeX = safe.x; safeY = safe.y; safeZ = safe.z;
        }
    }
    if (safeX != null) camera.position.x = +safeX;
    if (safeY != null) camera.position.y = +safeY;
    if (safeZ != null) camera.position.z = +safeZ;
    if (c.yaw   != null) camera.yaw   = +c.yaw;
    if (c.pitch != null) camera.pitch = +c.pitch;
    // Round 266 — surface clamp. Demo sequences are scripted with
    // fixed world coords that don't always anticipate the terrain
    // height at the target (x, z) — particularly after biome ops or
    // procedural terrain generation. Without this the camera can dive
    // into a hill mid-sequence. minBuffer here is gentle (2u) so an
    // intentionally low-overhead step (e.g. "skim across rooftops")
    // still looks how the author intended when the terrain is flat.
    if (typeof window !== "undefined" && window._clampCameraToGround) {
        // v443 — ease:false so scripted auto-camera moves SNAP to the
        // (smooth) floor instead of easing. The tween already supplies the
        // smooth motion; easing here lagged behind the fast move and made
        // the camera "walk" up the terrain in visible steps. Manual WASD
        // still routes through the eased path and stays smooth.
        window._clampCameraToGround(camera, { minBuffer: 2, maxLift: 24, ease: false });
    }
}

function _cancelSequence() {
    if (_seqRAF != null) {
        cancelAnimationFrame(_seqRAF);
        _seqRAF = null;
    }
}

function _runSequenceStep(steps, idx, fromState) {
    if (idx >= steps.length) { _seqRAF = null; return; }
    const step = steps[idx];
    const dur  = ((step.duration ?? step.wait ?? 3) * 1000);
    const c    = step.camera || {};
    const to   = {
        x: c.x ?? fromState.x,
        y: c.y ?? fromState.y,
        z: c.z ?? fromState.z,
        yaw: c.yaw ?? fromState.yaw,
        pitch: c.pitch ?? fromState.pitch,
    };
    // v383 — per-step safety bounds. Defaults loosened from the v379
    // (maxLift:4, maxRadius:2) to (maxLift:8, maxRadius:3) so a fast
    // scripted move that skims close to a wall doesn't get yanked
    // sideways on every interpolated frame. A step can opt OUT
    // entirely with `safety: false`, or override the bounds with
    // `safety: { maxLift, maxRadius }`. The wall-clearance walk only
    // engages when the interpolated position is genuinely solid;
    // looser bounds = give it room to find the right answer cleanly,
    // not "do less work".
    let safetyOpts = step.safety;
    if (safetyOpts !== false) {
        safetyOpts = Object.assign({ warnOnAdjust: false, maxLift: 8, maxRadius: 3 },
                                     (safetyOpts && typeof safetyOpts === "object") ? safetyOpts : {});
    }
    const start = performance.now();
    const tick = () => {
        const t = performance.now();
        const a = Math.min(1, (t - start) / dur);
        // ease-in-out cubic — feels filmic, not robotic
        const e = a < 0.5 ? 4 * a * a * a : 1 - Math.pow(-2 * a + 2, 3) / 2;
        camera.position.x = fromState.x + (to.x - fromState.x) * e;
        camera.position.y = fromState.y + (to.y - fromState.y) * e;
        camera.position.z = fromState.z + (to.z - fromState.z) * e;
        camera.yaw        = fromState.yaw   + (to.yaw   - fromState.yaw)   * e;
        camera.pitch      = fromState.pitch + (to.pitch - fromState.pitch) * e;
        if (safetyOpts && typeof window !== "undefined" && window._safeMoveCamera) {
            window._safeMoveCamera(camera,
                camera.position.x, camera.position.y, camera.position.z,
                safetyOpts);
        }
        if (a < 1) {
            _seqRAF = requestAnimationFrame(tick);
        } else {
            _seqRAF = null;
            _runSequenceStep(steps, idx + 1, to);
        }
    };
    _seqRAF = requestAnimationFrame(tick);
}

// ---- Demo generator + save -----------------------------------------
const demoGenerator = new DemoGenerator({ model: "llama3.2" });

// Save a procedural model spec to the models/ folder via the server's
// /models/save endpoint. Mirrors saveDemo but writes to a different
// directory tree.
async function saveModel(dir, filename, spec) {
    try {
        const res = await fetch("/models/save", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ dir, filename, content: spec }),
        });
        if (!res.ok) {
            const txt = await res.text();
            console.warn(`[model] save failed: HTTP ${res.status} — ${txt}`);
            return false;
        }
        return true;
    } catch (e) {
        console.warn(`[model] save threw: ${e.message}`);
        return false;
    }
}

// First-run population — once per browser, if Ollama is reachable,
// generate a starter set of procedural creature models. Each creature
// materializes in the world as voxels at a deterministic showcase
// position; the camera flies to it and a narrative caption announces
// its arrival. Voxels persist via WSBridge so subsequent reloads keep
// the gallery.
const FIRST_RUN_FLAG = "voxelengine.firstRunPopulated.v1";
const STARTER_CREATURES = [
    { name: "herald",   desc: "a tall slender messenger creature with raised antennae" },
    { name: "sentinel", desc: "a squat armored guardian with thick legs" },
    { name: "wanderer", desc: "a four-legged roaming beast with a long tail" },
    { name: "archive",  desc: "a sessile crystalline entity emitting memory" },
    { name: "echo",     desc: "a small flying wisp creature, mostly head" },
    { name: "totem",    desc: "a stacked ancestral pillar creature" },
    { name: "whisper",  desc: "a low ground-hugging serpentine form" },
];

// Showcase row: 7 slots in a line near the camera spawn area.
// Camera spawn is (0, 60, 80) looking down/forward, so this is in
// frame from launch. Spacing of 6u prevents creatures from touching.
const SHOWCASE_BASE = { y: 14, z: 30 };  // y close to surface, z in front
const SHOWCASE_SPACING_X = 7;
// v964 — robust ground for showcase slots. The old code fell back to a fixed
// SHOWCASE_BASE.y (=14) whenever world._heightAt was unavailable or disagreed
// with the painted surface — that fixed sky Y was the source of the floating
// white cubes at startup. Now: prefer the deterministic heightmap (valid even
// before chunks stream in), then refine to the actual top solid voxel if the
// column is generated (so creatures sit on painted biome mountains too), and
// return null when no ground can be found so the caller SKIPS placement. A
// creature is never dropped at a sky Y again.
function _showcaseGroundY(x, z) {
    let h = null;
    try { if (world._heightAt) { const v = world._heightAt(x, z) | 0; if (v > 0) h = v; } } catch {}
    try {
        if (world.voxelAt) {
            for (let y = 48; y >= 0; y--) {
                const v = world.voxelAt(x, y, z);
                if (v && v !== 0 && v !== 10 /* WATER */) { h = y; break; }
            }
        }
    } catch {}
    return (h != null && h > 0) ? h + 1 : null;
}

function showcaseSlot(i) {
    const x = (i - 3) * SHOWCASE_SPACING_X;    // -21, -14, -7, 0, 7, 14, 21
    const z = SHOWCASE_BASE.z;
    // v964 — sit on the real surface; if no ground is found, return null and
    // the caller skips this slot (never float at the old fixed y=14).
    const gy = _showcaseGroundY(x, z);
    if (gy == null) return null;
    return { x, y: gy, z };
}

// Place a creature spec at world coordinates by expanding its
// structures into voxels and dispatching voxel:set commands through
// the router. The router's WSBridge fan-out persists them, so reloads
// see the same gallery without re-generation.
function placeCreatureAt(spec, slot) {
    if (!spec || !Array.isArray(spec.structures)) return 0;
    const voxels = expandStructures(spec.structures);
    const ox = Math.floor(slot.x);
    const oy = Math.floor(slot.y);
    const oz = Math.floor(slot.z);
    let n = 0;
    for (const v of voxels) {
        if (v.v === 0) continue;   // skip air
        router.exec({
            type: "voxel:set",
            x: ox + v.x,
            y: oy + v.y,
            z: oz + v.z,
            v:  v.v,
        });
        n++;
    }
    return n;
}

// Clear a bounding box around a showcase slot — used before re-placing
// during repopulate so old creatures don't bleed into new ones. Box
// width 8, height 6 (creatures are <= 4u tall + 2u headroom).
function clearShowcaseSlot(slot) {
    const ox = Math.floor(slot.x);
    const oy = Math.floor(slot.y);
    const oz = Math.floor(slot.z);
    for (let dx = -4; dx <= 4; dx++) {
        for (let dy = 0; dy <= 5; dy++) {
            for (let dz = -4; dz <= 4; dz++) {
                router.exec({ type: "voxel:set", x: ox + dx, y: oy + dy, z: oz + dz, v: 0 });
            }
        }
    }
}

// Run the procedural-creature population. force=false honors the
// localStorage flag (first-run only); force=true bypasses it for
// manual re-runs from the Settings panel.
async function populateModels(force = false) {
    if (!force && localStorage.getItem(FIRST_RUN_FLAG)) {
        console.log("[populate] already populated, skipping (use force=true to re-run)");
        return { ok: false, reason: "already_populated" };
    }
    const reachable = await ollama.probe();
    if (!reachable) {
        console.log("[populate] Ollama not reachable");
        return { ok: false, reason: "ollama_unreachable" };
    }

    const modal = new FirstRunModal();
    modal.show();
    modal.setStatus(force
        ? "Re-populating models from Ollama..."
        : "Connected to Ollama. Generating creatures...");

    let okCount = 0;
    for (let i = 0; i < STARTER_CREATURES.length; i++) {
        if (modal.isClosed()) break;
        const { name, desc } = STARTER_CREATURES[i];
        modal.setStatus(`Generating ${name}... (${i + 1}/${STARTER_CREATURES.length})`);

        let spec = null;
        try {
            spec = await demoGenerator.generateCreature(name, desc);
        } catch (e) {
            console.warn(`[populate] ${name} threw:`, e.message);
        }

        if (spec && spec.structures) {
            const saved = await saveModel("scene", `${name}.json`, spec);
            const slot = showcaseSlot(i);
            if (!slot) { modal.addLine(`${name} (skipped — no ground at slot)`, false); continue; }
            // Re-runs clear the slot first to avoid creature pile-up.
            // First runs skip the clear since slots are already empty terrain.
            if (force) clearShowcaseSlot(slot);
            const placed = placeCreatureAt(spec, slot);

            modal.addLine(`${name} (${placed} voxels)`, saved && placed > 0);
            if (saved && placed > 0) {
                okCount++;
                civEvents.publish({
                    type: "model_placed",
                    intensity: 0.7,
                    x: slot.x, y: slot.y + 2, z: slot.z,
                    modelName: name,
                });

                // Round 16 — spawn / re-spawn life mote for this slot.
                // On force-run, despawn any existing mote at the slot first.
                if (force) {
                    const existingIdx = showcaseMotes.findIndex(m => m.modelName === name);
                    if (existingIdx >= 0) {
                        ecsWorld.removeEntity(showcaseMotes[existingIdx].entityId);
                        showcaseMotes.splice(existingIdx, 1);
                    }
                }
                spawnMoteFor(i, name);
            }
        } else {
            modal.addLine(name, false);
        }
        modal.setProgress((i + 1) / STARTER_CREATURES.length);
    }

    modal.setStatus(`Done. ${okCount}/${STARTER_CREATURES.length} creatures placed.`);
    localStorage.setItem(FIRST_RUN_FLAG, String(Date.now()));
    setTimeout(() => modal.hide(), 3000);
    return { ok: true, count: okCount };
}

// Count helpers for the Settings panel status display.
async function countAssetsLoaded() {
    try {
        const r = await fetch("/assets/list");
        const j = await r.json();
        return j.ok ? j.assets.length : 0;
    } catch { return 0; }
}
async function countModelsAvailable() {
    try {
        const r = await fetch("/models/list?dir=scene");
        const j = await r.json();
        return j.ok ? j.models.length : 0;
    } catch { return 0; }
}

// Run first-time population on load (the previous IIFE). Manual
// re-runs come from the Settings panel button via populateModels(true).
// v451 — the first-run creature showcase is now OPT-IN. It planted abstract
// voxel "creatures" + orbiting motes that read as stray white cubes floating
// over the terrain. Off by default; window.showcase.on() to enable (grounded).
const _showcaseEnabled = (() => { try { return localStorage.getItem("voxelengine.showcase") === "1"; } catch { return false; } })();
if (_showcaseEnabled) populateModels(false);

// ---- Round 16 — life motes ---------------------------------------
// Each placed creature gets a small ECS entity ("mote") floating
// above it that bobs and orbits slowly. The voxel sculpture stays
// static; the mote provides the "inhabited / alive" signal.
//
// Motes don't persist across reloads (ECS is in-memory), so on every
// load we fetch the list of existing models and re-spawn motes at the
// matching showcase slots.

const showcaseMotes = [];   // { entityId, slot, phase, modelName }

function spawnMoteFor(slotIndex, modelName) {
    const slot = showcaseSlot(slotIndex);
    if (!slot) return null;   // v964 — no ground → no floating mote
    const id = ecsWorld.createEntity();
    ecsWorld.addComponent(id, new Position(slot.x, slot.y + 4, slot.z));
    ecsWorld.addComponent(id, new Tag("mote"));
    showcaseMotes.push({
        entityId: id,
        slot,
        phase: slotIndex * 0.9,    // staggered start so motes don't sync
        modelName,
    });
    return id;
}

// On reload, re-spawn motes for any existing creatures on disk.
async function rehydrateMotes() {
    let modelNames = [];
    try {
        const r = await fetch("/models/list?dir=scene");
        const j = await r.json();
        if (j.ok) modelNames = j.models;
    } catch { return; }
    if (modelNames.length === 0) return;

    // Match disk model names to the STARTER_CREATURES indexed slots
    // so each mote lands at its creature's slot.
    for (let i = 0; i < STARTER_CREATURES.length; i++) {
        if (modelNames.includes(STARTER_CREATURES[i].name)) {
            spawnMoteFor(i, STARTER_CREATURES[i].name);
        }
    }
    console.log(`[motes] rehydrated ${showcaseMotes.length} motes`);
}

// Animation: per-frame update of mote positions. Slow orbit (radius
// 2.5u, period ~12s) plus bob (period ~3s, amplitude 0.5u). Both
// motion phases offset by mote phase so the gallery has staggered
// motion rather than synchronized.
function updateMotes(tMs) {
    for (const m of showcaseMotes) {
        const pos = ecsWorld.getComponent(m.entityId, Position);
        if (!pos) continue;
        const angle = (tMs * 0.0005) + m.phase;
        const orbit = 2.5;
        const bob = Math.sin(tMs * 0.002 + m.phase) * 0.5;
        pos.x = m.slot.x + Math.cos(angle) * orbit;
        pos.y = m.slot.y + 4 + bob;
        pos.z = m.slot.z + Math.sin(angle) * orbit;
    }
}

// Schedule rehydrate after first-run populate finishes (or skips).
// In normal flow:
//   - First run: populateModels(false) generates + spawns motes inline
//     via the populate path; rehydrate finds them and spawns more (dups)
//   - Subsequent runs: populate skips, rehydrate spawns the motes
// Solution: rehydrate only when populate skips. Wire it via the
// flag check.
if (_showcaseEnabled && localStorage.getItem(FIRST_RUN_FLAG)) {
    rehydrateMotes();
}

// v451 — showcase controls. Clear the orbiting motes on demand and
// toggle the first-run creature showcase (default off).
window.clearShowcase = () => {
    let n = 0;
    for (const m of showcaseMotes) { try { ecsWorld.removeEntity(m.entityId); n++; } catch {} }
    showcaseMotes.length = 0;
    console.log(`[showcase] cleared ${n} motes. (Any persisted creature voxels clear on hardResetWorld().)`);
    return n;
};
window.showcase = {
    on:  () => { try { localStorage.setItem("voxelengine.showcase", "1"); } catch {} console.log("[showcase] enabled — reload to populate the first-run creatures (now grounded on the terrain)."); },
    off: () => { try { localStorage.setItem("voxelengine.showcase", "0"); } catch {} window.clearShowcase(); console.log("[showcase] disabled + motes cleared."); },
    clear: () => window.clearShowcase(),
    status: () => ({ enabled: _showcaseEnabled, motes: showcaseMotes.length }),
};
console.log(`[showcase] first-run creature showcase is ${_showcaseEnabled ? "ON" : "OFF (default)"} — those were the floating white cubes. window.showcase.on()/off()/clear().`);

// v453 — CLICK-TO-INSPECT ("what is this?"). Toggle with window.inspect()
// or click the 🔍 button, then aim the crosshair at anything and click: it
// identifies the voxel under your aim (id + name + whether it's floating
// with air beneath it) and the nearest entity to your line of sight
// (kaiju / civ / creature kind + name). Built to diagnose mystery objects.
(() => {
    const VOXEL_NAMES = { 0: "AIR", 1: "STONE", 2: "DIRT", 3: "GRASS", 4: "SAND", 5: "SNOW", 6: "ASH", 10: "WATER", 12: "LAVA", 20: "SCREEN", 30: "MEMORY/OBELISK" };
    let on = false, raycastVoxel = null, badge = null;
    async function ensureRaycast() {
        if (!raycastVoxel) { try { const m = await import("./editor/voxelSelectionRaycast.js"); raycastVoxel = m.raycastVoxel; } catch (e) { console.warn("[inspect] raycast unavailable:", e.message); } }
        return raycastVoxel;
    }
    function show(text) {
        if (!badge) {
            badge = document.createElement("div");
            Object.assign(badge.style, {
                position: "fixed", left: "50%", bottom: "96px", transform: "translateX(-50%)",
                zIndex: "10050", padding: "8px 16px", maxWidth: "80vw",
                background: "rgba(10,16,30,0.92)", border: "1px solid rgba(120,200,255,0.6)",
                borderRadius: "8px", color: "#dff", font: "600 13px monospace",
                pointerEvents: "none", textAlign: "center", boxShadow: "0 3px 14px rgba(0,0,0,0.5)",
            });
            document.body.appendChild(badge);
        }
        badge.textContent = text; badge.style.display = "block";
        clearTimeout(badge._t); badge._t = setTimeout(() => { if (badge) badge.style.display = "none"; }, 7000);
    }
    function camForward() { const cp = Math.cos(camera.pitch); return { x: Math.sin(camera.yaw) * cp, y: Math.sin(camera.pitch), z: -Math.cos(camera.yaw) * cp }; }
    function nearestEntity(o, dir) {
        const cands = [];
        try { const it = kaijuManager?.kaiju?.values ? kaijuManager.kaiju.values() : []; for (const k of it) { const p = k.position; if (p) cands.push({ x: p.x, y: p.y, z: p.z, label: `kaiju ${k.kind || ""} ${k.name || ""}`.trim() }); } } catch {}
        try { for (const c of (civManager?.getAll?.() || [])) { const p = c.center; if (p) cands.push({ x: p.x, y: p.y ?? 0, z: p.z, label: `civ ${c.name || c.id || ""}`.trim() }); } } catch {}
        let best = null, bestD = 5;
        for (const c of cands) {
            const t = (c.x - o.x) * dir.x + (c.y - o.y) * dir.y + (c.z - o.z) * dir.z;
            if (t < 0) continue;
            const px = o.x + dir.x * t, py = o.y + dir.y * t, pz = o.z + dir.z * t;
            const d = Math.hypot(c.x - px, c.y - py, c.z - pz);
            if (d < bestD) { bestD = d; best = c; }
        }
        return best;
    }
    async function doInspect() {
        const rc = await ensureRaycast();
        const dir = camForward();
        let msg = "🔍 ";
        let hit = null;
        try { if (rc) hit = rc(world, camera.position, dir, 256); } catch {}
        if (hit) {
            let id = 0, below = 0;
            try { id = world.getVoxel(hit.x, hit.y, hit.z); } catch {}
            try { below = world.getVoxel(hit.x, hit.y - 1, hit.z); } catch {}
            msg += `VOXEL: ${VOXEL_NAMES[id] || ("id " + id)} @ ${hit.x},${hit.y},${hit.z}${below === 0 ? " — FLOATING (air below)" : ""}`;
        } else {
            msg += "no voxel under crosshair";
        }
        const ent = nearestEntity(camera.position, dir);
        if (ent) msg += `  ·  near ENTITY: ${ent.label}`;
        show(msg);
        console.log("[inspect]", msg, hit || "");
        return { hit, msg };
    }
    function onClick(e) { if (!on) return; e.preventDefault(); e.stopPropagation(); doInspect(); }
    window.inspect = (v = true) => {
        on = !!v;
        if (on) { window.addEventListener("click", onClick, true); document.body.style.cursor = "crosshair"; show("🔍 INSPECT ON — aim the crosshair and click. inspect(false) to stop."); }
        else { window.removeEventListener("click", onClick, true); document.body.style.cursor = ""; if (badge) badge.style.display = "none"; }
        console.log(`[inspect] ${on ? "ON — click to identify any voxel/object" : "off"}`);
        return on;
    };
    window.whatIsThis = () => doInspect();   // one-shot at the crosshair, no toggle

    // Small 🔍 button (bottom-left, above the bottom-row minitabs).
    // v703 — uses the shared miniIconStack helper. Position is auto-
    // assigned by the stack (first tool sits at bottom:60). The inspect
    // active state is tracked on window._inspectOn so the helper can
    // color the button cyan-active when on.
    (async () => {
        try {
            const { mountMiniIcon } = await import("./ui/miniIconStack.js");
            window._inspectOn = false;
            mountMiniIcon({
                id: "ve-inspect-btn",
                icon: "🔍",
                label: "Picker/Examiner",
                color: "cyan",
                title: "Inspect: identify the voxel/object under your crosshair",
                onClick: () => { window._inspectOn = window.inspect(!on); },
                getActive: () => window._inspectOn === true,
            });
        } catch (e) { console.warn("[inspect] miniIconStack mount failed:", e?.message); }
    })();
    console.log("[inspect] click the 🔍 button (bottom-left) or run inspect(), then click to identify voxels/objects · whatIsThis() for a one-shot");

    // v1974 — move AUDIO + SETTINGS off their minitabs into the bottom-left icon rail. SETTINGS pins to the
    // very bottom (order 0), AUDIO just above it (order 1); the existing rail icons float above (no order).
    // We also hide the old AUDIO minitab (hud._volumeMinitab) and the SETTINGS minitab so they're not doubled.
    (async () => {
        try {
            const { mountMiniIcon } = await import("./ui/miniIconStack.js");
            // AUDIO — toggles the hud's volume panel (MASTER/SFX/AMBIENT)
            mountMiniIcon({
                id: "ve-audio-btn", icon: "\uD83D\uDD0A", label: "Audio", color: "blue", order: 1,
                title: "Audio: master / SFX / ambient volumes",
                onClick: () => {
                    try {
                        const h = window._hud;
                        const p = h && h._volumePanel, m = h && h._volumeMinitab;
                        if (!p) return;
                        const showing = p.style.display !== "none" && p.style.display !== "";
                        p.style.display = showing ? "none" : "block";
                        if (m) m.style.display = "none";   // keep the old minitab hidden; the icon owns it now
                    } catch (e) {}
                },
                getActive: () => { try { const p = window._hud && window._hud._volumePanel; return !!p && p.style.display !== "none" && p.style.display !== ""; } catch { return false; } },
            });
            // SETTINGS — opens the settings hub; pinned to the bottom of the rail
            mountMiniIcon({
                id: "ve-settings-btn", icon: "\u2699\uFE0F", label: "Settings", color: "cyan", order: 0,
                title: "Settings",
                onClick: () => { try { (window.openSettings || window.openSettingsHub)?.(); } catch (e) {} },
            });
            // hide the now-migrated minitabs (guarded; they may mount a beat later)
            const hideMigrated = () => {
                try { const m = window._hud && window._hud._volumeMinitab; if (m) m.style.display = "none"; } catch (e) {}
                try { const st = document.getElementById("swek-settings-minitab") || [...document.querySelectorAll(".lcars-minitab")].find(t => /settings/i.test(t.textContent || "")); if (st) st.style.display = "none"; } catch (e) {}
            };
            hideMigrated(); setTimeout(hideMigrated, 600); setTimeout(hideMigrated, 1600);
        } catch (e) { console.warn("[audio/settings icons] mount failed:", e?.message); }
    })();

    // v1972 — clean boot: tuck away the auto-opening panels (Cameras / Status / Demos / Difficulty) so boot
    // shows just the world; a "▤ Panels" button (bottom-left) toggles them back. Opt out with
    // localStorage voxelengine.cleanBoot="0". Runs after the panels have mounted.
    (async () => {
        try {
            const { runBootClean } = await import("./ui/bootClean.js");
            window._bootClean = runBootClean({
                cameraPanel: (typeof cameraPanel !== "undefined" ? cameraPanel : null),
                hud: (window._hud || (typeof hud !== "undefined" ? hud : null)),
                demoMenu: null,   // resolved lazily below via window._demoMenu (defined a bit later in boot)
                _lazyDemoMenu: () => window._demoMenu || null,
            });
        } catch (e) { console.warn("[bootClean] skipped:", e?.message); }
    })();

    // v1964 — manual 3D navigation pad on the left rail (🧭). Click to show/hide a button pad that moves,
    // zooms, and rotates the camera, plus keyboard nav (WASD-family) whose keys are shown on each button.
    (async () => {
        try {
            const { mountNavPad } = await import("./ui/navPad.js");
            const np = await mountNavPad(camera);
            window._navPad = np;
            // keyboard nav: mirrors the pad button titles. Ignored while typing or when a demo owns WASD (fp/kaiju drive).
            const KEYMAP = { KeyA:"left", ArrowLeft:"left", KeyD:"right", ArrowRight:"right", KeyR:"up", PageUp:"up",
                KeyF:"down", PageDown:"down", Equal:"in", NumpadAdd:"in", Minus:"out", NumpadSubtract:"out",
                KeyW:"rotUp", KeyS:"rotDown", KeyQ:"rotLeft", KeyE:"rotRight", Home:"recenter", Backspace:"orient" };
            window.addEventListener("keydown", (e) => {
                const tgt = e.target;
                if (tgt && (tgt.tagName === "INPUT" || tgt.tagName === "TEXTAREA" || tgt.isContentEditable)) return;
                // don't fight first-person / kaiju-drive modes that own WASD
                try { if (camera.mode === "fp" || camera.mode === "kaiju_drive") return; } catch {}
                const a = KEYMAP[e.code]; if (a && np && np.nav) { np.nav(a); }
            });
        } catch (e) { console.warn("[navPad] mount failed:", e?.message); }
    })();
})();

async function saveDemo(filename, spec) {
    try {
        const res = await fetch("/demos/save", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ filename, content: spec }),
        });
        if (!res.ok) {
            const txt = await res.text();
            console.warn(`[demo] save failed: HTTP ${res.status} — ${txt}`);
            return false;
        }
        return true;
    } catch (e) {
        console.warn("[demo] save error:", e);
        return false;
    }
}

// Round 88/89 — standalone DemoMenu restored after v2.88 over-hid it.
// The user wanted only the "🎬 Demos ▼" collapsible header removed (it
// was the part they didn't want); the Ollama-powered generator prompt
// + demos list below it should remain. The DemoMenu options below
// (alwaysOpen + hideTitle) handle that; see ui/demoMenu.js.
const demoMenu = new DemoMenu({
    parent: document.body,
    applyDemo,
    generator: demoGenerator,
    saveDemo,
    alwaysOpen: true,    // round 89 — no collapse, body always visible
    hideTitle: true,     // round 89 — remove the "🎬 Demos ▼" header
});
try { window._demoMenu = demoMenu; } catch {}   // v1972 — clean-boot collapses it on start

let lastHit  = null;
let netTimer = 0;
let simEnabled  = true;
let lastSimTick = 0;

