// available. SVG remains as the always-works baseline.
const heartbeatAvatar = new HeartbeatAvatar({
    parent: document.body,
    ollama,
    assetLoader,
    assetName: "heartbeat_mascot_v1",
});
// Round 260 — expose so PipAvatar.ollama.thought() can route here.
// This is the canonical Ollama presence; the OLLAMA slot in PipAvatar
// was retired in v4. The llama emoji + thought bubble live here.
if (typeof window !== "undefined") window.ollamaHeartbeat = heartbeatAvatar;
// v1167 — quick Dogmeat recolor toggle: window.dogmeat() on, window.dogmeat(false) off
if (typeof window !== "undefined") window.dogmeat = (on = true) => { try { return window.ollamaHeartbeat && window.ollamaHeartbeat.setDogmeat ? window.ollamaHeartbeat.setDogmeat(on) : { ok: false }; } catch (e) { return { ok: false, error: String(e && e.message || e) }; } };
// v1000 — retire the standalone OLLAMA floating panel. The llama/pet presence
// will return later expressed through the KPop diorama pet avatar (mapping the
// running AI Models' status into the pet's expressions). Keep the object so the
// mouth-sync + thought() hooks still resolve, but hide its root and mark it
// undocked so PipAvatar won't embed it in the KPop panel either.
try {
    // v1000 retired this floating panel; v1002 hardens it — a saved drag
    // position (_pendingDragPos / localStorage "voxelengine.ollamaPanelPos")
    // was re-floating it past a plain display:none, so force it hidden and
    // drop the pending restore. Object kept so mouth-sync/thought hooks resolve.
    if (heartbeatAvatar?.root) heartbeatAvatar.root.style.setProperty("display", "none", "important");
    heartbeatAvatar._undocked = true;
    heartbeatAvatar._pendingDragPos = null;
    // v1039 — display:none alone wasn't sticking (a saved drag pos re-floated the
    // panel and/or a re-embed reshowed it), so fully detach the external OLLAMA
    // square from the DOM and drop the saved float position. The object is kept
    // so mouth-sync/thought() hooks still resolve (they no-op when off-DOM). The
    // 3D pet llama that wanders the avatar canvas is a SEPARATE thing and stays.
    try { localStorage.removeItem("voxelengine.ollamaPanelPos"); } catch {}
    try { heartbeatAvatar.root && heartbeatAvatar.root.remove(); } catch {}
} catch {}

// Round 97 — KPop bridge client. The PowerShell KPopListener (v9.3+)
// renders WinRT/BurntToast notifications; the bridge relays toast
// payloads from the engine into the named pipe \\.\pipe\KPopListenerPipe.
// Round 109 — default ENABLED. Was off-by-default in round 97 to avoid
// 503 spam when no listener was running; the launcher always starts
// the listener so the connection is reliable now. User can disable via
// the Settings toggle if they want quiet.
const kpop = new KPopClient({ bridgeBase: "" });
if (typeof window !== "undefined") window.kpop = kpop;
try {
    // Default ON unless explicitly set to "0" by the user. localStorage
    // never-set === null → treat as "1".
    const pref = (typeof localStorage !== "undefined") ? localStorage.getItem("voxelEngine.kpopToasts") : "1";
    const enabled = (pref !== "0");
    if (enabled) {
        kpop.setEnabled(true);
        // Round 97 — engine self-announce. When KPop was already enabled
        // from a prior session, probe the listener once and fire a single
        // "SweK Engine online" toast on a successful connection.
        setTimeout(() => {
            kpop.probeStatus({ force: true }).then((s) => {
                if (s && s.running) {
                    kpop.success("SweK Engine online",
                        "Engine loaded and bridge reachable. KPop toasts active.");
                }
            }).catch(() => { /* swallow — already logged inside probe */ });
        }, 600);
    }
} catch (e) { /* private mode */ }

// =============================================================================
// Round 215/216/217 wiring — moved here in v218 so the blocks see kpop
// AFTER its `const` declaration above (was a TDZ ReferenceError when
// constructed near the OLLAMA-LEVEL block). FPS shooter, BotManager +
// pathfinder pool, WadMap companion + replay all need kpop available
// at construction time. All other dependencies (camera, router, world,
// particles, ollamaLevelGen, bridge, assetLoader) are already defined.
// =============================================================================

// Round 225 — gravity warp power-up. Picking up a "gravity" pickup
// flips, rotates, or tilts what counts as "down" for a few seconds.
// Constructed BEFORE FPSShooter so we can inject it into the ctor.
const gravityWarp = new GravityWarp({
    camera,
    fpsShooter: null,    // patched in immediately below
    audio: audio?.audio ?? null,
    canvasId: "glCanvas",
});
window.gravity = {
    warp:       (kind, secs) => gravityWarp.activate(kind, secs),
    stop:       () => gravityWarp.deactivate(),
    isActive:   () => gravityWarp.isActive(),
    ceiling:    (secs) => gravityWarp.activate("ceiling", secs),
    wallLeft:   (secs) => gravityWarp.activate("wall_left", secs),
    wallRight:  (secs) => gravityWarp.activate("wall_right", secs),
    tilt:       (secs) => gravityWarp.activate("tilt", secs),
    stats:      () => gravityWarp.getStats(),
};
console.log("[GRAVITY-WARP] type 'gravity.ceiling()' / .wallLeft() / .wallRight() / .tilt() / .warp(\"random\", 6)");

// Round 241 — underwater swimming. Reads room.water depth; when the
// player's eye drops below the water surface (depth >= 3 + submerged),
// applies swim physics: buoyancy, Space=up, Shift=down, halved walk
// speed, suppressed fall damage. Adds a blue tint via the CanvasFilter
// "submerged" slot. Couples with SpaceSuit — submerged is treated as
// vacuum for O2 drain ("holding breath").
const swimMode = new SwimMode({
    camera,
    fpsShooter: null,    // patched in below
    ollamaLevelGen,
    kpop,
    audio: audio?.audio ?? null,
    particles,           // round 243 — bubble trail when submerged
});
window.swim = {
    status: () => swimMode.getStatus(),
    stats:  () => swimMode.getStats(),
    setOpenWater: (cfg) => swimMode.setOpenWater(cfg || null),   // v1380 — demos register their raised water
};
console.log("[SWIM] water depth >= 5 + eye underwater = swim; depth 3-4 = wade · console: swim.status()");

// Round 236 — space suit. Tracks oxygen + jetpack fuel. Vacuum rooms
// drain O2; the player must keep moving toward atmosphere or die.
// Hold F (KeyF) while FPS is active to thrust upward via jetpack;
// fuel depletes during thrust, regenerates while grounded.
const spaceSuit = new SpaceSuit({
    camera,
    fpsShooter: null,    // patched in below
    particles,
    ollamaLevelGen,
    kpop,
    audio: audio?.audio ?? null,
    swimMode,            // round 241 — submerged → vacuum drain
});
window.spaceSuit = {
    status: () => spaceSuit.getStatus(),
    refillO2:   (a) => spaceSuit.refillO2(a ?? 0.5),
    refillFuel: (a) => spaceSuit.refillFuel(a ?? 0.5),
};
console.log("[SPACE-SUIT] hold F to thrust · vacuum rooms drain O₂ · health packs refill both");

// Round 237 — KAIJU MODE power-up. Picking up a kaiju totem scales
// the player up to building-size for ~12 seconds. Enemies appear
// toenail-tiny from way up high, but their guns still work — bullets
// are scale-independent. The giant player can STOMP nearby enemies
// (5 HP/sec within 4u) and takes HALF damage from incoming fire.
const kaijuMode = new KaijuMode({
    camera,
    fpsShooter: null,    // patched in below
    audio: audio?.audio ?? null,
    kpop,
    world,               // round 249 — for stomp-through-walls
    particles,           // round 249 — debris on broken walls
    canvasId: "glCanvas",
});
window.kaiju = {
    activate:   (secs) => kaijuMode.activate(secs ?? 12),
    deactivate: () => kaijuMode.deactivate(),
    isActive:   () => kaijuMode.isActive(),
    stats:      () => kaijuMode.getStats(),
};
console.log("[KAIJU-MODE] type 'kaiju.activate(12)' to trigger · pickup kind: 'kaiju'");

// Round 253 — Kaiju Sandbox game mode. Standalone game mode where the
// player IS a giant monster destroying a procedural city. Start with
// window.kaijuCity.start(). Take damage with window.kaijuCity.damage(n)
// to test the shrink mechanic.
const cityGen = new CityGen(world);
const kaijuSandbox = new KaijuSandbox({
    camera,
    world,
    particles,
    audio: audio?.audio ?? null,
    kpop,
    cityGen,
    botManager: null,     // round 254 — patched after botManager construction
    fpsShooter: null,     // round 254/258 — patched after FPSShooter construction (TDZ-safe)
    router,               // round 256 — for civilian entity:spawnMesh / move / despawn
});
window.kaijuCity = {
    start:   (opts) => { window.kaijuSim?.start?.(); return kaijuSandbox.start(opts || {}); },
    stop:    () => kaijuSandbox.stop(),
    damage:  (n) => kaijuSandbox.takeDamage(n ?? 1),
    // Round 275 — manual building damage for testing crumble + topple.
    // Pass world (wx, wz) coords + an amount; or "auto" to pick the
    // building nearest the camera and apply enough damage to topple it.
    hitBuilding: (wx, wz, amount = 50) => {
        const cg = cityGen;
        if (!cg) { console.warn("[kaijuCity] no cityGen — start the sandbox first"); return null; }
        const r = cg.damageAt(wx, wz, amount);
        if (!r) { console.log("[kaijuCity] no building at that coord"); return null; }
        console.log(`[kaijuCity] hit ${r.building.h}u building, hp=${r.building.hp.toFixed(1)}/${r.building.maxHp}, crumbled=${r.crumbled}, toppled=${r.toppled}`);
        return r;
    },
    toppleNearest: () => {
        const cg = cityGen;
        if (!cg?.buildings?.length) return null;
        const cam = window._camera;
        let nearest = null, bestD = Infinity;
        const cx = cam?.position?.x ?? 0, cz = cam?.position?.z ?? 0;
        for (const b of cg.buildings) {
            if (b.state === "toppled") continue;
            const d = Math.hypot((b.x + b.w/2) - cx, (b.z + b.d/2) - cz);
            if (d < bestD) { bestD = d; nearest = b; }
        }
        if (!nearest) { console.log("[kaijuCity] no standing buildings"); return null; }
        const r = cg.damageAt(nearest.x + nearest.w/2, nearest.z + nearest.d/2, nearest.maxHp + 1);
        console.log(`[kaijuCity] toppled ${nearest.h}u building at (${nearest.x},${nearest.z})`);
        if (window.kaijuBox3d && window.kaijuBox3d.enabled) window.kaijuBox3d.topple(nearest, [(Math.random()-0.5)*40, 6, (Math.random()-0.5)*40]);   // v2259 — rigid collapse when box3d is on
        return r;
    },
    stats:   () => kaijuSandbox.getStats(),
    isActive:() => kaijuSandbox.isActive(),
    city:    () => cityGen.buildings,
    unbuildCity: () => cityGen.unbuild(),
};
console.log("[KAIJU-CITY] type 'kaijuCity.start()' to begin · '.damage(5)' to shrink · '.stats()' for status");

// Round 340 (v2259) — box3d rigid-body DESTRUCTION layer for the kaiju city. OPT-IN and defensive: when off
// (default) kaijuCity behaves exactly as before. When on (kaijuBox3d.enable(), needs a built WASM +
// box3d.setEnabled(true)) it runs the PHYSICS -- buildings as boxes, the kaiju as a kinematic collider,
// topple/debris/throw -- and hands back transforms via .bodies(). Drawing the toppled/debris meshes at those
// transforms is the renderer's job (RIG): each frame, kaijuBox3d.driveKaiju(kaijuWorldPos); kaijuBox3d.step();
// then draw kaijuBox3d.bodies() as [{ref,pos,quat,kind}]. Everything no-ops until enabled, so it cannot break
// the existing kaiju sim.
window.kaijuBox3d = (() => {
    let scene = null, on = false;
    const remote = new Map();     // v2260 — receiver-side ghost store (id -> {kind,pos,quat})
    return {
        get enabled() { return on && !!scene && scene.ready === true; },
        async enable(opts = {}) {
            try {
                const s = await createSceneFromLoader(box3d, opts);
                if (!s || s.ready !== true) { console.warn("[kaijuBox3d] " + (s && s.reason || "box3d not ready")); return false; }
                s.addBuildings((cityGen && cityGen.buildings) || []);
                scene = s; on = true;
                try { if (!window.box3dOverlay) { const _m = await import("./physics/box3dMeshOverlay.js"); window.box3dOverlay = _m.createBox3dOverlay(); } window.box3dOverlay.start(); } catch (e) { console.warn("[kaijuBox3d] mesh overlay:", e && e.message); }
                console.log(`[kaijuBox3d] ON — ${scene.buildingCount()} buildings as rigid bodies; mesh overlay drawing kaijuBox3d.bodies().`);
                return true;
            } catch (e) { console.warn("[kaijuBox3d] enable failed:", e && e.message); return false; }
        },
        disable() { try { scene && scene.destroy(); } catch {} scene = null; on = false; try { window.box3dOverlay && window.box3dOverlay.stop(); } catch {} },
        driveKaiju(pos, quat) { if (this.enabled) scene.driveKaiju(pos, quat); },
        topple(b, impulse) { return this.enabled ? scene.topple(b, impulse) : null; },
        spawnDebris(pos, n, o) { return this.enabled ? scene.spawnDebris(pos, n, o) : null; },
        throwProp(pos, v, spin, half) { return this.enabled ? scene.throwProp(pos, v, spin, half) : null; },
        step(dt) { if (this.enabled) return scene.step(dt); },
        bodies() { return this.enabled ? scene.activeBodies() : []; },
        // --- v2260: fleet-share. OWNER: broadcast pack() every tick. RECEIVER: applyRemote(packet) then draw remoteBodies().
        pack() { return this.enabled ? packBodies(scene) : null; },
        applyRemote(packet) { applyBodies(remote, packet); return remote.size; },
        remoteBodies() { return [...remote.values()]; },
        lockstep(remoteHash) { return this.enabled ? lockstepStatus(scene.stateHash(), remoteHash) : null; },
        stats() { return this.enabled ? { buildings: scene.buildingCount(), standing: scene.standingCount(), active: scene.activeCount(), hash: scene.stateHash().toString(16) } : { enabled: false }; },
    };
})();
console.log("[kaijuBox3d] rigid destruction layer available (opt-in): box3d.setEnabled(true) then kaijuBox3d.enable() — needs the box3d WASM built");

// Round 341 (v2268) -- one-click kaiju box3d demo. index.html?box3ddemo=1 auto-runs the destruction, so the
// Box3D info-page button and render QA can launch it without the console. Gated on the param; fully defensive
// (no-ops if anything isn't ready); topples a building every ~1.5s for a lively sequence.
try {
    const _bd = new URLSearchParams(location.search);
    if (_bd.get("box3ddemo") === "1" || _bd.get("demo") === "box3d") {
        const _runBox3dDemo = async () => {
            try {
                box3d.setEnabled(true);
                if (window.kaijuBox3d) { try { await window.kaijuBox3d.enable(); } catch {} }
                if (window.kaijuCity) { try { window.kaijuCity.start(); } catch {} }
                let _n = 0; const _iv = setInterval(() => { try { window.kaijuCity && window.kaijuCity.toppleNearest(); } catch {} if (++_n > 40) clearInterval(_iv); }, 1500);
                console.log("[box3ddemo] auto-running kaiju destruction (box3d substrate + kaijuCity topple loop)");
            } catch (e) { console.warn("[box3ddemo]", e && e.message); }
        };
        if (document.readyState === "complete") setTimeout(_runBox3dDemo, 2500);
        else window.addEventListener("load", () => setTimeout(_runBox3dDemo, 2500));
    }
} catch {}

