// Round 272 — console helpers for the audio-driven lip-sync paths.
// `kpop.useBrowser()` toggles route B (window.speechSynthesis).
// `kpop.audioLipSync(text)` exercises route C: requests a WAV from
// the PowerShell side, plays it via an Audio element, taps the
// amplitude with AnalyserNode, and feeds the result to the robot
// mouth via window.parent → iframe postMessage.
window.kpop.useBrowser = (on) => kpop.useBrowser(on);
// v1031 — route D: local bridge TTS (/tts/speak; SAPI or Piper per the TTS
// panel config). `kpop.useLocalTts(true)` gives the avatar one consistent
// local voice across clients; sticky in localStorage, falls back to browser
// TTS if the bridge is unreachable.
window.kpop.useLocalTts = (on) => kpop.useLocalTts(on);
window.kpop.audioLipSync = async (text, voice = "M1") => {
    if (!text) { console.warn("[audioLipSync] need text"); return; }
    const wav = await kpop.speakWav({ Voice: voice, Text: text });
    if (!wav.ok || !wav.url) { console.warn("[audioLipSync] WAV request failed:", wav); return; }
    console.log(`[audioLipSync] got ${wav.url} in ${wav.durationMs}ms — playing + analysing`);
    const audio = new Audio(wav.url);
    const { AudioAnalyser } = await import("./ai/AudioAnalyser.js");
    const an = new AudioAnalyser({ audioElement: audio });
    if (!an.start()) { console.warn("[audioLipSync] AnalyserNode failed to start"); return; }
    // Also fire the existing visual speak so the curve + zoom run
    pipAvatar.speak({ Voice: voice, Text: text });
    audio.addEventListener("ended", () => an.stop());
    audio.play().catch(e => { console.warn("[audioLipSync] play() rejected:", e); });
    // Drive a per-frame amplitude tap into the iframe via postMessage.
    // Iframe overrides its phoneme-curve sample for this duration so
    // the mouth follows actual audio energy.
    const frame = pipAvatar._listener?.iframe;
    const probe = () => {
        if (!an._running) return;
        const a = an.getAmplitude();
        if (frame?.contentWindow) {
            try {
                frame.contentWindow.postMessage({
                    type: "kpop:audio_amp", amp: a,
                }, "*");
            } catch {}
        }
        requestAnimationFrame(probe);
    };
    requestAnimationFrame(probe);
};
// Stop heartbeatAvatar's independent dock-to-tama timer — it's now
// physically embedded in the PIP slot, so it follows the PIP via DOM.
try {
    if (heartbeatAvatar?._dockTimer) {
        clearInterval(heartbeatAvatar._dockTimer);
        heartbeatAvatar._dockTimer = null;
    }
} catch {}
// v412 — the old PIP THE LISTENER window is now headless (constructed with
// { headless: true }), so its DOM is never attached and can't flash on
// startup. Its stat sim still runs in the background; the KPop LISTENER
// panel surfaces the same stats + action buttons.
// Round 277 — asset pipeline console API. Exercises the TripoSR /
// cuda_voxelizer / MeshToVox stack via the bridge. The .vox parser +
// importer are local; voxelization + ComfyUI need the bridge.
// Usage:
//   asset.parseVoxUrl("/asset-pipeline/vox/vox_123.vox")  → preview
//   asset.import("/asset-pipeline/vox/vox_123.vox", 0, 8, 0, {scale:1})
//   asset.voxelize("C:/path/to/model.obj", 128)           → returns voxUrl
//   asset.generateThenImport({workflow}, x, y, z)         → ComfyUI → vox → world
const { parseVox, loadVoxFromUrl } = await import("./tools/voxParser.js");
const { VoxImporter } = await import("./tools/voxImporter.js");
const _voxImporter = new VoxImporter(world);
window.asset = {
    parseVoxUrl: async (url) => {
        const r = await loadVoxFromUrl(url);
        if (!r.ok) { console.warn("[asset.parseVoxUrl]", r.error); return r; }
        const m = r.models[0];
        console.log(`[asset] ${url} — version ${r.version}, ${r.models.length} model(s), first model ${m.sizeX}×${m.sizeY}×${m.sizeZ}, ${m.voxels.length} voxels`);
        return r;
    },
    // Fetch + parse + stamp into world. Default position is in front
    // of the camera so you can immediately see it.
    import: async (url, x = null, y = null, z = null, opts = {}) => {
        const r = await loadVoxFromUrl(url);
        if (!r.ok) { console.warn("[asset.import]", r.error); return null; }
        if (x == null && window._camera) {
            const c = window._camera;
            // Place 8u ahead of where the camera is looking
            const yaw = c.yaw ?? 0;
            x = Math.floor(c.position.x + Math.sin(yaw) * 8);
            z = Math.floor(c.position.z + Math.cos(yaw) * 8);
            y = Math.floor(c.position.y);
        }
        const result = _voxImporter.stamp(r, { x, y, z, ...opts });
        console.log(`[asset.import] stamped ${result.stamped} voxels at (${x},${y},${z}) from ${result.model.sizeX}×${result.model.sizeY}×${result.model.sizeZ} model`);
        return result;
    },
    // Round 281 — async chunked import. For big models (>10K voxels)
    // the sync `import` blocks the main thread long enough to drop
    // frames. This variant yields every 4000 voxels so 60fps holds
    // while a 256³ model is being placed. Logs progress every chunk.
    //
    // Honest framing: this isn't using web workers. The voxel writes
    // have to happen on the main thread (the world data structure
    // isn't worker-transferable), so the actual win is "yield to the
    // renderer between batches" — not parallelism. For genuine GPU-
    // parallel work, see asset.raceGenerators which runs N child
    // processes concurrently on the bridge side.
    importAsync: async (url, x = null, y = null, z = null, opts = {}) => {
        const r = await loadVoxFromUrl(url);
        if (!r.ok) { console.warn("[asset.importAsync]", r.error); return null; }
        if (x == null && window._camera) {
            const c = window._camera;
            const yaw = c.yaw ?? 0;
            x = Math.floor(c.position.x + Math.sin(yaw) * 8);
            z = Math.floor(c.position.z + Math.cos(yaw) * 8);
            y = Math.floor(c.position.y);
        }
        let lastLogged = 0;
        const result = await _voxImporter.stampAsync(r, {
            x, y, z, ...opts,
            onProgress: (p) => {
                // Throttle console logging to every 25%
                const tier = Math.floor(p.percent / 25);
                if (tier > lastLogged) {
                    console.log(`[asset.importAsync] ${p.percent.toFixed(0)}% — ${p.stamped} voxels`);
                    lastLogged = tier;
                }
                opts.onProgress?.(p);
            },
        });
        console.log(`[asset.importAsync] stamped ${result.stamped} voxels at (${x},${y},${z}) from ${result.model.sizeX}×${result.model.sizeY}×${result.model.sizeZ} model`);
        return result;
    },
    // Round 282 — post-process a mesh (hole fill + Laplacian smooth +
    // recompute normals) on the bridge using the engine's pure-JS
    // post-processing algorithms (engine/meshPostProcess.js). Same
    // algorithms the engine's idle scheduler uses on Trellis kaiju
    // mesh swaps — invoked synchronously on the bridge so we can sit
    // between mesh-gen and voxelize in the pipeline.
    //
    // Use this when InstantMesh / Hunyuan3D / Unique3D / CRM outputs
    // have artifacts (zigzag edges, single-triangle holes, faceted
    // shading) before voxelizing. Cleanup typically takes 100-500ms
    // for a 50K-vert mesh.
    postprocessMesh: async (meshPath, opts = {}) => {
        const r = await fetch("/asset-pipeline/postprocess-mesh", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                meshPath,
                smoothIterations: opts.smoothIterations ?? 3,
                smoothLambda:     opts.smoothLambda     ?? 0.5,
                fillHoles:        opts.fillHoles !== false,
                smoothBoundary:   !!opts.smoothBoundary,
            }),
        });
        const j = await r.json();
        if (!j.ok) { console.warn("[asset.postprocessMesh]", j.error, j.hint ?? ""); return j; }
        console.log(`[asset.postprocessMesh] ${meshPath} → ${j.processedUrl} in ${j.durationMs}ms (${j.beforeVerts}→${j.afterVerts} verts, ${j.beforeTris}→${j.afterTris} tris, +${j.addedTriangles} hole tris, ${j.smoothIterations}× smooth)`);
        return j;
    },
    // Round 284 — engine-side post-processing via the idle scheduler.
    // Same algorithms as the bridge-side path (engine/meshPostProcess.js),
    // but runs INSIDE the engine using the existing
    // window.idleTasks.postproc task. The scheduler yields between
    // iterations so the 60fps frame budget is preserved while the
    // mesh cleans up.
    //
    // Returns the SAME shape as postprocessMesh — { ok, processedUrl,
    // meshPath, ... } — by uploading the cleaned mesh back to the
    // bridge so downstream voxelization can fetch it. Difference is
    // WHERE the CPU work happens: bridge thread vs engine idle.
    //
    // Watch the Worker ECG HUD while this runs — you'll see
    // mesh_postprocess pulse via the idle scheduler.
    postprocessOnIdle: async (meshUrl, opts = {}) => {
        const idleTask = window.idleTasks?.postproc;
        if (!idleTask?.enqueue) {
            console.warn("[asset.postprocessOnIdle] idle scheduler post-processor unavailable — was it disabled via voxelengine.idlePostProcess=0?");
            return { ok: false, error: "idle postproc unavailable" };
        }
        // Fetch + parse the OBJ on main thread (cheap)
        // v3103 -- A RESPONSE BODY READ WITHOUT CONSULTING .ok RETURNS THE ERROR PAGE AS DATA. A 404 on this
        // URL used to arrive here as an HTML document and go straight into the mesh parser: the fetch
        // resolved, nothing threw, and the parser got markup. Same bug v3054 fixed for downloads, in a
        // different filename. Refuse with the status, which is the fact the caller needs.
        const _r = await fetch(meshUrl);
        if (!_r.ok) throw new Error("mesh fetch failed: HTTP " + _r.status + " for " + meshUrl);
        const text = await _r.text();
        const parsed = (() => {
            const positions = [];
            const indices   = [];
            for (const line of text.split(/\r?\n/)) {
                if (!line) continue;
                const c0 = line.charCodeAt(0);
                if (c0 === 118 && (line[1] === " " || line[1] === "\t")) {
                    const p = line.split(/\s+/);
                    if (p.length >= 4) positions.push(+p[1], +p[2], +p[3]);
                } else if (c0 === 102 && (line[1] === " " || line[1] === "\t")) {
                    const verts = [];
                    const refs = line.trim().split(/\s+/);
                    for (let i = 1; i < refs.length; i++) {
                        const slash = refs[i].indexOf("/");
                        const idx = parseInt(slash >= 0 ? refs[i].slice(0, slash) : refs[i], 10);
                        if (Number.isFinite(idx)) verts.push(idx - 1);
                    }
                    for (let i = 1; i < verts.length - 1; i++) {
                        indices.push(verts[0], verts[i], verts[i + 1]);
                    }
                }
            }
            return {
                positions: Float32Array.from(positions),
                indices:   Uint32Array.from(indices),
            };
        })();
        const beforeVerts = parsed.positions.length / 3;
        const beforeTris  = parsed.indices.length / 3;
        if (beforeVerts === 0) {
            return { ok: false, error: "mesh parse produced 0 verts" };
        }
        const t0 = performance.now();
        const name = `idle_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
        const result = await idleTask.enqueue(name, parsed.positions, parsed.indices, opts);
        const durationMs = Math.round(performance.now() - t0);
        // Build a new OBJ from the processed buffers + upload to bridge
        const lines = ["# round 284 — post-processed via engine idle scheduler"];
        const N = result.positions.length / 3;
        for (let i = 0; i < N; i++) {
            lines.push(`v ${result.positions[i*3].toFixed(6)} ${result.positions[i*3+1].toFixed(6)} ${result.positions[i*3+2].toFixed(6)}`);
        }
        for (let i = 0; i < N; i++) {
            lines.push(`vn ${result.normals[i*3].toFixed(6)} ${result.normals[i*3+1].toFixed(6)} ${result.normals[i*3+2].toFixed(6)}`);
        }
        const T = result.indices.length / 3;
        for (let i = 0; i < T; i++) {
            const a = result.indices[i*3] + 1;
            const b = result.indices[i*3+1] + 1;
            const c = result.indices[i*3+2] + 1;
            lines.push(`f ${a}//${a} ${b}//${b} ${c}//${c}`);
        }
        const objText = lines.join("\n") + "\n";
        const r = await fetch("/asset-pipeline/postprocess-mesh?smoothIterations=0&fillHoles=0", {
            method: "POST",
            headers: { "Content-Type": "application/octet-stream" },
            body: new TextEncoder().encode(objText),
        });
        const j = await r.json();
        if (!j.ok) {
            console.warn("[asset.postprocessOnIdle] upload-back failed:", j.error);
            return { ok: false, error: j.error, idleStats: result };
        }
        console.log(`[asset.postprocessOnIdle] ${meshUrl} → ${j.processedUrl} via idle scheduler in ${durationMs}ms (${beforeVerts}→${result.positions.length/3} verts, +${result.addedTriangles} hole tris, ${result.smoothIterations}× smooth)`);
        return {
            ok: true,
            processedUrl: j.processedUrl,
            meshPath:     j.meshPath,
            durationMs,
            via:          "idle-scheduler",
            beforeVerts, afterVerts: result.positions.length / 3,
            beforeTris,  afterTris:  result.indices.length / 3,
            addedTriangles: result.addedTriangles,
            unfilledHoles:  result.unfilledHoles,
            smoothIterations: result.smoothIterations,
        };
    },
    // Round 284 — speculative parallel generation. Fires the SLOW
    // primary tool + a FAST fallback tool in parallel. As soon as the
    // fallback returns, calls onPartial so the user sees SOMETHING.
    // When the primary finally returns, calls onFinal with the higher-
    // quality result so the caller can swap.
    //
    // Pattern: heavy Trellis/Hunyuan3D as primary (5min+ on Pascal),
    // CRM or InstantMesh as fallback (~30s). User waits ~30s for the
    // provisional preview, then ~5min for the upgrade.
    speculativeGenerate: async ({ primary, fallback, imagePath, onPartial, onFinal }) => {
        if (!primary || !fallback || primary === fallback) {
            console.warn("[asset.speculativeGenerate] need distinct primary + fallback");
            return { ok: false, error: "need distinct primary + fallback" };
        }
        const t0 = performance.now();
        console.log(`[asset.speculativeGenerate] start — primary=${primary}, fallback=${fallback}`);
        let partialFired = false;
        const fastPromise = window.asset.generateMesh(fallback, imagePath, { postprocess: false })
            .then(j => {
                if (partialFired) return j;   // primary beat us; skip
                if (j?.ok) {
                    partialFired = true;
                    const dt = Math.round(performance.now() - t0);
                    console.log(`[asset.speculativeGenerate] fallback ${fallback} ready in ${dt}ms (provisional)`);
                    try { onPartial?.({ ...j, role: "provisional", tool: fallback, durationMs: dt }); } catch (e) { console.warn(e); }
                }
                return j;
            });
        const slowPromise = window.asset.generateMesh(primary, imagePath, { postprocess: false })
            .then(j => {
                const dt = Math.round(performance.now() - t0);
                if (j?.ok) {
                    if (!partialFired) {
                        // Primary beat the fallback — single result.
                        partialFired = true;
                        try { onPartial?.({ ...j, role: "final-first", tool: primary, durationMs: dt }); } catch (e) { console.warn(e); }
                    }
                    console.log(`[asset.speculativeGenerate] primary ${primary} ready in ${dt}ms (final)`);
                    try { onFinal?.({ ...j, role: "final", tool: primary, durationMs: dt }); } catch (e) { console.warn(e); }
                } else {
                    console.warn(`[asset.speculativeGenerate] primary ${primary} failed — provisional from ${fallback} remains.`);
                }
                return j;
            });
        const [fast, slow] = await Promise.allSettled([fastPromise, slowPromise]);
        return {
            ok: (slow.value?.ok || fast.value?.ok),
            primary: slow.status === "fulfilled" ? slow.value : { ok: false, error: slow.reason?.message },
            fallback: fast.status === "fulfilled" ? fast.value : { ok: false, error: fast.reason?.message },
            durationMs: Math.round(performance.now() - t0),
        };
    },
    // POST a server-side mesh path to the bridge for voxelization.
    // The bridge spawns cuda_voxelizer (preferred) or mesh_to_vox.
    // Round 278 — `solid` argument flips on cuda_voxelizer's -solid
    // flag (fill the interior). Surface-only by default — good for
    // hollow shapes like buildings; flip to true for solid props.
    // Round 279 — `tool` argument forces a specific voxelizer:
    // "auto" (default), "cuda", or "m2v". Used by the benchmark to
    // run head-to-head comparisons without silent fallback.
    voxelize: async (meshPath, dim = 128, solid = false, tool = "auto") => {
        const r = await fetch("/asset-pipeline/voxelize-mesh", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ meshPath, dim, solid, tool }),
        });
        const j = await r.json();
        if (!j.ok) { console.warn("[asset.voxelize]", j.error, j.details ?? "", j.hint ?? ""); return j; }
        console.log(`[asset.voxelize] ${meshPath} → ${j.voxUrl} via ${j.tool}${j.solid?" (solid)":""} in ${j.durationMs}ms`);
        return j;
    },
    // Upload a local mesh file from a File/Blob and voxelize it.
    // Opens a file picker; user picks an .obj or .glb.
    voxelizeUpload: async (dim = 128, solid = false) => {
        return new Promise((resolve) => {
            const input = document.createElement("input");
            input.type = "file";
            input.accept = ".obj,.glb,model/obj,model/gltf-binary";
            input.addEventListener("change", async () => {
                const file = input.files?.[0];
                if (!file) { resolve(null); return; }
                const buf = await file.arrayBuffer();
                // Round 278 — multipart-ish: pass dim+solid as query
                // params so the JSON-body parser doesn't misread the
                // octet stream as JSON.
                const url = `/asset-pipeline/voxelize-mesh?dim=${dim}&solid=${solid?1:0}`;
                const r = await fetch(url, {
                    method: "POST",
                    headers: { "Content-Type": "application/octet-stream" },
                    body: buf,
                });
                const j = await r.json();
                if (j.ok) console.log(`[asset.voxelizeUpload] ${file.name} → ${j.voxUrl}${j.solid?" (solid)":""}`);
                else      console.warn("[asset.voxelizeUpload]", j.error, j.details ?? "");
                resolve(j);
            });
            input.click();
        });
    },
    // Round 278 — probe what tools the bridge has. Useful for UIs
    // that need to show "voxelizer ready" vs "voxelizer missing"
    // before the user clicks a button. Calls /asset-pipeline/status.
    status: async () => {
        try {
            const r = await fetch("/asset-pipeline/status");
            const j = await r.json();
            console.log("[asset.status]");
            console.log(`  cuda_voxelizer: ${j.cuda_voxelizer.found ? `✓ ${j.cuda_voxelizer.path} (v${j.cuda_voxelizer.version})` : `✗ ${j.cuda_voxelizer.reason}`}`);
            console.log(`  mesh_to_vox:    ${j.mesh_to_vox.found    ? `✓ ${j.mesh_to_vox.path} (v${j.mesh_to_vox.version})` : `✗ ${j.mesh_to_vox.reason}`}`);
            console.log(`  ultrashape:     ${j.ultrashape?.found    ? `✓ ${j.ultrashape.repoDir} via ${j.ultrashape.python}` : `✗ ${j.ultrashape?.reason ?? "not detected"}`}`);
            console.log("  mesh generators:");
            for (const [name, g] of Object.entries(j.meshGenerators ?? {})) {
                console.log(`    ${name.padEnd(14)} ${g.found ? `✓ ${g.repoDir} via ${g.python}` : `✗ ${g.reason}`}`);
            }
            console.log(`  comfyUrl:       ${j.comfyUrl}`);
            console.log(`  voxOutDir:      ${j.voxOutDir}`);
            return j;
        } catch (e) {
            console.warn("[asset.status] bridge unreachable:", e?.message ?? e);
            return null;
        }
    },
    // Round 280 — UltraShape 1.0 refinement. Takes a coarse mesh path
    // (server-side) or uploads a local file, runs UltraShape's
    // diffusion refine, returns the refined .obj URL. Slow — first
    // call cold-loads the model (~30s on Pascal), subsequent calls
    // ~10-60s depending on input complexity.
    ultrashapeRefine: async (meshPath) => {
        const r = await fetch("/asset-pipeline/ultrashape-refine", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ meshPath }),
        });
        const j = await r.json();
        if (!j.ok) {
            console.warn("[asset.ultrashapeRefine]", j.error, j.reason ?? "", j.hint ?? "");
            if (j.stderr) console.warn("  stderr:", j.stderr);
            return j;
        }
        console.log(`[asset.ultrashapeRefine] ${meshPath} → ${j.refinedUrl} in ${j.durationMs}ms (exit ${j.exitCode})`);
        return j;
    },
    ultrashapeRefineUpload: async () => {
        return new Promise((resolve) => {
            const input = document.createElement("input");
            input.type = "file";
            input.accept = ".obj,.glb,.ply";
            input.addEventListener("change", async () => {
                const file = input.files?.[0];
                if (!file) { resolve(null); return; }
                const buf = await file.arrayBuffer();
                console.log(`[asset.ultrashapeRefineUpload] uploading ${file.name} (${(buf.byteLength/1024).toFixed(1)} KB)…`);
                const r = await fetch("/asset-pipeline/ultrashape-refine", {
                    method: "POST",
                    headers: { "Content-Type": "application/octet-stream" },
                    body: buf,
                });
                const j = await r.json();
                if (j.ok) console.log(`[asset.ultrashapeRefineUpload] → ${j.refinedUrl} in ${j.durationMs}ms`);
                else      console.warn("[asset.ultrashapeRefineUpload]", j.error, j.stderr ?? "");
                resolve(j);
            });
            input.click();
        });
    },
    // Round 281 — generic image-to-mesh generator. tool is one of
    // "instantmesh", "hunyuan3d", "unique3d", "crm" (or anything the
    // user added to meshGenerators in the config). image is a server-
    // side path; for browser-side file pickers use generateMeshUpload.
    // Round 282 — `postprocess: true` (default) chains the result
    // through /asset-pipeline/postprocess-mesh before returning, so the
    // mesh is cleaned up (hole-fill + smooth + normals) before
    // voxelization. Pass postprocess:false to keep the raw output.
    generateMesh: async (tool, imagePath, opts = {}) => {
        const r = await fetch("/asset-pipeline/generate-mesh", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ tool, imagePath }),
        });
        const j = await r.json();
        if (!j.ok) {
            console.warn(`[asset.generateMesh:${tool}]`, j.error, j.reason ?? "", j.hint ?? "");
            if (j.stderr) console.warn("  stderr:", j.stderr);
            return j;
        }
        console.log(`[asset.generateMesh:${tool}] ${imagePath} → ${j.meshUrl} in ${j.durationMs}ms (exit ${j.exitCode})`);
        // Round 282 — optional inline post-processing. Only .obj
        // outputs are supported by the bridge-side post-processor;
        // .glb / .ply fall through unchanged with a console note.
        if (opts.postprocess !== false && j.meshPath?.toLowerCase().endsWith(".obj")) {
            const pp = await window.asset.postprocessMesh(j.meshPath, opts.postprocessOpts ?? {});
            if (pp?.ok) {
                j.rawMeshPath = j.meshPath;
                j.rawMeshUrl  = j.meshUrl;
                j.meshPath    = pp.meshPath;
                j.meshUrl     = pp.processedUrl;
                j.postprocess = pp;
            }
        } else if (opts.postprocess !== false) {
            console.log(`[asset.generateMesh:${tool}] postprocess skipped — ${j.meshPath} isn't .obj`);
        }
        return j;
    },
    generateMeshUpload: async (tool) => {
        return new Promise((resolve) => {
            const input = document.createElement("input");
            input.type = "file";
            input.accept = "image/png,image/jpeg,image/webp";
            input.addEventListener("change", async () => {
                const file = input.files?.[0];
                if (!file) { resolve(null); return; }
                const buf = await file.arrayBuffer();
                console.log(`[asset.generateMeshUpload:${tool}] uploading ${file.name} (${(buf.byteLength/1024).toFixed(1)} KB)…`);
                const r = await fetch(`/asset-pipeline/generate-mesh?tool=${encodeURIComponent(tool)}`, {
                    method: "POST",
                    headers: { "Content-Type": "application/octet-stream" },
                    body: buf,
                });
                const j = await r.json();
                if (j.ok) console.log(`[asset.generateMeshUpload:${tool}] → ${j.meshUrl} in ${j.durationMs}ms`);
                else      console.warn(`[asset.generateMeshUpload:${tool}]`, j.error, j.stderr ?? "");
                resolve(j);
            });
            input.click();
        });
    },
    // Round 281 — race ALL configured generators on the same image in
    // PARALLEL. Returns per-tool results + identifies the winner
    // (fastest successful). Demonstrates the bridge's ability to
    // saturate multiple child processes — the "are we using our
    // workers" answer at the bridge level (each generator runs in
    // its own subprocess, Node async I/O juggles them).
    raceGenerators: async ({ imagePath = null, imageDataUrl = null, tools = null } = {}) => {
        const body = { imagePath, imageDataUrl, tools };
        const r = await fetch("/asset-pipeline/race-generators", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(body),
        });
        const j = await r.json();
        if (!j.ok) {
            console.warn("[asset.raceGenerators]", j.error, j.hint ?? "");
            return j;
        }
        console.log(`[asset.raceGenerators] ${j.attempted.length} tools raced in ${j.durationMs}ms`);
        for (const [name, run] of Object.entries(j.results)) {
            if (run.ok) console.log(`  ✓ ${name.padEnd(14)} ${run.durationMs}ms → ${run.meshUrl}`);
            else        console.log(`  ✗ ${name.padEnd(14)} ${run.error}`);
        }
        if (j.winner) console.log(`  WINNER: ${j.winner.tool} (${j.winner.durationMs}ms)`);
        return j;
    },
    // Full ComfyUI → voxelize → import pipeline. Requires:
    //   - ComfyUI running on the URL set in asset-pipeline-config.json
    //   - A TripoSR-or-equivalent workflow in `workflow` matching that
    //     ComfyUI install's loaded nodes
    //   - cuda_voxelizer or mesh_to_vox configured
    // Output of ComfyUI's mesh node must be reachable from the bridge
    // (typically ComfyUI's output/ dir).
    generateThenImport: async ({ workflow, meshPathFromComfy }, x = null, y = null, z = null) => {
        const gr = await fetch("/asset-pipeline/comfy-generate", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ workflow }),
        });
        const gj = await gr.json();
        if (!gj.ok) { console.warn("[asset.generateThenImport]", gj.error); return gj; }
        const meshPath = meshPathFromComfy?.(gj) ?? gj.files?.[0]?.filename;
        if (!meshPath) {
            console.warn("[asset.generateThenImport] no mesh path in ComfyUI output", gj);
            return { ok: false, error: "no mesh in ComfyUI output" };
        }
        const vox = await window.asset.voxelize(meshPath);
        if (!vox.ok) return vox;
        return window.asset.import(vox.voxUrl, x, y, z);
    },
};
console.log("[asset] type 'asset.import(url, x, y, z)' to stamp a .vox into the world. See asset-pipeline-config.json for tool paths.");

