// Round 238 — day/night cycle. Full 24-hour rotation in 4 minutes by
// default. Tints + darkens the canvas via the CanvasFilter "lighting"
// slot so vision modes (NVG, flashlight) actually become essential
// at night. Dungeons can pin a fixed hour via "time_of_day" in the
// Ollama layout (e.g., "haunted catacombs at midnight").
const dayNightCycle = new DayNightCycle({
    ollamaLevelGen,
    secondsPerDay: 240,
    startHour: 12,
});
// Round 269 — expose for BotManager (which doesn't have a direct ref)
// to read the current period for midnight-wander behavior.
window._dayNight = dayNightCycle;

// Round 270b — FPS state checkpoint/restore. Persists camera pos +
// energy + time of day to localStorage. Console: fps.save(), fps.load().
const { FpsStateSaver, installFpsSaveConsoleAPI } = await import("./simulation/FpsStateSaver.js");
const fpsStateSaver = new FpsStateSaver({ camera, playerEnergy, dayNightCycle });
installFpsSaveConsoleAPI(fpsStateSaver);
window.time = {
    set:    (h) => dayNightCycle.setHour(h),
    pause:  () => dayNightCycle.pause(),
    resume: () => dayNightCycle.resume(),
    speed:  (secsPerDay) => dayNightCycle.setSecondsPerDay(secsPerDay),
    hour:   () => dayNightCycle.getHour(),
    period: () => dayNightCycle.getPeriod(),
    stats:  () => dayNightCycle.getStats(),
};
// v532 — match the engine sky to your real-world location: the device clock
// sets time-of-day (sun position via DayNightCycle), and Open-Meteo current
// weather sets the weather state. Geolocation (HTTPS + permission) is only
// needed for weather; daylight works from the device clock alone.
window.irl = {
    daylight: () => {
        const now = new Date();
        const h = now.getHours() + now.getMinutes() / 60;
        try { dayNightCycle.setHour(h); } catch {}
        return h;
    },
    // WMO weather code → engine weather state (clear/cloudy/rain/snow/storm)
    codeToState: (code) => {
        if (code == null) return "clear";
        if (code >= 95) return "storm";              // thunderstorm
        if (code >= 85) return "snow";               // snow showers
        if (code >= 80) return "rain";               // rain showers
        if (code >= 71 && code <= 77) return "snow"; // snowfall
        if (code >= 51 && code <= 67) return "rain"; // drizzle / rain
        if (code === 45 || code === 48) return "cloudy"; // fog
        if (code === 2 || code === 3) return "cloudy";   // partly cloudy / overcast
        return "clear";                              // 0,1
    },
    weather: async () => {
        if (typeof navigator === "undefined" || !navigator.geolocation) throw new Error("no geolocation");
        const pos = await new Promise((res, rej) => navigator.geolocation.getCurrentPosition(res, rej, { timeout: 8000, maximumAge: 600000 }));
        const { latitude, longitude } = pos.coords;
        const url = `https://api.open-meteo.com/v1/forecast?latitude=${latitude.toFixed(3)}&longitude=${longitude.toFixed(3)}&current=temperature_2m,weather_code,cloud_cover`;
        const j = await (await fetch(url)).json();
        const code = j?.current?.weather_code;
        const state = window.irl.codeToState(code);
        try { weatherSystem.state = state; weatherSystem._stateAge = 0; } catch {}
        const out = { code, state, temperatureC: j?.current?.temperature_2m, cloud: j?.current?.cloud_cover, lat: +latitude.toFixed(2), lon: +longitude.toFixed(2) };
        window.irl.last = out;   // v533 — kaiju reactivity reads this
        return out;
    },
    sync: async () => {
        const h = window.irl.daylight();
        let w = null, err = null;
        try { w = await window.irl.weather(); } catch (e) { err = e?.message || "weather unavailable"; }
        const hh = String(Math.floor(h)).padStart(2, "0") + ":" + String(Math.round((h % 1) * 60)).padStart(2, "0");
        const msg = `🌍 ${hh} local` + (w ? ` · ${w.state} · ${Math.round(w.temperatureC)}°C` : ` · weather: ${err}`);
        try { window.kpop?.info?.("Real-world sky", msg); } catch {}
        return { hour: h, weather: w, error: err };
    },
    // v1047 — 7-day forecast for the THE WEATHER panel. The bridge auto-detects
    // location via IP (no geolocation prompt) and pulls it from Open-Meteo.
    forecast: async () => { try { let _q = ""; try { const _m = window.engineLocation && window.engineLocation.manual && window.engineLocation.manual(); if (_m) _q = "?lat=" + _m.lat + "&lon=" + _m.lon; } catch {} return await (await fetch("/weather/forecast" + _q)).json(); } catch (e) { return { ok: false, error: e?.message }; } },
    // weather state -> the cloud-layer style that best matches it.
    stateToClouds: (state) => ({ clear: "off", cloudy: "stratocumulus", rain: "nimbostratus", snow: "stratus", storm: "cumulonimbus", fog: "stratus", mist: "stratus" }[state] || "off"),
    // v1454 — accurate cloud TYPE from the granular WMO weather_code + cloud-cover %.
    // Returns one of the cloudLayer types (or "off").
    codeToClouds: (code, cover) => {
        code = +code; const c = (cover == null ? null : +cover);
        if (code >= 95) return "cumulonimbus";                 // thunderstorm
        if (code >= 80 && code <= 82) return "cumulonimbus";   // rain showers (convective)
        if (code >= 85 && code <= 86) return "nimbostratus";   // snow showers
        if (code >= 71 && code <= 77) return "stratus";        // snowfall
        if (code >= 61 && code <= 67) return "nimbostratus";   // rain
        if (code >= 51 && code <= 57) return "nimbostratus";   // drizzle
        if (code === 45 || code === 48) return "stratus";      // fog
        if (code === 3) return (c != null && c >= 90) ? "stratus" : "stratocumulus";   // overcast
        if (code === 2) return "cumulus";                      // partly cloudy
        if (c != null && c >= 55) return "stratocumulus";      // clear/mainly-clear (0,1): let cover decide
        if (c != null && c >= 20) return "cumulus";
        if (c != null && c >= 8)  return "cirrus";
        return "off";
    },
    // Style the sky clouds (and weather state) from the bridge's current
    // condition — no permission prompt, runs off the IP-detected location.
    autoClouds: async (opts = {}) => {
        const f = (opts && opts.forecast) || await window.irl.forecast();
        if (!f || !f.ok || !f.current) return null;
        const state = window.irl.codeToState(f.current.code);
        const ct = window.irl.codeToClouds(f.current.code, f.current.cloud);
        try { if (ct === "off") window.clouds?.off?.(); else window.clouds?.set?.(ct); } catch {}
        try { weatherSystem.state = state; weatherSystem._stateAge = 0; } catch {}
        window.irl.last = { code: f.current.code, state, clouds: ct, tempF: f.current.tempF, cloud: f.current.cloud, pressure: f.current.pressure, place: f.place, lat: f.lat, lon: f.lon };
        return window.irl.last;
    },
    // v1454 — geocode a typed place ("Boston, MA" / "Tokyo") -> { lat, lon, name }.
    // Open-Meteo's geocoding API is CORS-open, so this runs client-side.
    geocode: async (query) => {
        const q = String(query || "").trim(); if (!q) return null;
        const url = `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(q)}&count=1&language=en&format=json`;
        try { const j = await (await fetch(url)).json(); const r = j && j.results && j.results[0]; if (!r) return null; return { lat: r.latitude, lon: r.longitude, name: [r.name, r.admin1, r.country_code].filter(Boolean).join(", ") }; } catch (e) { return null; }
    },
};
console.log("[irl] window.irl.sync() — time-of-day from your clock + weather from Open-Meteo (location permission needed for weather)");
console.log("[DAY-NIGHT] time.set('night') · time.speed(60) for 1min cycle · time.pause()");
// v1096 — Real Terrain (Stage 2): voxelize real elevation + paint OSM streets,
// with the house at the origin (kaiju epicenter). Data = world/realTerrainData.js,
// voxelizer = world/realTerrainStamp.js (installs world._heightOverride + regenerate).
window.realTerrain = {
    last: null,
    // Demo options (persisted). raisedRoads = curb/causeway look; buildings = OSM 3D.
    opts: (() => { try { return Object.assign({ raisedRoads: false, buildings: true, water: true, source: "open-meteo", mapboxToken: "" }, JSON.parse(localStorage.getItem("voxelengine.realTerrainOpts") || "{}")); } catch { return { raisedRoads: false, buildings: true, water: true, source: "open-meteo", mapboxToken: "" }; } })(),
    setOpt(k, v) { this.opts[k] = v; try { localStorage.setItem("voxelengine.realTerrainOpts", JSON.stringify(this.opts)); } catch {} },
    preview: () => { try { window.open("/realterrain.html", "_blank"); } catch {} },
    async load(o = {}) {
        const lat = +o.lat, lon = +o.lon;
        if (!isFinite(lat) || !isFinite(lon)) throw new Error("realTerrain.load needs {lat, lon}");
        const sizeM = +o.sizeM || 2000, grid = +o.grid || 32;
        const wantBuildings = (o.buildings !== undefined) ? !!o.buildings : !!this.opts.buildings;
        const wantWater     = (o.water !== undefined) ? !!o.water : !!this.opts.water;
        const raisedRoads   = (o.raisedRoads !== undefined) ? !!o.raisedRoads : !!this.opts.raisedRoads;
        const source        = o.source || this.opts.source || "open-meteo";
        const mapboxToken   = o.mapboxToken || this.opts.mapboxToken || "";
        console.log(`[realTerrain] fetching ${grid}\u00d7${grid} @ ${lat.toFixed(4)},${lon.toFixed(4)} (${(sizeM/1000).toFixed(2)}km) buildings=${wantBuildings} raised=${raisedRoads}\u2026`);
        const { fetchRealTerrain } = await import("./world/realTerrainData.js");
        const { applyRealTerrain } = await import("./world/realTerrainStamp.js");
        const data = await fetchRealTerrain({ lat, lon, sizeM, grid, buildings: wantBuildings, water: wantWater, source, mapboxToken });
        window.realTerrain.last = data;
        window.realTerrain._lastCenter = { lat, lon, sizeM, grid, source };
        const summary = applyRealTerrain(world, data, { baseY: o.baseY, amp: o.amp, region: o.region, raisedRoads, metersPerVoxel: o.metersPerVoxel, maxBuildings: o.maxBuildings, maxBuildingVox: o.maxBuildingVox });
        try {
            const y = (summary.centerSurface || 24) + 18;
            camera.position.x = 0; camera.position.z = 0; camera.position.y = y;
            if ("pitch" in camera) camera.pitch = -0.45;
        } catch {}
        try {
            const clip = summary.buildingsClipped > 0 ? ` (+${summary.buildingsClipped} clipped)` : "";
            window._toaster?.show?.({ title: "\\uD83C\\uDF0D Real terrain", msg: `${summary.roadsPainted} roads \u00b7 ${summary.buildingsPainted} buildings${clip} \u00b7 elev ${data.min.toFixed(0)}\u2013${data.max.toFixed(0)}m`, type: "system", duration: 4500 });
            if (summary.buildingsClipped > 0) window._toaster?.show?.({ title: "\\uD83C\\uDFD9 Buildings capped", msg: `${summary.buildingsTotal} found; drew ${summary.buildingsPainted}, skipped ${summary.buildingsClipped} (dense area). Raise via realTerrain.load({maxBuildings, maxBuildingVox}) or shrink the box.`, type: "warning", duration: 6500 });
        } catch {}
        return summary;
    },
    // v1454 — load real terrain for a TYPED place (geocodes via window.irl.geocode),
    // then matches the sky clouds to that location's live weather.
    async goTo(query, o = {}) {
        const g = await window.irl?.geocode?.(query);
        if (!g) { console.warn(`[realTerrain] couldn't find "${query}"`); try { window._toaster?.show?.({ title: "Location not found", msg: String(query), type: "warning", duration: 3500 }); } catch {} return null; }
        console.log(`[realTerrain] ${g.name} \u2192 ${g.lat.toFixed(4)},${g.lon.toFixed(4)}`);
        const summary = await window.realTerrain.load(Object.assign({ lat: g.lat, lon: g.lon }, o));
        try { const f = await (await fetch(`/weather/forecast?lat=${g.lat}&lon=${g.lon}`)).json(); if (f && f.ok) await window.irl.autoClouds({ forecast: f }); } catch {}
        return { place: g.name, lat: g.lat, lon: g.lon, summary };
    },
    here(o = {}) {
        if (typeof navigator === "undefined" || !navigator.geolocation) { console.warn("[realTerrain] no geolocation"); return; }
        console.log("[realTerrain] requesting your location\u2026");
        navigator.geolocation.getCurrentPosition(
            (p) => window.realTerrain.load(Object.assign({ lat: p.coords.latitude, lon: p.coords.longitude }, o)).catch((e) => console.warn("[realTerrain]", e.message)),
            (e) => console.warn("[realTerrain] location failed:", e.message),
            { timeout: 8000, maximumAge: 600000 }
        );
    },
    // Drop a kaiju on the house (world origin = epicenter), falling in from above.
    spawnKaiju(kind = "sky") {
        try { return kaijuManager.summon({ kind, x: 0, y: 32, z: 0 }); }
        catch (e) { console.warn("[realTerrain] spawnKaiju:", e?.message); return null; }
    },
    async clear() {
        const { clearRealTerrain } = await import("./world/realTerrainStamp.js");
        clearRealTerrain(world);
    },
    // --- Saved locations ---
    presets() { try { return JSON.parse(localStorage.getItem("voxelengine.realTerrainPresets") || "{}"); } catch { return {}; } },
    savePreset(name) {
        const c = this._lastCenter; if (!c) { console.warn("[realTerrain] nothing loaded yet"); return; }
        name = (name || `${c.lat.toFixed(4)},${c.lon.toFixed(4)}`).trim();
        const all = this.presets(); all[name] = c;
        try { localStorage.setItem("voxelengine.realTerrainPresets", JSON.stringify(all)); } catch {}
        console.log(`[realTerrain] saved preset "${name}"`); return name;
    },
    loadPreset(name) { const p = this.presets()[name]; if (!p) { console.warn("[realTerrain] no preset:", name); return; } return this.load(p); },
    delPreset(name) { const all = this.presets(); delete all[name]; try { localStorage.setItem("voxelengine.realTerrainPresets", JSON.stringify(all)); } catch {} },
    // --- Shareable link: open this URL and the Real Terrain demo loads this exact spot ---
    shareLink() {
        const c = this._lastCenter; if (!c) { console.warn("[realTerrain] nothing loaded yet"); return ""; }
        const u = `${location.origin}/?rtlat=${c.lat.toFixed(5)}&rtlon=${c.lon.toFixed(5)}&rtsize=${c.sizeM}&rtsrc=${c.source || "open-meteo"}`;
        try { navigator.clipboard?.writeText?.(u); console.log("[realTerrain] share link copied:", u); } catch { console.log("[realTerrain] share link:", u); }
        return u;
    },
    _fromUrl() {
        try {
            const q = new URLSearchParams(location.search);
            const lat = parseFloat(q.get("rtlat")), lon = parseFloat(q.get("rtlon"));
            if (!isFinite(lat) || !isFinite(lon)) return null;
            return { lat, lon, sizeM: +q.get("rtsize") || 2000, source: q.get("rtsrc") || undefined };
        } catch { return null; }
    },
    // Picked up from the preview page's "Send to engine" (shared localStorage).
    loadPending() {
        let p = this._fromUrl();
        if (!p) { try { const raw = localStorage.getItem("voxelengine.realTerrainPending"); if (raw) { p = JSON.parse(raw); localStorage.removeItem("voxelengine.realTerrainPending"); } } catch {} }
        if (p && isFinite(+p.lat) && isFinite(+p.lon)) { this.load(p).catch((e) => console.warn("[realTerrain]", e.message)); return true; }
        return false;
    },
    // Demo start hook: prefer a shared/pending location, else geolocation.
    autoStart() { if (!this.loadPending()) this.here(); },
};
console.log("[realTerrain] window.realTerrain.here() / .load({lat,lon,sizeM,grid,buildings,water,raisedRoads}) / .spawnKaiju() / .savePreset() / .shareLink() / .clear()");

// v1112 — shared location resolver. Prefers Real Terrain (the spot you're
// looking at), then a shared link, then a saved preset / last opts, then the
// browser's geolocation. Used by location-aware features like ADS-B aircraft.
window.engineLocation = {
    _cacheKey: "voxelengine.lastLocation",
    cached() { try { const j = JSON.parse(localStorage.getItem(this._cacheKey) || "null"); return (j && isFinite(j.lat) && isFinite(j.lon)) ? j : null; } catch { return null; } },
    _save(loc) { try { localStorage.setItem(this._cacheKey, JSON.stringify({ lat: loc.lat, lon: loc.lon, source: loc.source, at: Date.now() })); } catch {} return loc; },
    // v1588 — a manually pinned lat/lon (paste "41.7315, -71.4008" from Google Maps). Wins over every
    // auto source for weather / NEXRAD radar / live aircraft, and sidesteps the browser's "secure
    // origins only" geolocation block on an http:// LAN page.
    _manualKey: "voxelengine.manualLocation",
    manual() { try { const m = JSON.parse(localStorage.getItem(this._manualKey) || "null"); return (m && isFinite(m.lat) && isFinite(m.lon)) ? { lat: m.lat, lon: m.lon, source: "manual" } : null; } catch { return null; } },
    setManual(lat, lon) {
        if (typeof lat === "string" && (lon === undefined || lon === null)) { const m = lat.match(/(-?\d+(?:\.\d+)?)\s*[,\s]\s*(-?\d+(?:\.\d+)?)/); if (!m) throw new Error('paste as "lat, lon" e.g. 41.7315, -71.4008'); lat = +m[1]; lon = +m[2]; }
        lat = +lat; lon = +lon;
        if (!isFinite(lat) || !isFinite(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) throw new Error("lat must be -90..90, lon -180..180");
        try { localStorage.setItem(this._manualKey, JSON.stringify({ lat, lon, at: Date.now() })); } catch {}
        // v1589 — one pin drives everything: also feed the STATUS-panel live weather (wxLat/wxLon) and refresh it.
        try { localStorage.setItem("voxelengine.wxLat", String(lat)); localStorage.setItem("voxelengine.wxLon", String(lon)); if (window._hud && window._hud._fetchLiveWx) window._hud._fetchLiveWx(); } catch {}
        return this._save({ lat, lon, source: "manual" });
    },
    clearManual() { try { localStorage.removeItem(this._manualKey); } catch {} },
    async get({ allowGeo = true } = {}) {
        const _man = this.manual(); if (_man) return this._save(_man);   // v1588 — explicit pin wins
        const rt = window.realTerrain;
        if (rt && rt._lastCenter && isFinite(rt._lastCenter.lat)) return this._save({ lat: rt._lastCenter.lat, lon: rt._lastCenter.lon, source: "real terrain (loaded)" });
        try { const u = rt && rt._fromUrl && rt._fromUrl(); if (u && isFinite(u.lat)) return this._save({ lat: u.lat, lon: u.lon, source: "shared link" }); } catch {}
        try { const ps = (rt && rt.presets && rt.presets()) || {}; const keys = Object.keys(ps); const k = keys.find(x => /home/i.test(x)) || keys[0]; if (k && isFinite(ps[k].lat)) return this._save({ lat: ps[k].lat, lon: ps[k].lon, source: `real terrain preset '${k}'` }); } catch {}
        try { const o = JSON.parse(localStorage.getItem("voxelengine.realTerrainOpts") || "null"); if (o && isFinite(o.lat) && isFinite(o.lon)) return this._save({ lat: o.lat, lon: o.lon, source: "real terrain (last opts)" }); } catch {}
        const c = this.cached(); if (c) return c;
        if (allowGeo && navigator.geolocation) {
            return await new Promise((resolve, reject) => {
                navigator.geolocation.getCurrentPosition(
                    (p) => resolve(this._save({ lat: p.coords.latitude, lon: p.coords.longitude, source: "geolocation" })),
                    (e) => reject(new Error("geolocation: " + (e && e.message || e))),
                    { enableHighAccuracy: false, timeout: 8000, maximumAge: 600000 }
                );
            });
        }
        throw new Error("no location available (load Real Terrain or allow geolocation)");
    },
};
