        window.radar = { show: _noop, hide: _noop, toggle: _noop, refresh: _noop, status: _noop, config: _noop,
            setAllow: _noop, setSyncAllow: _noop, request: _noop, requestSync: _noop, syncWeather: _noop, setNexrad: _noop, _retired: true };
