// v1691 — the engine robot reacts to CIV events too (not just toasts): a kaiju goes down -> cheer; a model placed -> nod.
// (Render-pipeline events are handled in the self-healing render loop's catch below: a frame error -> the robot flashes.)
try {
    civEvents.subscribe((evt) => {
        try {
            const bot = window.dockedGauges && window.dockedGauges.robot && window.dockedGauges.robot();
            if (!bot || !bot.react || !evt || !evt.type) return;
            if (evt.type === "kaiju_death") bot.react({ msg: "kaiju defeated", level: "success" });   // -> cheer (throttled)
            else if (evt.type === "model_placed") bot.react({ msg: "model placed (building)" });        // -> nod (throttled)
        } catch (e) {}
    });
    console.log("[swekRobot] engine robot wired to civ events (kaiju_death -> cheer, model_placed -> nod)");
} catch (e) {}
// v1643 — docked renderless mode. While the top-center SVG dock is the active view (the default in the bare
// sandbox), throttle the 3D render to a low fps so CPU drops, and tuck the separate avatar panel away. The dock's
// full-render / full-avatar controls promote back to a live render. window.renderMode for console control.
(() => {
    let _floorFps = 2, _on = false;
    const apply = (on) => { _on = !!on; try { visibility.setRenderFloor(on ? _floorFps : null); } catch {} };
    // v1677 — the dock showing no longer auto-throttles the 3D to 2fps (that made the sandbox choppy). The bare
    // sandbox now renders at full fps; the low-fps "dock leads" mode is opt-in via window.renderMode.renderless(true).
    window.addEventListener("swek:dockActive",     () => { try { window.pip && window.pip.hide && window.pip.hide(); } catch {} });
    window.addEventListener("swek:dockInactive",   () => { apply(false); try { window.pip && window.pip.show && window.pip.show(); } catch {} });   // left the sandbox -> full render + restore the avatar for the demo
    window.addEventListener("swek:dockFullRender", () => { apply(false); try { window.demoChrome && window.demoChrome.setSvg && window.demoChrome.setSvg(false); } catch {} });   // v1771 - bring up the existing 3D gauge/avatar diorama (the demoChrome stage: avatars + llama + 3D gauges + fidget scenes)
    window.addEventListener("swek:dockSvg",        () => { apply(true);  try { window.demoChrome && window.demoChrome.setSvg && window.demoChrome.setSvg(true); } catch {} });   // v1771 - drop the diorama back to its low-power SVG tier (pauses the GPU stage)
    window.addEventListener("swek:dockFullAvatar", () => { apply(false); try { window.pip && window.pip.show && window.pip.show(); } catch {} });
    window.renderMode = {
        renderless: (on) => apply(on !== false),
        full: () => apply(false),
        isRenderless: () => _on,
        setFloorFps: (n) => { _floorFps = Math.max(0.5, Math.min(30, +n || 2)); if (_on) apply(true); return _floorFps; },
    };
    try { console.log("[renderMode] ready \u2014 sandbox renders full fps; window.renderMode.renderless(true) drops to ~" + _floorFps + "fps, .full() resumes, .setFloorFps(n)"); } catch {}
})();
