// v1623 — wave to a cloud peer, preferring the free WebRTC data channel when a P2P link is open, else the cloud
// relay. The remote already turns a {t:"announce"} channel message into a peerCameo, so P2P waves cost no egress.
try { window.cloudWave = async (peerId, text) => { try {
    const open = window.cloudPeer && window.cloudPeer.peers && window.cloudPeer.peers().some((x) => x.id === peerId && x.state === "open");
    if (open) { const c = await fetch("/cloud/config").then((r) => r.json()).catch(() => ({})); const me = (c && c.name) || "A peer"; const n = window.cloudPeer.send({ t: "announce", ann: { fromName: me, kind: "info", text: text || (me + " waves hello"), gestures: ["wave", "speak"], id: "wave-" + Date.now().toString(36) } }, peerId); return { ok: n > 0, via: "p2p" }; }
    const j = await fetch("/cloud/wave", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ to: peerId, text }) }).then((r) => r.json()); return Object.assign({ via: "relay" }, j);
} catch (e) { return { ok: false, error: String(e && e.message || e) }; } }; } catch {}
// v1624 — send art to a REMOTE peer's HA frame: fetch the image (same-origin, authed), base64 it, hand it to the
// bridge which relays it via the cloud blob + a targeted "frame" message. The peer casts it to its own display.
try { window.sendArtToPeer = async (peerId, imageUrl) => { try {
    const res = await fetch(imageUrl); if (!res.ok) return { ok: false, error: "fetch " + res.status };
    const blob = await res.blob();
    const b64 = await new Promise((rs, rj) => { const fr = new FileReader(); fr.onload = () => rs(String(fr.result).split(",")[1]); fr.onerror = () => rj(new Error("read failed")); fr.readAsDataURL(blob); });
    return await fetch("/cloud/frame", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ to: peerId, imageData: b64, type: blob.type || "image/jpeg" }) }).then((r) => r.json());
} catch (e) { return { ok: false, error: String(e && e.message || e) }; } }; } catch {}
