                    y: loc.y + Math.random() * 5,
                    z: loc.z + Math.sin(a) * r,
                    vx: Math.cos(a) * (4 + Math.random() * 6),
                    vy: 4 + Math.random() * 8,
                    vz: Math.sin(a) * (4 + Math.random() * 6),
                    ttl: 1.5 + Math.random(),
