// --- NEW Terrain tab (erosion + flooding — relocated from the old panel) ---
let eroRadius = 48, eroDrops = 18000, flMode = "Lake", flLevel = 12, flVolume = 4000, flRadius = 64;
// v495 — animated flooding: a gated interval driver ticks the conserving water
// flow (window.flood.updateFlow). Off by default; only runs while toggled on.
let floodFlowRate = 3, _floodTimer = null;
// v505 — river driver: springs feed water that flows + carves a channel. Gated OFF.
let riverCarve = 0.4, _riverTimer = null;
const _riverTick = () => { try { window.flood?.pumpSprings?.(1); window.flood?.updateFlow?.(0.1, { flowRate: floodFlowRate, carveChance: riverCarve }); } catch {} };
const _setRiver = (on) => { if (on && !_riverTimer) _riverTimer = setInterval(_riverTick, 150); else if (!on && _riverTimer) { clearInterval(_riverTimer); _riverTimer = null; } };
const _floodTick = () => { try { window.flood?.updateFlow?.(0.1, { flowRate: floodFlowRate }); } catch {} };
const _setFloodFlow = (on) => {
    if (on && !_floodTimer) _floodTimer = setInterval(_floodTick, 120);
    else if (!on && _floodTimer) { clearInterval(_floodTimer); _floodTimer = null; }
};

// v516 — waterfall driver: scan near the camera for water spilling over edges
// and emit the falling sheet + mist. Read-only (no voxel writes). Gated OFF.
let waterfallR = 36, _waterfallTimer = null;
const _waterfallTick = () => { try { window._waterfallSys?.scan?.(Math.round(camera.position.x), Math.round(camera.position.z), { radius: waterfallR }); } catch {} };
const _setWaterfalls = (on) => { if (on && !_waterfallTimer) _waterfallTimer = setInterval(_waterfallTick, 180); else if (!on && _waterfallTimer) { clearInterval(_waterfallTimer); _waterfallTimer = null; } };

// v516 — rain runoff driver: while it's raining/storming, sprinkle water onto
// the terrain near the camera and run the flow sim so rivers swell + lowlands
// flood; when the sky clears, evaporate the shallow puddles so it recedes.
// Reads the live weather state each tick. Gated OFF (opt-in).
let rainDrops = 26, _rainHydroTimer = null;
const _rainHydroTick = () => {
    try {
        const st = (typeof weatherSystem !== "undefined" ? weatherSystem.state : null);
        const wet = (st === "rain" || st === "storm");
        const cxr = Math.round(camera.position.x), czr = Math.round(camera.position.z);
        if (wet) { window.flood?.rainfall?.(cxr, czr, { drops: rainDrops, radius: 60 }); window.flood?.updateFlow?.(0.1, { flowRate: 3 });
                   if (Math.random() < 0.015) { try { window.flashFlood?.({ volume: 3000 }); } catch {} } }   // v519 — storm surge
        else { window.flood?.evaporateShallow?.(cxr, czr, { radius: 90, chance: 0.12 }); }
    } catch {}
};
const _setRainHydro = (on) => { if (on && !_rainHydroTimer) _rainHydroTimer = setInterval(_rainHydroTick, 220); else if (!on && _rainHydroTimer) { clearInterval(_rainHydroTimer); _rainHydroTimer = null; } };

// v517 — current viz: spawn drifting foam flecks on the fastest moving water
// cells near the camera so the flow DIRECTION is visible. Read-only; needs
// active flow (river / gush / rain). Gated OFF.
let _currentVizTimer = null;
const _currentVizTick = () => {
    try {
        const gp = window.gpuParticles; if (!gp?.spawn || !window.flood?.currentSamples) return;
        const cxr = Math.round(camera.position.x), czr = Math.round(camera.position.z);
        const samples = window.flood.currentSamples({ centerX: cxr, centerZ: czr, radius: 40, max: 50, minSpeed: 0.4 });
        for (const s of samples) {
            gp.spawn({
                x: s.x + 0.5 + (Math.random() - 0.5) * 0.5, y: s.y + 0.6, z: s.z + 0.5 + (Math.random() - 0.5) * 0.5,
                vx: s.vx * 2.2, vy: 0.3 + Math.random() * 0.3, vz: s.vz * 2.2,
                life: 0.55 + Math.random() * 0.3, size: 0.32,
                r: 0.95, g: 0.98, b: 1.0, shape: 4,        // soft white foam fleck
            });
        }
    } catch {}
};
const _setCurrentViz = (on) => { if (on && !_currentVizTimer) _currentVizTimer = setInterval(_currentVizTick, 160); else if (!on && _currentVizTimer) { clearInterval(_currentVizTimer); _currentVizTimer = null; } };

// v530 — watershed: snowmelt feeds streams that flow downhill, pool into lakes,
// overflow toward the sea (mass-conserving flow finds its level), and the
// material rivers carve settles as deltas / silt where the water slows. Opt-in
// (it carves terrain + costs CPU); ties the hydrology arc together.
let _watershedTimer = null;
const _watershedTick = () => {
    const fl = window.flood; if (!fl) return;
    try {
        const cx = Math.round(camera.position.x), cz = Math.round(camera.position.z);
        fl.snowmelt(cx, cz, { radius: 30, chance: 0.06, max: 50 });        // snowcaps feed streams
        fl.updateFlow(0.2, { flowRate: 4, carveChance: 0.05 });            // flow finds its level + cuts channels
        fl.depositSediment(cx, cz, { radius: 44, max: 30 });               // deltas / silt where it slows
    } catch (e) {}
};
const _setWatershed = (on) => { if (on && !_watershedTimer) _watershedTimer = setInterval(_watershedTick, 240); else if (!on && _watershedTimer) { clearInterval(_watershedTimer); _watershedTimer = null; } };
window.watershed = {
    on:  () => { _setWatershed(true);  console.log("[watershed] ON — snowmelt → streams → lakes → overflow → sea, with deltas"); },
    off: () => { _setWatershed(false); console.log("[watershed] OFF"); },
    status: () => ({ running: !!_watershedTimer, sediment: window.flood?.sediment, carved: window.flood?.carved, activeFlow: window.flood?.flow?.size }),
};

