          repoBtn.addEventListener("click", async () => { await api("config", collectCfg()); repoMsg.textContent = "loading\u2026"; const j = await fetch("/github/repos").then(r => r.json()).catch(() => ({})); if (!j || !j.ok) { repoMsg.textContent = "\u2717 " + ((j && j.error) || "failed"); return; } repoMsg.textContent = j.count + " repos"; repoBox.style.display = "block"; repoBox.innerHTML = ""; for (const r of j.repos) { const row = document.createElement("div"); row.style.cssText = "display:flex;gap:6px;align-items:center;padding:2px 0;cursor:pointer;"; row.title = "click to set as publish target"; const star = r.private ? "\uD83D\uDD12" : "\u2606"; row.innerHTML = `<span style="color:#9fd">${star} ${r.name}</span> <span style="color:#667">\u00B7 ${(r.pushedAt||"").slice(0,10)}</span> ${r.desc ? '<span style="color:#789">\u2014 ' + r.desc.slice(0,42) + '</span>' : ''}`; row.addEventListener("click", () => { pRepo.value = r.name; pubMsg.textContent = "publish target: " + r.name; }); repoBox.appendChild(row); } });
          pubBtn.addEventListener("click", async () => { await api("config", collectCfg()); if (!pRepo.value.trim() || !pTag.value.trim()) { pubMsg.textContent = "need a repo and a version tag"; pubMsg.style.color = "#f88"; return; } pubBtn.disabled = true; pubMsg.style.color = "#8b97a8"; pubMsg.textContent = "publishing\u2026" + (pAsset.value.trim() ? " (uploading asset can take a bit)" : ""); const j = await api("publish", { repo: pRepo.value.trim(), tag: pTag.value.trim(), name: pName.value.trim(), body: pNotes.value, assetPath: pAsset.value.trim(), draft: draft.checked, prerelease: pre.checked }); pubBtn.disabled = false; if (j && j.ok) { const rel = j.release || {}; const as = j.asset; pubMsg.innerHTML = "\u2713 released <b>" + rel.tag + "</b>" + (as ? (as.ok ? " + asset uploaded" : " (asset failed: " + as.error + ")") : "") + "<br><a href='" + rel.url + "' target='_blank' style='color:#7fbfff'>" + rel.url + "</a>"; pubMsg.style.color = "#9fe88f"; } else { pubMsg.textContent = "\u2717 " + ((j && j.error) || "failed"); pubMsg.style.color = "#f88"; } });
