// v1134 — Power Automate flow hooks (outbound webhooks on engine events).
_schema.push({ id: "flowhooks", label: "Flow Hooks", icon: "\u26A1", controls: [
    { id: "flowHooks", type: "custom", label: "Power Automate / webhook events",
      render(host) {
          host.style.cssText = "display:flex; flex-direction:column; gap:8px;";
          const hint = document.createElement("div"); hint.style.cssText = "color:#7a8290; font-size:11px; line-height:1.5;";
          hint.innerHTML = 'Fire engine events to a <b>Power Automate</b> flow (or any webhook). In Power Automate, create a flow with the <i>\u201cWhen an HTTP request is received\u201d</i> trigger, copy its POST URL, and paste it below. The engine POSTs <code>{event, ts, source, data}</code> outbound when the chosen events happen \u2014 no inbound exposure needed. (That trigger is a Power Automate <b>Premium</b> feature; the URL is a secret, stored mode-600.)';
          host.appendChild(hint);
          const listWrap = document.createElement("div"); listWrap.style.cssText = "display:flex; flex-direction:column; gap:6px;"; host.appendChild(listWrap);
          const msg = document.createElement("div"); msg.style.cssText = "font-size:11px; color:#8b97a8; min-height:14px;"; host.appendChild(msg);

          let EVENTS = [];
          const evLabel = { "petfbi.assembled": "PetFBI report assembled", "petfbi.emailed": "PetFBI emailed to admin", "report.posted": "Report marked posted", "rule.matched": "Email rule matched" };
          const post = (u, b) => fetch(u, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(b || {}) }).then(r => r.json()).catch(e => ({ ok: false, error: e.message }));

          function hookCard(h, isNew) {
              const card = document.createElement("div"); card.style.cssText = "border:1px solid #232c38; border-radius:8px; padding:8px; display:flex; flex-direction:column; gap:6px; background:#0c0f14;";
              const url = document.createElement("input"); url.type = "text"; url.value = h.url || ""; url.placeholder = "https://prod-XX.westus.logic.azure.com/workflows/.../triggers/manual/paths/invoke?..."; url.style.cssText = "padding:6px 8px;background:#0c0f14;color:#e8eef8;border:1px solid #2a3340;border-radius:6px;font:10.5px ui-monospace,monospace;width:100%;box-sizing:border-box;";
              card.appendChild(url);
              const evRow = document.createElement("div"); evRow.style.cssText = "display:flex; flex-wrap:wrap; gap:8px 12px;";
              const checks = {};
              for (const e of EVENTS) { const l = document.createElement("label"); l.style.cssText = "display:flex; gap:5px; align-items:center; font-size:11px; color:#cde;"; const cb = document.createElement("input"); cb.type = "checkbox"; cb.checked = (h.events || []).includes(e); checks[e] = cb; l.append(cb, document.createTextNode(evLabel[e] || e)); evRow.appendChild(l); }
              card.appendChild(evRow);
              const btnRow = document.createElement("div"); btnRow.style.cssText = "display:flex; gap:6px; align-items:center;";
              const en = document.createElement("label"); en.style.cssText = "display:flex; gap:5px; align-items:center; font-size:11px; color:#9be;"; const enCb = document.createElement("input"); enCb.type = "checkbox"; enCb.checked = h.enabled !== false; en.append(enCb, document.createTextNode("enabled"));
              const mk = (t, bg, br) => { const b = document.createElement("button"); b.textContent = t; b.style.cssText = `padding:5px 10px;background:${bg};color:#dfe;border:1px solid ${br};border-radius:6px;cursor:pointer;font-size:11px;`; return b; };
              const saveB = mk(isNew ? "Add hook" : "Save", "#2a4d3a", "#4a7d5a"), testB = mk("Test", "#3a4a6a", "#5a6a8a"), delB = mk("Remove", "#5a3a3a", "#8a5a5a");
              const collect = () => ({ id: h.id, url: url.value.trim(), enabled: enCb.checked, events: EVENTS.filter(e => checks[e].checked) });
              saveB.addEventListener("click", async () => { const j = await post("/flowhooks/save", collect()); msg.textContent = j.ok ? "\u2713 saved" : "\u2717 " + (j.error || "failed"); msg.style.color = j.ok ? "#9fe88f" : "#f88"; if (j.ok) load(); });
              testB.addEventListener("click", async () => { if (isNew) { msg.textContent = "add the hook first"; return; } msg.textContent = "testing\u2026"; const j = await post("/flowhooks/test", { id: h.id }); msg.textContent = j.ok ? ("\u2713 flow responded " + (j.status || "OK")) : "\u2717 " + (j.error || ("status " + j.status)); msg.style.color = j.ok ? "#9fe88f" : "#f88"; });
              delB.addEventListener("click", async () => { if (isNew) { card.remove(); return; } const j = await post("/flowhooks/remove", { id: h.id }); if (j.ok) load(); });
              if (isNew) { btnRow.append(en, saveB); } else { btnRow.append(en, saveB, testB, delB); }
              card.appendChild(btnRow);
              return card;
          }

          async function load() {
              const j = await fetch("/flowhooks/list").then(r => r.json()).catch(() => null);
              listWrap.innerHTML = "";
              if (!j || !j.ok) { listWrap.textContent = "could not load hooks"; return; }
              EVENTS = j.events || [];
              for (const h of (j.hooks || [])) listWrap.appendChild(hookCard(h, false));
              const addHdr = document.createElement("div"); addHdr.textContent = (j.hooks || []).length ? "\u2795 Add another" : "\u2795 Add your first flow hook"; addHdr.style.cssText = "font-size:11px;color:#8b97a8;margin-top:4px;"; listWrap.appendChild(addHdr);
              listWrap.appendChild(hookCard({ events: [], enabled: true }, true));
          }
          load();
      } },
]});

