// v1421 — global install watcher. We do NOT poll for things that are merely
// "not installed"; only once an install is INITIATED do we watch (every 3s)
// until each item is detected installed, announce it, then STOP. Works even
// with the Settings panel closed, and idles completely when nothing installs.
let _installWatch = null; const _installPrev = {};
function _watchInstalls() {
    if (_installWatch) return;   // already watching
    const step = async () => {
        const data = await window.autoInstall.list();
        let anyInstalling = false;
        if (data && data.ok) for (const it of (data.items || [])) {
            if (it.installing) anyInstalling = true;
            if (it.installed && _installPrev[it.id] === false) {
                try { window.demoChrome && window.demoChrome.tick && window.demoChrome.tick(`\u2713 ${it.label} installed`); } catch {}
                console.log(`[autoinstall] ${it.id} detected installed`);
            }
            if (it.lastErr && !it.installed && !it.installing && _installPrev[it.id] !== undefined) {
                try { window.demoChrome && window.demoChrome.tick && window.demoChrome.tick(`\u26a0 ${it.label} install failed`); } catch {}
            }
            _installPrev[it.id] = !!it.installed;
        }
        if (anyInstalling) { _installWatch = setTimeout(step, 3000); }   // keep watching
        else { _installWatch = null; }                                   // nothing installing -> STOP
    };
    step();
}
window.autoInstall.run    = (orig => (id) => { const p = orig(id); _watchInstalls(); return p; })(window.autoInstall.run);
window.autoInstall.ensure = (orig => (id) => { const p = orig(id); _watchInstalls(); return p; })(window.autoInstall.ensure);
window.autoInstall.watch  = _watchInstalls;

