              if (!r || !r.ok) { lfMsg.textContent = "LedFx unreachable (" + ((r && r.error) || "?") + ")"; return; }
              let scenes = {}; try { scenes = (JSON.parse(r.raw).scenes) || {}; } catch {}
              const ids = Object.keys(scenes); if (!ids.length) { lfMsg.textContent = "no scenes saved in LedFx"; return; }
              for (const id of ids) { const b = btn(scenes[id].name || id); b.style.fontSize = "10px"; b.addEventListener("click", async () => { const j = await fetch("/ledfx/scene", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ base, id }) }).then(r => r.json()).catch(() => null); lfMsg.textContent = (j && j.ok) ? "\u2713 " + (scenes[id].name || id) : "activate failed"; }); lfGrid.appendChild(b); }
              lfMsg.textContent = ids.length + " scene(s)";
