          bm.append(bmUrl, bmTarget, bmRow, bmMsg); host.appendChild(bm);
          const haCall = (domain, service, data) => fetch("/ha/call", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ domain, service, data: data || {} }) }).then(r => r.json()).catch(() => null);
          bmPop.addEventListener("click", async () => { const u = bmUrl.value.trim(); if (!u) { bmMsg.textContent = "enter a URL"; return; } const data = { content: { type: "iframe", url: u }, size: "wide" }; if (bmTarget.value.trim()) data.browser_id = bmTarget.value.trim(); const j = await haCall("browser_mod", "popup", data); bmMsg.textContent = j && j.ok !== false ? "\u2713 popped" : "failed — is Browser Mod installed?"; });
          bmClose.addEventListener("click", async () => { const data = bmTarget.value.trim() ? { browser_id: bmTarget.value.trim() } : {}; await haCall("browser_mod", "close_popup", data); bmMsg.textContent = "closed"; });

          // ---------- Music Assistant ----------
          const ma = mkH("\uD83C\uDFB5 Music Assistant", "Play a URL or control any media player MA exposes.");
