          const maUrl = inp("media URL (mp3/stream)"); maUrl.style.margin = "4px 0";
          const maCtl = document.createElement("div"); maCtl.style.cssText = "display:flex;gap:4px;"; const maPlayUrl = btn("Play URL"); const maPause = btn("\u23f8"); const maPrev = btn("\u23ee"); const maNext = btn("\u23ed"); maCtl.append(maPlayUrl, maPrev, maPause, maNext);
          const maMsg = document.createElement("div"); maMsg.style.cssText = "font-size:10px;color:#8b97a8;margin-top:3px;";
          ma.append(maRow, maUrl, maCtl, maMsg); host.appendChild(ma);
          maScan.addEventListener("click", async () => { const r = await fetch("/ha/states?domain=media_player", { cache: "no-store" }).then(r => r.json()).catch(() => null); const list = (r && (r.states || r)) || []; maSel.innerHTML = ""; (Array.isArray(list) ? list : []).forEach(e => { const o = document.createElement("option"); o.value = e.entity_id; o.textContent = (e.attributes && e.attributes.friendly_name) || e.entity_id; maSel.appendChild(o); }); maMsg.textContent = (maSel.options.length || 0) + " player(s)"; });
          const maSvc = (service, extra) => { const ent = maSel.value; if (!ent) { maMsg.textContent = "scan + pick a player"; return; } return haCall("media_player", service, Object.assign({ entity_id: ent }, extra || {})); };
          maPlayUrl.addEventListener("click", async () => { const u = maUrl.value.trim(); if (!u) { maMsg.textContent = "enter a URL"; return; } await maSvc("play_media", { media_content_id: u, media_content_type: "music" }); maMsg.textContent = "\u25b6 playing"; });
          maPause.addEventListener("click", () => { maSvc("media_play_pause"); });
          maPrev.addEventListener("click", () => { maSvc("media_previous_track"); });
          maNext.addEventListener("click", () => { maSvc("media_next_track"); });
