// --- NEW Auto-start tab (boot demo + session demo rotation / kiosk mode) ---
// Wires the ready boot hook: localStorage "voxelengine.autostart" = a demo id,
// or "dealer_choice" for the random rotation. Boot reads it on the next load.
let rotateSecs = 45, _rotateTimer = null;
const _asGet = () => { try { return localStorage.getItem("voxelengine.autostart") || ""; } catch { return ""; } };
const _asSet = (v) => { try { if (v) localStorage.setItem("voxelengine.autostart", v); else localStorage.removeItem("voxelengine.autostart"); } catch {} };
const _setRotate = (on) => {
    if (on && !_rotateTimer) _rotateTimer = setInterval(() => { try { demoManager.setById("dealer_choice"); } catch {} }, Math.max(5, rotateSecs) * 1000);
    else if (!on && _rotateTimer) { clearInterval(_rotateTimer); _rotateTimer = null; }
};
_schema.push({ id: "autostart", label: "Auto-start", icon: "▶", controls: [
    { id: "asMode", label: "On load, start", hint: "Applies on the next page load", type: "select", options: ["Off (blank room)", "Random demo", "Pin current demo"],
      get: () => { const a = _asGet(); return a === "dealer_choice" ? "Random demo" : (a ? "Pin current demo" : "Off (blank room)"); },
      set: (v) => {
          if (v === "Random demo") { _asSet("dealer_choice"); window.kpop?.info?.("Auto-start", "random demo on next load"); }
          else if (v === "Pin current demo") { const id = demoManager.current?.id || "blank_sandbox"; _asSet(id); window.kpop?.info?.("Auto-start", `pinned '${id}'`); }
          else { _asSet(""); window.kpop?.info?.("Auto-start", "off (blank room)"); }
      } },
    { id: "asPlayNow", label: "Play random demo now", hint: "Roll Dealer's Choice immediately", type: "button",
      action: () => { try { demoManager.setById("dealer_choice"); } catch { window.kpop?.info?.("Auto-start", "no demo manager"); } } },
    { id: "asRotate", label: "Auto-rotate (kiosk)", hint: "Switch to a new random demo on a timer", type: "toggle",
      get: () => !!_rotateTimer, set: (v) => _setRotate(v) },
    { id: "asRotateSecs", label: "Rotate every (s)", hint: "Seconds between random demos", type: "slider", min: 10, max: 180, step: 5,
      get: () => rotateSecs, set: (v) => { rotateSecs = v | 0; if (_rotateTimer) { _setRotate(false); _setRotate(true); } } },
    { id: "asRotationList", type: "custom", label: "Rotation demos",
      render: (box) => {
          const dr = window.demoRotation;
          const playable = (d) => d.id !== "dealer_choice" && d.autoplay !== false && typeof d.start === "function";
          const draw = () => {
              box.innerHTML = "";
              const title = document.createElement("div");
              title.textContent = "Demos in the auto-rotation — uncheck to exclude";
              Object.assign(title.style, { fontSize: "13px", fontWeight: "600", marginBottom: "2px" });
              const sub = document.createElement("div");
              sub.textContent = "Built-in, added .js, and Home Assistant panels. Greyed = no auto-play demo mode.";
              Object.assign(sub.style, { fontSize: "11px", color: "#9aa", marginBottom: "8px" });
              box.appendChild(title); box.appendChild(sub);
              const legend = document.createElement("div");
              try {
                  const k = _clientKind();
                  legend.innerHTML = "Badges = where each runs: <b style='color:#9fe0a8'>PC</b> / <b style='color:#9fe0a8'>Phone</b> / <b style='color:#9fe0a8'>TV</b> (green=usable, <b style='color:#d8d08a'>\u00b7watch</b>=visual only, grey=not here). You're on: <b style='color:#7fd1ff'>" + (k === "tv" ? "Android TV / Shield" : k === "phone" ? "Phone" : "PC") + "</b> \u2014 demos this device can't drive are dimmed.";
              } catch {}
              Object.assign(legend.style, { fontSize: "10.5px", color: "#8b97a8", marginBottom: "9px", lineHeight: "1.5", paddingBottom: "7px", borderBottom: "1px solid #1c2531" });
              box.appendChild(legend);
              if (!dr || typeof DEMO_MODES === "undefined") { const e = document.createElement("div"); e.textContent = "(demo list not ready)"; e.style.color = "#9aa"; box.appendChild(e); return; }
              const section = (heading, arr) => {
                  if (!arr.length) return;
                  const gh = document.createElement("div");
                  gh.textContent = heading;
                  Object.assign(gh.style, { fontSize: "11px", color: "#7af", textTransform: "uppercase", letterSpacing: "0.05em", margin: "8px 0 3px" });
                  box.appendChild(gh);
                  for (const d of arr) {
                      const ok = playable(d);
                      const row = document.createElement("label");
                      Object.assign(row.style, { display: "flex", alignItems: "center", gap: "8px", padding: "3px 0", fontSize: "12.5px", cursor: ok ? "pointer" : "default", opacity: ok ? "1" : "0.45" });
                      const chk = document.createElement("input");
                      chk.type = "checkbox";
                      chk.checked = ok ? dr.isEnabled(d.id) : false;
                      chk.disabled = !ok;
                      chk.style.accentColor = "#4af"; chk.style.cursor = ok ? "pointer" : "default";
                      if (ok) chk.addEventListener("change", () => dr.setEnabled(d.id, chk.checked));
                      const name = document.createElement("span");
                      name.textContent = (d.label || d.id) + (ok ? "" : "  · no demo mode");
                      row.appendChild(chk); row.appendChild(name);
                      // v1157 — platform badges (PC / Phone / TV) + dim if THIS client can't really use it
                      const pinfo = DEMO_PLATFORMS[d.id];
                      if (pinfo) {
                          const kind = _clientKind();
                          const badges = document.createElement("span");
                          badges.style.cssText = "margin-left:auto; display:flex; gap:4px; align-items:center; flex-shrink:0;";
                          for (const p of [["pc", "PC"], ["phone", "Phone"], ["tv", "TV"]]) {
                              const onP = pinfo.plat.includes(p[0]);
                              const playOnly = onP && p[0] !== "pc" && _DEMO_PLAY_PC_ONLY.has(d.id);   // renders here but play=PC
                              const b = document.createElement("span");
                              b.textContent = p[1] + (playOnly ? "\u00b7watch" : "");
                              b.title = playOnly ? (p[1] + " \u2014 self-runs as a visual; play on PC") : (onP ? (p[1] + " \u2014 supported") : (p[1] + " \u2014 not usable here"));
                              b.style.cssText = "font-size:9.5px; padding:1px 5px; border-radius:4px; white-space:nowrap; " + (onP ? (playOnly ? "background:#2a2f1a;color:#d8d08a;border:1px solid #5a5a2f;" : "background:#1f3a2a;color:#9fe0a8;border:1px solid #2f6a45;") : "background:#1a1d22;color:#566;border:1px solid #2a2f36;");
                              badges.appendChild(b);
                          }
                          row.appendChild(badges);
                          if (!pinfo.plat.includes(kind)) { row.style.opacity = String(Math.min(Number(row.style.opacity || 1), 0.6)); }
                          if (pinfo.note) name.title = pinfo.note;
                      }
                      box.appendChild(row);
                  }
              };
              const _isHA = (m) => m.category === "Home Assistant";
              section("Tour order", DEMO_MODES.filter((m) => !m._discovered && !_isHA(m) && m.setPos != null).sort((a, b) => a.setPos - b.setPos));
              section("Built-in demos", DEMO_MODES.filter((m) => !m._discovered && !_isHA(m) && m.setPos == null));
              section("Home Assistant panels", DEMO_MODES.filter((m) => _isHA(m)));
              section("Added demos / panels", DEMO_MODES.filter((m) => m._discovered && !_isHA(m)));
              const bar = document.createElement("div");
              Object.assign(bar.style, { marginTop: "10px", display: "flex", gap: "8px" });
              const mk = (txt, on) => { const b = document.createElement("button"); b.textContent = txt; Object.assign(b.style, { background: "#234", color: "#cde", border: "1px solid #456", borderRadius: "5px", padding: "4px 10px", cursor: "pointer", fontSize: "12px" });
                  b.addEventListener("click", () => { for (const d of DEMO_MODES) if (playable(d)) dr.setEnabled(d.id, on); draw(); }); return b; };
              bar.appendChild(mk("All on", true)); bar.appendChild(mk("All off", false));
              box.appendChild(bar);
          };
          draw();
      } },
]});

// --- NEW Ice & Snow tab (water→ice freezing + snow accumulation + thaw) ---
let freezeParams = { radius: 40, maxSnowDepth: 3, iceThickness: 2, freezeWater: true, snow: true };
