// v506 — earthquake camera shake (transient offset undone each tick, so no drift
// and player movement during the shake is preserved). Approximate; races the
// render loop slightly but the offsets are tiny.
let _shakeTimer = null, _shakeOff = { x: 0, y: 0, z: 0 }, _shakeEnd = 0, _shakeSecs = 1, _shakeMag = 0.4;
const _nowMs = () => (typeof performance !== "undefined" ? performance.now() : Date.now());
const _quakeShake = (seconds = 1, mag = 0.4) => {
    _shakeSecs = seconds; _shakeMag = mag; _shakeEnd = _nowMs() + seconds * 1000;
    if (_shakeTimer) return;
    _shakeTimer = setInterval(() => {
        try { camera.position.x -= _shakeOff.x; camera.position.y -= _shakeOff.y; camera.position.z -= _shakeOff.z; } catch {}
        const now = _nowMs();
        if (now >= _shakeEnd) { _shakeOff = { x: 0, y: 0, z: 0 }; clearInterval(_shakeTimer); _shakeTimer = null; return; }
        const k = Math.max(0, (_shakeEnd - now) / (_shakeSecs * 1000));
        const a = _shakeMag * k;
        _shakeOff = { x: (Math.random() - 0.5) * a, y: (Math.random() - 0.5) * a * 0.6, z: (Math.random() - 0.5) * a };
        try { camera.position.x += _shakeOff.x; camera.position.y += _shakeOff.y; camera.position.z += _shakeOff.z; } catch {}
    }, 16);
};
