          const mkInput = (ph) => { const i = document.createElement("input"); i.type = "text"; i.placeholder = ph; i.autocomplete = "off"; i.style.cssText = "width:100%;padding:6px 8px;background:#0c0f14;color:#e8eef8;border:1px solid #2a3340;border-radius:6px;font:11px ui-monospace,monospace;"; return i; };

