          hint.innerHTML = 'The avatar\u2019s local voice (route D). <b>SAPI</b> is Windows\u2019 built-in voice \u2014 zero install. <b>Piper</b> is rhasspy/piper neural TTS \u2014 much nicer, needs the piper binary + a <code>.onnx</code> voice model. Grab a Windows build from <code>github.com/rhasspy/piper/releases</code> and a voice from <code>github.com/rhasspy/piper-voices</code> (e.g. en_US-lessac-medium), then point the two paths below at them.';
          host.appendChild(hint);

          const engRow = document.createElement("div"); engRow.style.cssText = "display:flex; gap:8px; align-items:center;";
          const engSel = document.createElement("select"); engSel.style.cssText = "padding:5px 8px;background:#0c0f14;color:#e8eef8;border:1px solid #2a3340;border-radius:6px;font-size:11px;";
          for (const [v, t] of [["sapi", "SAPI (Windows, built-in)"], ["piper", "Piper (neural, local)"]]) { const o = document.createElement("option"); o.value = v; o.textContent = t; engSel.appendChild(o); }
          engRow.append(lbl("Engine"), engSel); host.appendChild(engRow);

