          const enRow = document.createElement("label"); enRow.style.cssText = "display:flex; gap:8px; align-items:center; font-size:12px; color:#cde;";
          const enChk = document.createElement("input"); enChk.type = "checkbox";
          enRow.append(enChk, document.createTextNode("Enable motion reactions")); host.appendChild(enRow);
          const reactWrap = document.createElement("label"); reactWrap.style.cssText = "display:flex; gap:8px; align-items:center; font-size:11px; color:#cde;";
          const react = document.createElement("select"); react.style.cssText = "padding:5px 8px;background:#0c0f14;color:#e8eef8;border:1px solid #2a3340;border-radius:6px;font:11px ui-monospace,monospace;";
          [["toast","Toast only"],["announce","Announce the location (speak)"],["wall","Show the camera on the screen wall"],["kaiju","Spawn a kaiju"],["all","All of the above"]].forEach(([v,t]) => { const o = document.createElement("option"); o.value = v; o.textContent = t; react.appendChild(o); });
          reactWrap.append(document.createTextNode("Reaction"), react); host.appendChild(reactWrap);
