          const labelIn = mkIn("name (e.g. Pip-Boy)"); const urlIn = mkIn("/GPU_Assets/PipBoy.glb  or  https://…/model.glb");
          host.append(labelIn, urlIn);
          const row = document.createElement("div"); row.style.cssText = "display:flex; gap:7px; flex-wrap:wrap;";
          const addBtn = document.createElement("button"); addBtn.textContent = "Add to avatar choices"; addBtn.style.cssText = "padding:5px 12px;background:#16202c;color:#cde;border:1px solid #2a3340;border-radius:6px;cursor:pointer;font-size:12px;";
          const useBtn = document.createElement("button"); useBtn.textContent = "Add + use as my avatar"; useBtn.style.cssText = "padding:5px 12px;background:#2a4d3a;color:#cfe;border:1px solid #4a7d5a;border-radius:6px;cursor:pointer;font-size:12px;";
          row.append(addBtn, useBtn); host.appendChild(row);
          const msg = document.createElement("span"); msg.style.cssText = "font-size:11px; color:#8b97a8; min-height:14px;"; host.appendChild(msg);
          const listWrap = document.createElement("div"); listWrap.style.cssText = "display:flex; flex-direction:column; gap:4px; margin-top:4px;"; host.appendChild(listWrap);
          const renderList = () => {
              listWrap.innerHTML = "";
              const favs = getFavs().filter(f => /\.glb($|\?)/i.test(f.url || ""));
              if (!favs.length) { const e = document.createElement("div"); e.style.cssText = "font-size:11px;color:#7a8290;"; e.textContent = "No custom GLBs registered yet."; listWrap.appendChild(e); return; }
              const head = document.createElement("div"); head.style.cssText = "font-size:10px;color:#7a8290;text-transform:uppercase;letter-spacing:1px;"; head.textContent = "Registered GLB avatars"; listWrap.appendChild(head);
              favs.forEach(f => {
                  const r = document.createElement("div"); r.style.cssText = "display:flex;gap:8px;align-items:center;font-size:11px;color:#cde;";
                  const nm = document.createElement("span"); nm.textContent = f.label || f.url; nm.style.flex = "1"; nm.style.fontFamily = "ui-monospace,monospace";
                  const use = document.createElement("button"); use.textContent = "use"; use.style.cssText = "padding:2px 8px;background:#16202c;color:#9fe88f;border:1px solid #2a3340;border-radius:5px;cursor:pointer;font-size:10px;";
                  const del = document.createElement("button"); del.textContent = "✕"; del.style.cssText = "padding:2px 7px;background:#16202c;color:#f88;border:1px solid #2a3340;border-radius:5px;cursor:pointer;font-size:10px;";
                  use.onclick = () => { useAvatar(f.url); msg.textContent = "✓ set as avatar — reload demos to see it"; msg.style.color = "#9fe88f"; };
                  del.onclick = () => { setFavs(getFavs().filter(x => x.url !== f.url)); renderList(); msg.textContent = "✓ removed"; msg.style.color = "#9fe88f"; };
                  r.append(nm, use, del); listWrap.appendChild(r);
              });
          };
          const doAdd = () => { const url = urlIn.value.trim(); if (!url) { msg.textContent = "GLB URL/path required"; msg.style.color = "#f88"; return null; } if (!/\.glb($|\?)/i.test(url)) { msg.textContent = "expected a .glb URL/path"; msg.style.color = "#f88"; return null; } const label = labelIn.value.trim() || url.split("/").pop().replace(/\.glb.*$/i, ""); const favs = getFavs(); if (!favs.some(f => f.url === url)) favs.push({ label, url }); setFavs(favs); renderList(); return url; };
          addBtn.onclick = () => { const u = doAdd(); if (u) { msg.textContent = "✓ added — it’s in the avatar pickers (reopen Settings)"; msg.style.color = "#9fe88f"; labelIn.value = urlIn.value = ""; } };
          useBtn.onclick = () => { const u = doAdd(); if (u) { useAvatar(u); msg.textContent = "✓ added + set as avatar — reload demos to see it"; msg.style.color = "#9fe88f"; labelIn.value = urlIn.value = ""; } };
