// v1079 — engine state -> lights. Drives ALL RGB lights (/rgb/all) in reaction to
// engine + smart-home events: weather tint, day/night warm/cool, Fallout low-HP
// red pulse, and a motion/doorbell flash. Opt-in; conflicts with the solar/game
// follows and the manual RGB panel (they all paint the same lights), so use one
// driver at a time. window.haScene(id) fires a Home Assistant scene.
// v1524 — role read: avatar cycle <- "favorite" tag. Library assets tagged
// "favorite" (in the Roles matrix) flow into the kpopFavorites store so they show
// up in every avatar picker/cycle that already reads it. Tag-sourced entries use a
// /assets/glb?id= URL (loadable via the v1522 raw-GLB route); they're added when
// tagged and pruned when untagged, leaving the user's own favorites untouched.
async function syncAvatarFavorites() {
    const store = window.kpopFavorites, lib = window.assetLibrary;
    if (!store || !store.list || !store.add || !lib || !lib.list) return;
    let r; try { r = await Promise.resolve(lib.list({ type: "mesh" })); } catch { return; }
    const arr = Array.isArray(r) ? r : (r && (r.items || r.assets)) || [];
    const tagged = new Map();   // id -> { url, label }
    for (const a of arr) {
        const id = a && (a.id || a.assetId);
        if (id && Array.isArray(a.tags) && a.tags.includes("favorite")) {
            tagged.set(String(id), { url: "/assets/glb?id=" + encodeURIComponent(id), label: a.name || a.label || ("asset " + String(id).slice(0, 6)) });
        }
    }
    const isTagUrl = (u) => String(u || "").indexOf("/assets/glb?") === 0;
    const idFromUrl = (u) => { const m = /[?&]id=([^&]+)/.exec(String(u || "")); return m ? decodeURIComponent(m[1]) : null; };
    let existing = []; try { existing = store.list() || []; } catch {}
    // add newly-tagged
    for (const [, info] of tagged) { try { if (!store.has(info.url)) store.add(info.url, info.label); } catch {} }
    // prune tag-sourced favorites that are no longer tagged
    for (const f of existing) { if (isTagUrl(f.url)) { const id = idFromUrl(f.url); if (id && !tagged.has(id)) { try { store.remove(f.url); } catch {} } } }
}
window.syncAvatarFavorites = syncAvatarFavorites;
(function _initFavSync() {
    let tries = 0;
    const tick = () => {
        if (window.kpopFavorites && window.assetLibrary && window.assetLibrary.list) { syncAvatarFavorites(); return; }
        if (tries++ < 40) setTimeout(tick, 500);   // wait up to ~20s for the library client to come up
    };
    tick();
})();

// v1523 / v1533 — VMware VM power control (vmrun) client helpers. Drives /vm/* on
// the bridge. Now TARGET-AWARE: pass a base URL (a discovered peer like
// "http://192.168.50.109:8787") to control THAT machine's VMs from here; omit it
// (or window.vm.base = "") for this PC. CORS is permissive and auth is opt-in +
// LAN-exempt, so cross-box control works on a trusted LAN with no extra setup.
window.vm = {
    base: "",
    _b(b) { return String(b == null ? (window.vm.base || "") : b).replace(/\/+$/, ""); },
    status:  (vmx, b)       => fetch(window.vm._b(b) + "/vm/status" + (vmx ? "?vmx=" + encodeURIComponent(vmx) : "")).then(r => r.json()),
    list:    (b)            => fetch(window.vm._b(b) + "/vm/list").then(r => r.json()),
    images:  (b)            => fetch(window.vm._b(b) + "/vm/images").then(r => r.json()),
    config:  (c, b)         => fetch(window.vm._b(b) + "/vm/config", c ? { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(c) } : undefined).then(r => r.json()),
    start:   (vmx, b, gui)  => fetch(window.vm._b(b) + "/vm/start",   { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ vmx, gui: !!gui }) }).then(r => r.json()),
    stop:    (vmx, mode, b) => fetch(window.vm._b(b) + "/vm/stop",    { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ vmx, mode }) }).then(r => r.json()),
    restart: (vmx, mode, b) => fetch(window.vm._b(b) + "/vm/restart", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ vmx, mode }) }).then(r => r.json()),
    reset:   (vmx, mode, b) => fetch(window.vm._b(b) + "/vm/reset",   { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ vmx, mode }) }).then(r => r.json()),
    peers:   ()             => fetch("/sync/best").then(r => r.json()).then(j => (j && j.pool) || []).catch(() => []),
};
