// Round 219 — WAD level transition loop. When the player walks into an
// open exit portal, generate a fresh level via Ollama and restart FPS
// at the new spawn. Reuses the same prompt by default, so successive
// dungeons feel cohesive; user can override by setting
// window.fps._nextLevelPrompt before clearing.
fpsShooter.onExitEntered(() => {
    const prompt = fpsShooter._nextLevelPrompt
                || fpsShooter.levelName
                || "an underground dungeon with traps and treasure";
    // Round 221 — if autopilot was active when the player walked
    // through the exit, keep it active across the level transition
    // (so the AI plays through multiple dungeons in sequence).
    const wasAutoplay = fpsAutopilot.active;
    // Round 222 — bump the dungeon level counter + escalate bot density
    // ever so gently (0.7 at LV1, 0.9 at LV5, capped at 1.2 at LV10+).
    fpsShooter.levelNumber++;
    const lvl = fpsShooter.levelNumber;
    const density = Math.min(1.2, 0.7 + (lvl - 1) * 0.05);
    // Brief delay so audio cue + toast read before the world shifts
    setTimeout(async () => {
        fpsShooter.stop();
        try {
            await fpsShooter.start({
                wadLevel: prompt,
                spawnBots: true,
                botDensity: density,
            });
            if (wasAutoplay) {
                setTimeout(() => fpsAutopilot.engage(), 1200);
            }
        } catch (e) {
            console.warn("[FPS] next-level transition failed:", e?.message ?? e);
        }
    }, 900);
});

