// Round 255 — turret defense for OGRE waves. Each new wave spawns
// bot_turret entities at the arena's defender slots. The turrets
// fire at the OGRE/kaijus during the wave. Cleared on next wave
// start (despawn previous before placing new).
let _ogreTurretIds = [];
ogreScenario._onWaveSpawned = (waveNumber, arena) => {
    if (!arena?.placeTurrets) return;
    // Clear previous wave's turrets
    for (const id of _ogreTurretIds) {
        try {
            if (botManager?.bots?.has(id)) botManager._onBotKilled(id);
        } catch {}
    }
    _ogreTurretIds = [];
    // Place new turrets. Count scales with wave: 4 base + 1 per 3 waves.
    const maxTurrets = Math.min(8, 4 + Math.floor(waveNumber / 3));
    const ids = arena.placeTurrets({
        botManager, fpsShooter,
        maxTurrets,
        groundY: 5,    // typical OGRE arena ground level
        models: window._libDefenderModels,   // v1374 — downloaded civDefender bodies
    });
    _ogreTurretIds = ids || [];
    console.log(`[OgreArena] wave ${waveNumber}: ${_ogreTurretIds.length} turrets deployed`);
};
