// Round 226 — automatic mini-boss spawn on every Nth level. Hooked
// via a wrapper around fpsShooter.start so it fires after bots have
// already populated the layout. BOSS_LEVEL_INTERVAL = 3 means levels
// 3, 6, 9, 12, ... each get a single mini-boss in the exit room.
// Override window._fpsBossInterval to change cadence.
const _origFpsStartForBoss = fpsShooter.start.bind(fpsShooter);
fpsShooter.start = async function(opts = {}) {
    const r = await _origFpsStartForBoss(opts);
    const interval = window._fpsBossInterval || 3;
    if (fpsShooter.levelNumber > 0 &&
        fpsShooter.levelNumber % interval === 0 &&
        ollamaLevelGen?._lastLevel) {
        // Brief delay so the dungeon lore overlay has time to land first
        setTimeout(async () => {
            try {
                await botManager.spawnMiniboss(ollamaLevelGen._lastLevel);
                console.log(`[FPS] LV ${fpsShooter.levelNumber} — mini-boss spawned`);
            } catch (e) {
                console.warn("[FPS] miniboss spawn failed:", e?.message ?? e);
            }
        }, 1400);
    }
    return r;
};

// Round 231 — mid-fight boss phase shifts. When the mini-boss drops
// to 50% HP, it teleports to a different room and spawns 3 kaiju
// minions where the player is. The boss is invulnerable while
// minions are alive. Clear them all to expose the boss again.
const bossPhaseManager = new BossPhaseManager({
    fpsShooter, botManager, ollamaLevelGen,
    camera,
    kpop,
    audio: audio?.audio ?? null,
    ecsWorld: window.ecsWorld ?? null,
});
window.bossPhase = {
    phase: () => bossPhaseManager.getPhase(),
    stats: () => bossPhaseManager.getStats(),
};
console.log("[BOSS-PHASE] type 'bossPhase.phase()' or '.stats()' to inspect");

// Round 235 — vision modes. Press V (during FPS) to cycle through
// normal / night-vision / flashlight / heat / x-ray / soul-tracker.
// Each mode applies a canvas CSS filter and/or a HUD overlay.
//   heat/xray/soul show enemies (and pickups for xray) on a compass
//   strip projected from camera yaw, so you can see things through
//   walls. flashlight darkens the world and gives a transparent cone
//   at screen center.
const visionModes = new VisionModes({
    camera, fpsShooter, ollamaLevelGen,
});
// Round 244 — patch back-ref so health pickups can refill the vision
// battery (matches the spaceSuit/kaijuMode/swimMode back-ref pattern)
fpsShooter.visionModes = visionModes;
window.vision = {
    set:    (m) => visionModes.set(m),
    cycle:  () => visionModes.cycle(),
    current: () => visionModes.current(),
    list:   () => visionModes.listModes(),
};
console.log("[VISION] press V during FPS to cycle modes. console: vision.set('heat'|'xray'|'night_vision'|...)");

// Round 232 — pressure-plate spawn_bots action delegates to
// BotManager.spawn so FPSShooter doesn't have to know about it.
// Spawns 2-3 kaiju-or-grunt bots at the target xz (or near plate if
// no target). Mix of kinds for ambush variety.
fpsShooter.onPlateAction(({ action, target, plate }) => {
    if (action !== "spawn_bots") return;
    const tx = target?.x ?? plate.x;
    const tz = target?.z ?? plate.z;
    const layout = ollamaLevelGen?._lastLevel;
    // If target.roomId is given, spawn at that room's center instead
    let spawnX = tx, spawnZ = tz;
    if (target?.roomId && layout?.rooms) {
        const room = layout.rooms.find(r => r.id === target.roomId);
        if (room) { spawnX = room.x + room.w/2; spawnZ = room.z + room.d/2; }
    }
    const ambushKinds = ["bot_grunt", "bot_grunt", "bot_kaiju_hell", "bot_kaiju_cave"];
    const count = 2 + Math.floor(Math.random() * 2);   // 2 or 3
    for (let i = 0; i < count; i++) {
        const off = (Math.random() - 0.5) * 4;
        const kind = ambushKinds[Math.floor(Math.random() * ambushKinds.length)];
        botManager.spawn({ x: spawnX + off, z: spawnZ + off, kind });
    }
    console.log(`[plate] spawn_bots → ${count} bots at (${spawnX.toFixed(1)}, ${spawnZ.toFixed(1)})`);
});

// Round 217 — WadMap companion + replay.
const wadMap = new WadMap({
    camera, ollamaLevelGen, fpsShooter, botManager,
    bridge,
    kaijuManager, civManager,   // v446 — always-on radar markers
});
wadMap.start();
// v460 — sync minimap visibility to the boot demo (hidden unless it opts in).
try { wadMap.setVisible(demoManager.current?.minimap === true); } catch {}
// Round 270 — expose the wadMap instance so damage callsites can fire
// `window._wadMap?.addPulse(x, z)` for minimap impact rings without
// each caller threading the ref through constructors.
window._wadMap = wadMap;
window.wadmap = {
    startRecording: () => wadMap.startRecording(),
    stopRecording:  () => wadMap.stopRecording(),
    saveRecording:  () => wadMap.saveRecording(),
    loadRecording:  (obj) => wadMap.loadRecording(obj),
    play:    (opts) => wadMap.play(opts || {}),
    replay:  () => wadMap.replay(),
    stop:    () => wadMap.stop(),
    stats:   () => wadMap.getStats(),
    pulse:   (x, z, opts) => wadMap.addPulse(x, z, opts || {}),
    download: () => {
        const rec = wadMap.saveRecording();
        const blob = new Blob([JSON.stringify(rec, null, 2)], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `wadmap_replay_${Date.now()}.json`;
        a.click();
        URL.revokeObjectURL(url);
    },
    // Round 273 — upload a saved replay JSON. Opens a file picker;
    // on selection, parses the JSON and calls loadRecording. Doesn't
    // auto-play — caller must wadmap.play() after.
    upload: () => {
        return new Promise((resolve) => {
            const input = document.createElement("input");
            input.type = "file";
            input.accept = "application/json,.json";
            input.addEventListener("change", async () => {
                const file = input.files?.[0];
                if (!file) { resolve(null); return; }
                try {
                    const text = await file.text();
                    const obj = JSON.parse(text);
                    const ok = wadMap.loadRecording(obj);
                    console.log(ok ? `[wadmap] loaded replay (${obj.frames?.length ?? 0} frames). Call wadmap.play() to view.`
                                   : "[wadmap] loadRecording rejected the file");
                    resolve(ok ? obj : null);
                } catch (e) {
                    console.warn("[wadmap] upload parse failed:", e);
                    resolve(null);
                }
            });
            input.click();
        });
    },

    // Round 273 — seeded WAD generation. The level generator uses
    // Math.random() directly (no seed param plumbed through), so we
    // temporarily monkey-patch Math.random with a seeded LCG, call
    // the generator, then restore. Deterministic from the same seed.
    // Use case: portfolio reproducibility ("show me WAD #42 again").
    //
    // Usage: wadmap.seed(12345)  →  regenerates with that seed.
    //        wadmap.seed()       →  random seed (logs which one).
    seed: (seed) => {
        if (typeof ollamaLevelGen?.generate !== "function") {
            console.warn("[wadmap] no level generator available");
            return null;
        }
        if (seed === undefined || seed === null) {
            seed = Math.floor(Math.random() * 0xFFFFFFFF);
        }
        seed = (seed >>> 0) || 1;
        const original = Math.random;
        // Mulberry32 — small, fast, good enough for level layout
        let s = seed;
        Math.random = function () {
            s = (s + 0x6D2B79F5) >>> 0;
            let t = s;
            t = Math.imul(t ^ (t >>> 15), t | 1);
            t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
        try {
            console.log(`[wadmap] seeding generator with ${seed}`);
            ollamaLevelGen.generate();
        } catch (e) {
            console.warn("[wadmap] seeded generate failed:", e);
        } finally {
            Math.random = original;
        }
        return seed;
    },

    // Round 273 — auto-cycle tour. Generates a sequence of N WAD
    // levels with random seeds, switching between them every {dwell}
    // seconds. Each transition logs the seed so the user can pin a
    // favourite via wadmap.seed(seed). Stops automatically after N
    // levels, or call wadmap.stopTour() to cancel early.
    tour: ({ levels = 5, dwell = 25 } = {}) => {
        if (window._wadmapTourTimer) {
            console.warn("[wadmap] tour already running — wadmap.stopTour() to cancel");
            return;
        }
        let i = 0;
        const cycle = () => {
            if (i >= levels) {
                console.log(`[wadmap] tour complete — ${levels} levels shown`);
                window._wadmapTourTimer = null;
                return;
            }
            const seed = window.wadmap.seed();   // random + log
            console.log(`[wadmap] tour ${i + 1}/${levels} — seed ${seed}`);
            i++;
            window._wadmapTourTimer = setTimeout(cycle, dwell * 1000);
        };
        cycle();
    },
    stopTour: () => {
        if (window._wadmapTourTimer) {
            clearTimeout(window._wadmapTourTimer);
            window._wadmapTourTimer = null;
            console.log("[wadmap] tour cancelled");
        }
    },
};
console.log("[WADMAP] minimap top-right · open /wadmap.html in a second tab for the companion view");
console.log("[WADMAP] wadmap.startRecording() / wadmap.stopRecording() / wadmap.play() / wadmap.download()");

