// Round 220 — Ollama-generated atmospheric narration on every WAD level
// start. Subscribes to fpsShooter via a wrapper around start(): we keep
// the original method and prepend a lore.narrate(wadLevel) call. The
// narration plays in parallel — KPop TTS + toast + centered overlay
// card — and runs while the level loads, so by the time the player can
// move, the intro fade-out is already underway.
const dungeonLore = new DungeonLore({ ollama, kpop });
window.lore = {
    narrate: (desc) => dungeonLore.narrate(desc),
    recent:  () => dungeonLore.recent(),
    last:    () => dungeonLore.last(),
    setEnabled: (on) => dungeonLore.setEnabled(on),
    stats:   () => dungeonLore.getStats(),
};

// Wrap fpsShooter.start so every WAD level triggers lore. We can't
// modify the FPSShooter source here, so we monkey-patch the instance.
// The original .start is bound to fpsShooter so `this` still resolves
// inside it.
const _origFpsStart = fpsShooter.start.bind(fpsShooter);
fpsShooter.start = async function (opts = {}) {
    const r = await _origFpsStart(opts);
    // Only narrate WAD-generated levels (skip the "no level" / open case)
    if (opts.wadLevel) {
        // Fire-and-forget; don't await — lore is decoration, not blocking
        // Round 222 — pass level number so deeper dungeons get more oppressive narration
        dungeonLore.narrate(opts.wadLevel, fpsShooter.levelNumber).catch(() => {});
    }
    return r;
};
console.log("[LORE] dungeon narrator wired — each new WAD level gets Ollama-generated flavor text");


