// be readable from inside POV (F-key OGRE-camera mode) where the docked
// crew panel at bottom-right might be out of attention.
const crewCallout = new CrewCallout({ parent: document.body });
ogreCrewPanel.onStateChange = (def, oldState, newState) => {
    crewCallout.fireTransition(def, oldState, newState);
};
if (typeof window !== "undefined") {
    window.ogreCrewPanel = ogreCrewPanel;
    window.ogreScenario = ogreScenario;
    window.crewCallout = crewCallout;
}

// Visibility coordinator — polls 4Hz. Cheap enough; ogreScenario.ogre
// is a single null-check. When it transitions present↔absent, swap
// which avatar stack is showing.
(() => {
    let lastOgreActive = null;   // null = unknown, bool after first observation
    // Stash HeartbeatAvatar root by ID since it doesn't expose a setter.
    const hbEl = document.getElementById("ollama-heartbeat-avatar");
    let palChatWasEnabled = false;
    let hbWasVisible = true;
    setInterval(() => {
        const ogreActive = !!(ogreScenario?.ogre && ogreScenario.ogre.state !== "dying");
        if (lastOgreActive !== ogreActive) {
            if (ogreActive) {
                // Capture previous visibility states so we can restore later
                palChatWasEnabled = palChat.isEnabled();
                const hb = document.getElementById("ollama-heartbeat-avatar");
                hbWasVisible = hb ? (hb.style.display !== "none") : true;
                // Hide normal avatars, show crew
                if (hb) hb.style.display = "none";
                palChatAvatar.setEnabled(false);  // hides the panel
                // palChat itself stays enabled internally so it keeps
                // generating dialogue when OGRE crew panel takes over;
                // dialogue just won't render visually. That's fine —
                // crew panel doesn't need M1/M2 chatter on screen.
                ogreCrewPanel.setVisible(true);
                // Round 105 — Pip becomes "PIP the OGRE" while a
                // scenario runs (and reverts on end).
                if (tamagotchi?.setName) tamagotchi.setName("PIP the OGRE");
            } else {
                // Restore previous visibility
                ogreCrewPanel.setVisible(false);
                const hb = document.getElementById("ollama-heartbeat-avatar");
                if (hb && hbWasVisible) hb.style.display = "";
                if (palChatWasEnabled) palChatAvatar.setEnabled(true);
                if (tamagotchi?.setName) tamagotchi.setName("PIP the Listener");
            }
            lastOgreActive = ogreActive;
        }
        // Always update HP readouts while visible
        if (ogreActive) ogreCrewPanel.update();
    }, 250);
})();

// Round 101 — Ollama state-transition triggers for PalChat. Subscribes
// to the existing onActivity stream (which fires for every started/
// completed/failed/unreachable event) and debounces transitions so
// the dog and person only comment on big state shifts — not every
// completion. Specifically: when Ollama goes from "alive" to
// "unreachable", fire once. When it comes BACK after being unreachable,
// fire once. Skip everything in between.
(() => {
    if (!ollama?.onActivity) return;
    let lastOnlineState = null;  // null = unknown, true = alive, false = unreachable
    let lastTransitionMs = 0;
    const minTransitionGap = 30_000;  // 30s — survive a brief network hiccup without spamming
    ollama.onActivity((event) => {
        const now = performance.now();
        let nowOnline = null;
        if (event === "completed" || event === "started")  nowOnline = true;
        else if (event === "unreachable" || event === "failed") nowOnline = false;
        if (nowOnline === null) return;
        if (lastOnlineState === null) {
            // First observation — just remember; don't comment on it
            lastOnlineState = nowOnline;
            return;
        }
        if (lastOnlineState === nowOnline) return;
        if (now - lastTransitionMs < minTransitionGap) return;
        lastTransitionMs = now;
        lastOnlineState = nowOnline;
        if (!palChat?.isEnabled?.()) return;
        if (nowOnline) {
            palChat.generate("Ollama just came back online after being unreachable for a while.");
        } else {
            palChat.generate("Ollama just went offline — the LLM connection dropped.");
        }
    });
})();

// Round 93 — kick off the meta-loop on startup. Fire-and-forget:
//   1. Ask asset loader for the heartbeat_mascot. It's not on disk
//      yet, so the loader's _maybeRequestFromOllama path triggers a
//      generation request to Ollama (currently routed to C3D).
//   2. C3D produces an OBJ from the heartbeat_mascot_v1 description
//      we registered in assetVariants.
//   3. ai-bridge saves to GPU_Assets/.
//   4. Asset loader's onMeshReplaced fires; HeartbeatAvatar receives
//      the event, switches body from SVG cat to 3D mesh.
// If the bridge/Ollama is down at startup, all this fails silently;
// the SVG avatar continues working.
(async () => {
    try {
        // Small delay so the variant description registration completes first
        await new Promise(r => setTimeout(r, 500));
        if (assetLoader?.loadAsset) {
            assetLoader.loadAsset("heartbeat_mascot_v1");
        }
        // Round 101 — fire palchat_dog_v1 with extra stagger so the
        // heartbeat mascot request lands first (avoids competing C3D
        // jobs on resource-constrained Ollama setups). When the dog
        // OBJ arrives, PalChatAvatar's onMeshReplaced subscription
        // upgrades the M2 slot from SVG to 3D automatically.
        await new Promise(r => setTimeout(r, 800));
        if (assetLoader?.loadAsset) {
            assetLoader.loadAsset("palchat_dog_v1");
        }

        // Round 125 — try to load rigged GLBs for each kaiju kind. The
        // KaijuManager._tryAttachMesh path looks them up by name
        // `kaiju_<kind>` and attaches them as mesh entities. If the
        // file doesn't exist on disk the load fails silently and the
        // kaiju falls back to obelisk rendering. To enable a rigged
        // kaiju kind, drop e.g. `kaiju_tech.glb` into GPU_Assets/.
        //
        // These fire in parallel with a small stagger to avoid bursting
        // the asset loader. Each tries to load; failures are logged at
        // the loader level and don't block the engine.
        //
        // Round 165 (v660) — gated behind the same lean-boot check used
        // elsewhere. assetLoader.loadAsset triggers the full AI generation
        // pipeline (Ollama C3D → texture → Trellis → Hitem3D → Kaggle)
        // for any name not already on disk, which means firing it for 8
        // kaiju kinds on blank_sandbox boot kicks off ~80MB of GPU work
        // the user never asked for. Now only pre-warms when the demo is
        // actually a kaiju-using demo. Other demos that need the rigged
        // meshes will get them via the regular acquire path on first use.
        await new Promise(r => setTimeout(r, 800));
        const _kaijuDemos = new Set([
            "kaiju", "kaiju_roster", "ecosystem_enemies", "neural_enemies",
            "kaiju_city", "sandbox_gameplay", "satellite_strike_showcase",
            "hellgate", "snow_ogre",
        ]);
        const _currentDemo = (typeof want === "string" ? want : (window.__currentDemo || ""));
        if (assetLoader?.loadAsset && _kaijuDemos.has(_currentDemo)) {
            const kaijuKinds = ["sky", "hell", "space", "water", "frost", "underground", "cave", "tech"];
            for (const kind of kaijuKinds) {
                assetLoader.loadAsset(`kaiju_${kind}`).catch(() => {
                    // 404 / missing file is expected for kinds without a
                    // rigged GLB; the kaiju falls back to obelisk
                    // rendering automatically.
                });
            }
        } else {
            console.log(`[main] kaiju preload skipped — demo "${_currentDemo}" isn't kaiju-using. Kaiju kinds will acquire on first use.`);
        }
    } catch (e) {
        console.warn("[heartbeat] mascot kickoff failed:", e);
    }
})();

// Round 97 — sample KPop wire-up. When the heartbeat mascot finishes
// its C3D round-trip and the 3D mesh becomes available, fire a one-shot
// toast announcing it. Only sent when KPop Toasts toggle is on (the
// client's enabled flag gates this internally). Wired here rather than
// inside HeartbeatAvatar so each engine subsystem can keep its KPop
// hooks visible at the top-level integration layer.
//
// Round 100 — same trigger ALSO kicks a PalChat exchange. The M1↔M2
// pair comments on the new mascot — M1 thoughtfully, M2 doggily.
// PalChat internally checks its own enabled flag, so this is a no-op
// when PalChat is off.
(() => {
    let alreadyToasted = false;
    if (assetLoader?.onMeshReplaced) {
        assetLoader.onMeshReplaced((name) => {
            if (alreadyToasted) return;
            if (name === "heartbeat_mascot_v1" || name === "heartbeat_mascot_v2") {
                alreadyToasted = true;
                kpop.success("Mascot ready",
                    `C3D generated ${name} — heartbeat avatar now in 3D mode.`);
                // Round 100 — PalChat reacts in dialogue
                palChat.generate(`A new mascot named "${name}" just finished rendering in 3D for the first time.`);
            }
        });
    }
})();


