        const skip = document.createElement("button"); skip.textContent = "Skip for now"; skip.style.cssText = "padding:10px 16px;border-radius:9px;border:1px solid #2a3340;background:#16202c;color:#cde;cursor:pointer;font:13px ui-monospace,monospace;";
        const go = document.createElement("button"); go.textContent = "Get started \u2192"; go.style.cssText = "padding:10px 18px;border-radius:9px;border:1px solid #2bff88;background:#0c3;color:#021;font-weight:bold;cursor:pointer;font:13px ui-monospace,monospace;";
