// ===================== v1224 — engine FPS -> avatar mood ========================
// The avatar's mood sours as the engine bogs down and goes to full alarm when it
// stalls. Self-contained: peeks the shared mood bus (no quip drain) so it won't
// stomp a more-severe mood pushed by PowerShell/another device, and only clears
// moods IT raised (reason prefixed "engine"). PowerShell + phone can still drive
// mood independently via /avatar/mood.
(function fpsEnginePublish(){
  // v1269 (#6) — publish the engine's OWN first-person camera to /fps/state, so the VBA
  // mirror + fpsmirror.html reflect the real game camera instead of the fpscontrol.html
  // stand-in. Engine forward is (sin yaw, sin pitch, -cos yaw·); the bridge/mirror use
  // three.js YXZ (-sin yaw, .., -cos yaw), so we publish yaw = -camera.yaw, pitch as-is.
  let enabled = false, timer = null, last = null, lastT = 0;
  function tickPub(){
    const c = window.camera; if (!c || !c.position) return;
    const now = performance.now();
    const pos = [c.position.x, c.position.y, c.position.z];
    let vel = [0, 0, 0];
    if (last && now > lastT){ const dt = (now - lastT) / 1000; if (dt > 0){ vel = [(pos[0]-last[0])/dt, (pos[1]-last[1])/dt, (pos[2]-last[2])/dt]; } }
    last = pos; lastT = now;
    try { fetch("/fps/state", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ pos, yaw: -c.yaw, pitch: c.pitch, vel, src: "engine" }) }).catch(() => {}); } catch (e) {}
  }
  function start(){ if (timer) return; enabled = true; timer = setInterval(tickPub, 33); console.log("[fps] engine camera -> /fps/state @30Hz"); }
  function stop(){ enabled = false; if (timer){ clearInterval(timer); timer = null; } }
  window.fpsPublish = { start, stop, force(on){ window._fpsForce = !!on; if (on) start(); else stop(); }, get enabled(){ return enabled; } };
  // auto-publish whenever the engine enters first-person mode ("fp"); manual force overrides.
  setInterval(() => {
    if (window._fpsForce) return;
    const m = window.camera && window.camera.mode;
    if (m === "fp" && !enabled) start(); else if (m !== "fp" && enabled) stop();
  }, 1000);
  // tiny self-contained toggle (force publish even in observer mode) + status dot
  try {
    addEventListener("DOMContentLoaded", () => {
      const b = document.createElement("button");
      b.textContent = "📡 FPS→mirror";
      b.title = "Publish this engine camera to /fps/state (VBA + fpsmirror.html). Auto-on in first-person.";
      b.style.cssText = "position:fixed;right:8px;bottom:8px;z-index:99998;font:12px system-ui;padding:5px 9px;border-radius:7px;border:1px solid #2a6;background:#0b1a12;color:#7fe0a0;opacity:0.5;cursor:pointer";
      const sync = () => { b.style.opacity = enabled ? "1" : "0.5"; b.style.borderColor = enabled ? "#5fd08a" : "#244"; };
      b.addEventListener("click", () => { window.fpsPublish.force(!enabled); sync(); });
      setInterval(sync, 1000); document.body.appendChild(b);
    });
  } catch (e) {}
})();
(function moodFromFps(){
  let low = 0, ok = 0, lastPosted = null, lastQuiet = null;
  const post = (mood, reason) => {
    lastPosted = mood;
    try { fetch("/avatar/mood", { method:"POST", headers:{ "Content-Type":"application/json" }, body: JSON.stringify({ mood, reason, score: mood==="alarm"?0.05:mood==="souring"?0.45:1.0 }) }); } catch (e) {}
  };
  // v1230 — engine authority: quiet the listener when the engine is busy, un-quiet on
  // recovery. Posts only on change so we don't spam the policy bus.
  const postQuiet = (quiet, reason) => {
    if (quiet === lastQuiet) return; lastQuiet = quiet;
    try { fetch("/kpop/policy", { method:"POST", headers:{ "Content-Type":"application/json" }, body: JSON.stringify({ quiet, reason }) }); } catch (e) {}
  };
  setInterval(async () => {
    if (window.__swekPollsPaused) return;   // v1870 — hold while Settings is open
    const fps = (window._perfStats && window._perfStats.fps) || 0;
    if (fps <= 0) return;                       // not measured yet / page hidden
    if (fps < 14) { low += 2; ok = 0; }
    else if (fps < 32) { low += 1; ok = 0; }
    else { ok += 1; low = Math.max(0, low - 1); }
    let want = null;
    if (low >= 6) want = "alarm";
    else if (low >= 3) want = "souring";
    else if (ok >= 3) want = "support";
    if (!want) return;
    let cur = null;
    try { const r = await fetch("/avatar/mood?peek=1", { cache:"no-store" }); if (r.ok) cur = await r.json(); } catch (e) {}
    const curMood = cur && cur.mood, curReason = (cur && cur.reason) || "";
    const engineOwned = /^engine/.test(curReason);   // did we set the current mood?
    if (want === "support") {
      // only relax back to support if WE soured it (don't clobber an external mood)
      if (engineOwned && curMood !== "support" && lastPosted !== "support") post("support", "engine fps recovered");
      postQuiet(false, "engine fps recovered");   // v1230 — let the listener speak again
    } else {
      const rank = { support:0, souring:1, alarm:2 };
      // escalate freely; only downgrade severity if we own it
      if (curMood == null || rank[want] > (rank[curMood] || 0) || engineOwned) {
        if (curMood !== want || lastPosted !== want) post(want, "engine fps " + Math.round(fps));
      }
      if (want === "alarm") postQuiet(true, "engine busy (low fps)");   // v1230 — hush the listener while struggling
    }
  }, 5000);
})();

